quests[29258] = { id = 29258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meteoritenjagd" }
quests[29261] = { id = 29261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Aman Voodoo", progress = "Der Erschaffer dieses Voodoohaufens ist während des Vorgangs gestorben. Wenn Ihr ihn jedoch abschließen könntet, würden die Geister Euch vielleicht beschützen...", completion = "Die Schrifttafel enthält den letzten Zauberspruch, um die Magie des Voodoohaufens an Euch und Eure Gruppe zu binden!" }
quests[29262] = { id = 29262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Gurub Voodoo", progress = "Dieser mächtige Haufen Voodoohexenkunst verströmt starkes Mojo...", completion = "Als Ihr die Tafel in den Voodoohaufen steckt, zerreißt ein markerschütternder Schrei die Stille." }
quests[29263] = { id = 29263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine bittere Pille", description = "Soweit es mich betrifft, gibt es kein Problem, das nicht mithilfe von Bomben gelöst werden kann. Und wenn eine Bombe das Problem nicht beim ersten Versuch löst... dann muss man eben eine größere Bombe nehmen.\n\nEs gibt da also diesen großen Wurm, der Leute bei der Lavapfütze im Norden frisst. Haltet Ausschau nach Luftblasen, um ihn zu finden. Greift ihn an, bis er sich bereit macht, zuzubeißen, und platziert dann die Bombe vor ihm. Und dann könnt Ihr Euch zurücklehnen und das Feuerwerk genießen.\n\nHmm... es gab noch eine andere Sache, die ich sagen wollte... Ach ja! Lasst Euch nicht fressen.", sourceObjective = "Findet die Luftblasen des unterirdischen Magmawurms und besiegt ihn dann, indem Ihr ihn die bittere Pille schlucken lasst.", completion = "Ah, ich wusste, dass Rickets Bomben noch einmal nützlich sein würden. Es war nur eine Frage, ob wir etwas ausreichend Großes zum in die Luft sprengen finden würden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29264] = { id = 29264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flammenschürer des Geschmolzenen Stroms", description = "Von allen Dienern Ragnaros' scheinen die Flammenschürer die hingebungsvollsten zu sein. Die meisten von ihnen weilen in dieser Höhle und bereiten sich auf einen weiteren Angriff vor. Wir haben hier vielleicht eine recht sichere Stellung, aber wir werden keine Überraschungsangriffe von diesem Gewürm tolerieren.\n\nNein, wir werden als erste zuschlagen.\n\nReißt sie in Stücke, {name}.", sourceObjective = "Erschlagt 8 Flammenschürer im Geschmolzenen Strom.", completion = "Mir gefällt, wie Ihr arbeitet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29265] = { id = 29265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerblumen", description = "Meine Kollegin, Choluna, hat uns gebeten, alles, was wir an pflanzlichem Leben in den Feuerlanden finden, einzusammeln...\n\n... Ich weiß nicht, wessen Idee es war, Wissenschaftler an eine Kriegsfront zu schicken.\n\nNichtsdestotrotz, da Ihr nun schon mal in der Höhle sein werdet - und Dinge tötet - könnt Ihr auch genauso gut Ausschau nach Dingen halten, die am Boden wachsen.", sourceObjective = "Sammelt 5 Luzifarne.", progress = "Sie können überall wachsen. Haltet die Augen offen.", completion = "Diese Dinge werden nie aufhören, mich in Staunen zu versetzen. Ob sie nun wirklich Pflanzen sind oder einfach nur feingliedrige Steinformationen... der Umstand, dass sie unter solch feindlichen Bedingungen wachsen können, verblüfft mich einfach nur.\n\nIch muss sie sofort an Avrilla zur Analyse schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[29267] = { id = 29267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glück im Unglück", description = "So viel Gewalt, so viel Tod. Brüder sind gestorben, eine Mutter ist gestorben und nun wird ein Pantherjunges sterben, wenn sich niemand seiner annimmt.\n\nWerdet Ihr Euch für einen Moment von der Gewalt abwenden und für ein Pantherjunges sorgen?", sourceObjective = "Das Pantherkätzchen sieht Euch mit einem Ausdruck an, der sagt \"Bist du mein neuer Papa?\"", sourceObjectiveStatus = "unverified-source-field" }
quests[29268] = { id = 29268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glück im Unglück", description = "So viel Gewalt, so viel Tod. Brüder sind gestorben, eine Mutter ist gestorben und nun wird ein Pantherjunges sterben, wenn sich niemand seiner annimmt.\n\nWerdet Ihr Euch für einen Moment von der Gewalt abwenden und für ein Pantherjunges sorgen?", sourceObjective = "Kümmert Euch um das Pantherjunge. Schließlich habt Ihr seine Mutter auf dem Gewissen.", completion = "Das Pantherkätzchen sieht Euch mit einem Ausdruck an, der sagt \"Bist du mein neuer Papa?\"", sourceObjectiveStatus = "unverified-source-field" }
quests[29269] = { id = 29269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vereint", description = "Ich war mit ihrer Sicherheit betraut, und doch war sie es, die sich für mich opferte.\n\nIch ertrage es nicht, sie zu verlieren, {name}. Ich muss Euch eine entscheidende Bitte stellen.\n\nNoch nie hat ein Sterblicher die Essenz eines wahren Drachen getragen, doch mit Eurer Erlaubnis würde ich eine Ausnahme machen.\n\nBitte, solange noch etwas Leben in ihr verweilt, erlaubt mir Tarecgosa an Euch zu binden.", sourceObjective = "Sprecht mit Kalecgos, um der Bitte zuzustimmen.", completion = "Ich bin dankbar, {name}.\n\nWärt Ihr nicht gewesen oder hättet Ihr abgelehnt, wäre Tarecgosa für mich für immer verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[29270] = { id = 29270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zeit drängt", description = "Tarecgosa ist an Euch gebunden, {name}, aber nur auf begrenzte Zeit. Die Macht eines Aspekts ist von Nöten, um ihre Essenz permanent zu versiegeln.\n\nMalygos' Nachfolger wird nicht vor der nächsten Mondfinsternis Azeroths bestimmt und der Bund, den Ihr mit ihr teilt wird nicht so lange überdauern.\n\nGlücklicherweise gibt es eine Möglichkeit, uns die nötige Zeit zu verschaffen. Es gibt mächtige Elemente, die die Dauer des Rituals verlängern können. Einige davon können in der Ebene des Feuers gefunden werden, mit der Ihr bereits vertraut seid.\n\nBesorgt sie, {class}, und haltet Tarecgosa bis zur Mondfinsternis aufrecht.", sourceObjective = "Sammelt 1000 Einheiten siedender Schlacke aus den Feuerlanden.", progress = "Es tut gut, Euch wiederzusehen, {name}.", completion = "Ich spüre, dass Tarecgosa noch immer bei Euch ist.\n\nDas habt Ihr gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[29271] = { id = 29271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ound for Warmer Weather" }
quests[29272] = { id = 29272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brauche... Wasser... Dringend...", description = "Brauche... Wasser... Dringend...", sourceObjective = "Bringt Anren Schattensucher zum Eingang der Geschmolzenen Front.", completion = "Ihr! Ihr seid derjenige, der Anren gerettet hat. Meinen besten Freund Anren.\n\nWir sind in dieser Höhle getrennt worden. Ich wusste nicht, wie ich ohne Anren weitermachen sollte.\n\nIhr seid ein einfallsreicher {class}. Vielleicht werden wir Euch später noch einmal um Unterstützung bei unseren Erkundungsmissionen bitten. Mit Eurer Hilfe werden Anren und ich möglicherweise nicht länger mit dem entsetzlichen Risiko leben müssen, voneinander getrennt zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29273] = { id = 29273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie heiß", description = "Die Feuerfalken des Schwarzrauchgipfels können unglaublichen Temperaturen widerstehen. Man kann sie sowohl dabei beobachten, wie sie am Himmel ihre Kreise ziehen, als auch dabei, wie sie in flüssiger Lava schwimmen.\n\nStimmt doch, oder, Anren?\n\nWir würden gerne wissen, wie heiß diese Lava werden kann. Der Schwarzrauchgipfel verfügt über drei große Lavaseen. Benutzt dies, um in jedem von ihnen die Temperatur zu messen.", sourceObjective = "Benutzt Tholos Thermometer, um die Temperatur in den drei großen Lavaseen des Schwarzrauchgipfels zu messen.", completion = "Diese Ergebnisse werden uns sehr dabei helfen, die Feuerfalken besser zu verstehen und - noch wichtiger - Alysrazar, ihre neue, feurige Königin.\n\nTholo und ich sind dankbar, dass Ihr uns hier ausgeholfen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29274] = { id = 29274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hunde von Shannox", description = "Auf der größten Insel der Feuerlande haben unsere Truppen Probleme im Kampf gegen Shannox, den Jäger der Flammenschürer. Er verfügt nicht nur über unfehlbare Zielgenauigkeit, sondern er hält sich auch abgerichtete Hunde, die unseren Truppen Ärger ohne Ende bereiten.\n\nTholo, in seiner Weisheit, glaubt, dass es eine gute Idee wäre, die Biologie dieser Hunde zu studieren. Ich stimme natürlich mit Tholo überein.\n\nIhr werdet mehrere Hunde im Geschmolzenen Strom finden, unterhalb des Schmelzofens. Wir werden ihre Asche für unsere Studien benötigen.", sourceObjective = "Sammelt 6 kleine Haufen Asche von Hundeknochen.", progress = "Jede Information, die wir kriegen können, wird hilfreich sein, wenn wir unseren Männern helfen wollen, Shannox zu bezwingen.", completion = "Diese Asche mag genauso aussehen wie alle anderen Arten von Asche, die man auf dieser gottverlassenen Insel findet, aber vertraut mir... Ihr habt das richtige Zeug gefunden.\n\nWir werden es sofort untersuchen lassen.\n\nKehrt bald zurück. Ich verbringe zwar gerne Zeit mit Anren, aber Eure Gesellschaft ist uns auch sehr angenehm, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29275] = { id = 29275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fandrals Methoden", description = "Die Druiden der Flamme... ein Orden von Druiden von dem Tholo und ich bis vor wenigen Wochen noch niemals gehört hatten. Und nun, unter der Führerschaft von Fandral Hirschhaupt, bedrohen sie den Erfolg unserer Mission mit ihrer Herrschaft über das Feuer.\n\nEs scheint, als würden sie einige Ausrüstungsgegenstände in den Feurigen Tiefen aufbewahren, im Nordosten. Wenn es uns gelingt, in den Besitz von einigen Teilen dieser Ausrüstung zu gelangen, haben wir vielleicht mehr Glück, wenn wir den Kampf zu Fandral tragen.", sourceObjective = "Beschafft Euch einen Flammendruidenstab, ein Flammendruidenzauberbuch, einen Flammendruidenreagenzienbeutel sowie einen Flammendruidengötzen.", progress = "Vertraut mir - alle Informationen, die wir hier sammeln, werden uns sehr dabei helfen, zu verstehen, was die Quelle für Fandrals Macht ist.", completion = "Anren, seht was {name} entdeckt hat! Das ist genau das, was wir brauchen!\n\nWir werden einige Zeit brauchen, um diese Ausrüstung anzusehen. In der Zwischenzeit ist Euch unser Dank gewiss.", sourceObjectiveStatus = "unverified-source-field" }
quests[29276] = { id = 29276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flammenspinnenkönigin", description = "Das Gelege der Witwe, im Nordosten, ist nach Beth'tilac benannt, der riesigen Königin der Flammenspinnen. Ihre Netze und ihr Gift sind eine nagende Bedrohung unserer Hauptoffensivkraft.\n\nWir glauben, wenn wir die Flammenspinnen hier an der Geschmolzenen Front studieren, dann können wir diese Information einsetzen, um einen Erfolg gegen Beth'tilac zu erzielen. Setzt alle Euch zur Verfügung stehenden Methoden ein, um Proben ihres Gifts und ihrer Spinnenseidenflüssigkeit zu sammeln und kehrt dann zu meinem getreuen Freund Anren zurück.", sourceObjective = "Sammelt 8 Proben Flammengift und 8 Proben sengende Spinnenseidenflüssigkeit.", progress = "Seid vorsichtig mit diesen Flüssigkeiten, {name}. Wir wollen doch nicht, dass etwas davon verschüttet wird.", completion = "Ihr seid ein echter Gewinn für unsere Sache, {name}. Tholo und ich danken Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[29278] = { id = 29278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebendes Obsidium", description = "Habt Ihr diese Feuerbälle gesehen, die vom Himmel kommen? Ich habe gesehen, wie einer von ihnen in die Felder im Norden eingeschlagen ist und das Gestein, was da gelandet ist, bestand aus purem Lebendem Obsidium!\n\nIch kann das Material benutzen, um ultra-robuste, hitzebeständige Rüstung und Waffen für unsere Truppen herzustellen. Könntet Ihr mir das Erz bringen?\n\nGeht zu den Magmaquellen und berührt einen der magnetischen Steine. Passt nur auf, wo Ihr steht, wenn der Feuerregen herunterkommt, und sammelt das Gestein ein, bevor es durch den Aufprall zerbricht.", sourceObjective = "Sammelt 10 Obsidiummeteoriten ein.", progress = "Wie geht es voran? Habt Ihr schon Meteoriten gefunden?", completion = "Fantastisch! Dann kann ich mich ja jetzt an die Arbeit machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29279] = { id = 29279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befüllung des Mondbrunnens", description = "Wir haben diesen Mondbrunnen erschaffen, doch erfüllt er wenig Zweck, solange er noch nicht mit den Wassern des Brunnens der Ewigkeit gefüllt wurde.\n\nMit einem aktiven Mondbrunnen wäre es uns möglich, unsere Lebensmittelvorräte zu segnen, zu denen Ihr selbstverständlich Zugang bekommen würdet. Es sollte uns auch möglich sein, den Segen des Mondbrunnens zu nutzen, um Euch Schutz vor dem Feuer zu gewähren.\n\nSobald Ihr genügend Abzeichen zusammen habt, solltet Ihr mit Matookla am Heiligtum von Malorne sprechen. Sie wird in der Lage sein, für den sicheren Transport des heiligen Wassers zu sorgen.", sourceObjective = "Sammelt 125 Abzeichen des Weltenbaums.", progress = "Wie kann ich Euch helfen, {name}?", completion = "Natürlich. Ich werde mich sofort darum kümmern, dass die heiligen Wasser durch das Portal gebracht werden.\n\nDanke, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29280] = { id = 29280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebensspendende Wasser", description = "Ich habe die Wasser des heiligen Mondbrunnens zu Malfurions Bresche gesandt, wie Ihr es gewünscht habt. Ayla ist gut darin ausgebildet, sich um sie zu kümmern. Ihr solltet zu ihr zurückkehren und sehen, welche Segen sie für Euch dort bereithält.", sourceObjective = "Sprecht mit Ayla Schattensturm bei Malfurions Bresche.", completion = "Es wird Euch freuen, zu hören, dass die Wasser hier sicher angekommen sind. Nun da der Mondbrunnen gefüllt ist und der Schatten des Wachenden Baums über uns liegt, kann ich manchmal sogar mehrere Momente lang vergessen, dass wir in den Feuerlanden sind.\n\nIch habe den Segen des Mondbrunnens auf diese Bäume und Büsche verteilt. Nehmt die Frucht mit Euch, bevor Ihr geht. Sie ist erfrischender als Ihr Euch vorstellen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29281] = { id = 29281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung", description = "Diesen Druiden fehlen die Werkzeuge, um ihre Aufgaben hier vernünftig zu erledigen. Ich hab' aber 'nen Kumpel beim Schrein des alten Hirschbocks, auf der anderen Seite des Portals. Wenn wir uns wiedertreffen sollten, dann hätten wir sicher ein bisschen Spielzeug, das wir gegen Ragni und seine Kumpane einsetzen könnten.\n\nNehmt einige der Abzeichendinger und geht damit zu Matookla. Fragt sie nach Ricket. Wir brauchen sie hier, damit wir ordentlich Ärger anzetteln können.", sourceObjective = "Sammelt 125 Abzeichen des Weltenbaums.", progress = "Ja, {name}?", completion = "Ich hatte mich schon gefragt, ob sich diese zwei nicht noch als nützlich erweisen würden. Sie schienen recht fehl am Platz zu sein, seitdem sie angekommen sind.\n\nIch habe Ricket vor ein paar Augenblicken hier in der Gegend gesehen. Ich werde sie mit Vergnügen mit Euch zusammen durch das Portal schicken. Auf der Seite wird sie auch weniger Gefahr laufen, das lokale Pflanzenleben in die Luft zu sprengen.\n\nLasst mich mal sehen... wo ist sie...?", sourceObjectiveStatus = "unverified-source-field" }
quests[29282] = { id = 29282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut bewaffnet", description = "Ricket sollte zusammen mit Damek bei Malfurions Bresche sein, wie von Euch erbeten. Ich bin mir allerdings nicht sicher, dass Ihr wirklich wisst, worauf Ihr Euch mit den beiden einlasst.\n\nWo wir gerade davon sprechen: Ihr solltet vermutlich mal nach ihnen sehen... um sicherzugehen, dass sie es noch nicht geschafft haben, den Wachenden Baum in die Luft zu jagen. So lange Ihr sie mit Elementaren beschäftigt haltet, sollte die Wahrscheinlichkeit von \"Unfällen\" an der Bresche dramatisch sinken.", sourceObjective = "Sprecht mit Ricket bei Malfurions Bresche.", completion = "Hey Ihr! Gut, Euch wiederzusehen!\n\nIch habe mich hier eigentlich schon ganz gut eingelebt! Es ist schön, mal wieder Zeit mit dem guten alten Damek zu verbringen. Ich hätte nie gedacht, dass ich mich mal so gut mit einem Zwerg verstehen würde, aber was die wichtigen Dinge angeht, da liegen er und ich auf derselben Wellenlänge.\n\nMacht Ihr mal Euer Ding und sorgt Euch nicht um uns. Wenn wir irgendwelches nettes Spielzeug für Euch haben, dann werden wir es Euch wissen lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29283] = { id = 29283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rufen der Urtume", description = "Die Urtume warten in Hyjal. Die Feuerlande werden sich als gefährlicher Ort herausstellen, wenn man ihre... Zusammensetzung bedenkt, aber ihre Stärke wird uns sehr von Nutzen sein, wenn wir uns Ragnaros' Leutnants stellen müssen.\n\nSammelt Eure Abzeichen und sprecht mit Ahnenzweig am Heiligtum von Malorne. Wenn sie an unserer Seite marschieren sollen, so wäre er derjenige, der sie durch das Portal anführen würde.", sourceObjective = "Sammelt 125 Abzeichen des Weltenbaums.", progress = "Seid gegrüßt, junges Wesen.", completion = "Ich verstehe. Wir sind bereit. Wir werden uns dem Zug anschließen und Euch auf der am weitesten entfernten Seite des Portals treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29284] = { id = 29284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe der Urtume", description = "Die Urtume haben den Wert Eurer Weisheit erkannt und sich bei Malfurions Bresche niedergelassen. Ihr solltet Ahnenzweig aufsuchen. Ich bin sicher, er würde sich freuen, von Euch zu hören.", sourceObjective = "Sprecht mit Ahnenzweig bei Malfurions Bresche.", completion = "Ihr habt einen weisen Zeitpunkt ausgewählt, um zu uns zu kommen, {class}. Ich war besorgt gewesen, ob wir in diesem Reich gegen die Elemente bestehen könnten, aber der Schutz des Wachenden Baums hat sich als mehr als ausreichend erwiesen.\n\nWir werden alles tun, um Euch in Euren Bemühungen zu unterstützen. Dorrzweig hat sich mit Euren anderen Verbündeten getroffen und bespricht mit ihnen Wege, einige von Ragnaros' Leutnants in die Ecke zu treiben. Ihr solltet mit ihnen sprechen, wenn die Zeit gekommen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[29285] = { id = 29285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausrichtung", description = "Die Zeit der Wahl ist gekommen, {name}.\n\nObwohl nur Mitglieder des blauen Drachenschwarms dort erlaubt sind, macht die Bindung mit Tarecgosa Eure Anwesenheit dort erforderlich.\n\nIch muss Euch bitten, ihre Form anzunehmen und in ihrem Namen abzustimmen.\n\nTrödelt nicht, der Zeitpunkt der Mondfinsternis ist nahe...", sourceObjective = "Begleitet Kalecgos zum Konzil der blauen Drachen.\n\nSprecht mit Kalecgos in Kaltarra, wenn Ihr bereit seid.", progress = "Es ist vollbracht, {class}.", completion = "Arygos' Pläne wurden durchkreuzt, und zwar größtenteils wegen Eurer Mühen, {class}.\n\nAls meine erste Tat als Aspekt des blauen Drachenschwarms wird Euer Bund mit Tarecgosa nun ein stabiler sein.\n\nDie Macht, die diesen Bund einst getragen hat, übertrage ich nun in Euren Stab.\n\nMöge der Runenstab von Nordrassil Euch wohl dienen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29287] = { id = 29287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gipfel des Interesses", description = "Diese Feuerfalken sind Wesen aus Feuer, aber sie zeigen viel von dem Verhalten, dass wir auch bei den Vögeln in unserer Heimat beobachtet haben. Ich frage mich, was wohl ihr Ursprung sein mag.\n\nAber zurück zum Punkt - ich glaube, es könnte uns gelingen, sie abzurichten. Sie zähmen, wenn Ihr es so sagen wollt. Sie gegen unsere Feinde einsetzen.\n\nIch möchte, dass Ihr Euch eins ihrer Eier vom Schwarzrauchgipfel besorgt. Wenn Ihr es heil zu mir zurückbringt, werde ich mich um den Rest kümmern.", sourceObjective = "Besorgt ein Ei eines Feuerfalken von der Spitze des Schwarzrauchgipfels.", progress = "Ist es Euch gelungen, ein Ei zu besorgen?", completion = "Das wird perfekt funktionieren! Kommt in einem oder zwei Tagen wieder und wir werden sehen, wie sich die Dinge entwickelt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[29288] = { id = 29288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Junges Blut", description = "Unsere Späher kommen mit Berichten von Feuerfalkenjungen überall auf dem Gipfel zurück... ihre Eier müssen also vor Kurzem ausgebrütet worden sein. Und, was noch besser ist: sie scheinen extrem gelehrig zu sein.\n\nIch weiß, es mag sich wie eine seltsame und vielleicht auch geschmacklose Bitte anhören, aber wenn es Euch gelänge, ein paar dieser Jungtiere zu mir zu bringen, dann könnte ich sie vielleicht ausbilden, um uns in unseren Kriegsanstrengungen zu helfen.\n\nSeid Ihr willens?", sourceObjective = "Besorgt Euch 5 Feuerfalkenjunge.", progress = "Ich kann mich einfach nicht entscheiden, wie ich diese Kreaturen sehen soll. Sie verhalten sich genauso wie andere Vögel, aber sie sind ganz offensichtlich an diesem feurigen Ort heimisch.\n\nIch frage mich, warum Ragnaros und seine Diener keine Versuche unternommen haben, sie gegen uns einzusetzen...", completion = "Es sieht so aus, als hätten sie Eure Handschuhe ein wenig angesengt, aber ich sehe ansonsten keine weiteren Schäden. Gut gemacht, {class}.\n\nKommt in den nächsten paar Tagen wieder, um zu sehen, wie es mit der Ausbildung vorangeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[29289] = { id = 29289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sorgen einer Mutter", description = "Wenig überraschend hat die Matriarchin Anstoß daran genommen, dass wir ihre Jungen für unsere eigenen Zwecke ausgebildet haben. Verständlich... und eigentlich ein wenig tragisch. In dieser Sache sind wir die Bösen.\n\nJetzt ist aber nicht die Zeit, über solche Dinge nachzudenken. Diese Kreaturen sind Wesen aus Feuer und bei mehr als einer Gelegenheit haben sie Leben in unseren Reihen gefordert. Nun da ihre Matriarchin verärgert ist, ist die Gefahr immens gewachsen.\n\nIch brauche jemanden, der ihren Zorn besänftigt, und ich fürchte, dass Ihr dazu am fähigsten seid.", sourceObjective = "Bezwingt die Feuerfalkenmatriarchin.", sourceObjectiveStatus = "unverified-source-field" }
quests[29290] = { id = 29290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer am Himmel", description = "Schaut Euch das an! Es ist unglaublich! Gerade mal vor zwei Tagen geboren und schon ausgewachsen. Traurigerweise fürchte ich, dass ihre Lebensdauer entsprechend kurz sein wird, deshalb sollten wir die Zeit ausnutzen, die wir haben.\n\nSeine Ausbildung ist erstaunlich gut verlaufen. Ich möchte, dass Ihr derjenige seid, der ihn auf die Masse an feindlichen Streitkräften loslässt, die sich in der Nähe von Ragnaros' Unterschlupf versammelt haben.\n\nZeigt keine Gnade, {race}.", sourceObjective = "Benutzt den dressierten Feuerfalken, um 100 Flammenschürersalamander, 40 Aschenweberspinnen und 3 geschmolzene Lords, die in den Feuerlanden häufig anzutreffen sind, zu töten.", progress = "Einige unserer fähigsten Streitkräfte sind bereit, Ragnaros selbst anzugreifen. Wenn diese Angriffe gut laufen, sind wir vielleicht in der Lage, ihnen die Gelegenheit zu geben, die sie benötigen.", completion = "Ich nehme an, Euer Angriff war erfolgreich! Großartig. Dies könnte ein Schlüsselmoment im Durchbrechen von Ragnaros' Verteidigung sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[29291] = { id = 29291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Schirm, Charm und Bomben" }
quests[29292] = { id = 29292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falkenfeuer" }
quests[29293] = { id = 29293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesengte Flügel", description = "Viele unserer Sturmkrähen sind vorausgeflogen, um die Spitze auszukundschaften und zu versuchen, einige der Feuerfalkeneier zu besorgen, allerdings mit wenig Erfolg, fürchte ich. Die Thermalwinde machen sicheres Fliegen fast unmöglich und die Feuerfalken sind auch nicht gerade besonders freundlich.\n\nIch möchte, dass Ihr Euch dorthin begebt und so viele Druiden rettet, wie Ihr könnt. Ich habe Schienen, Verbände, Brandsalben, Riechsalze... alles, was Ihr braucht, um ihnen wieder auf die Beine zu helfen, vorausgesetzt, sie leben noch. Bitte beeilt Euch und helft allen, die Ihr finden könnt.", sourceObjective = "Rettet 5 verletzte Druiden der Kralle auf dem Schwarzrauchgipfel.", completion = "Mehrere unserer Brüder und Schwestern sind hier vorbeigekommen, als sie in die Sicherheit des Wachenden Baums zurückkehrten. Ihr habt da draußen sehr gute Arbeit geleistet, {name}. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[29294] = { id = 29294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "nimate Embers" }
quests[29295] = { id = 29295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Je größer...", description = "Ihr wollt Euch ja wohl nicht in DER Ausstattung den feurigen Ungetümen stellen, oder? Wenn Ihr nicht meine aus Obsidium hergestellten Sachen tragt, dann werdet Ihr sofort in Flammen aufgehen! Und selbst wenn Ihr sie tragt, Ihr könnt nie genug von den guten Dingen haben.\n\nSchaut, <Bruder/Schwester>, ich kann Euch die beste Rüstung herstellen, die für Gold zu haben ist, aber ich brauche zuerst reines, unverhüttetes lebendiges Obsidium.\n\nDie Obsidiumbestrafer auf dem Schwarzrauchgipfel bestehen im wahrsten Sinne des Wortes aus dem Zeug. Geht und tötet sie und sammelt ihre Überreste ein.", sourceObjective = "Sammelt 10 Stücke lebendiges Obsidium von den Obsidiumbestrafern auf dem Schwarzrauchgipfel.", progress = "Habt Ihr mir die Waren mitgebracht?", completion = "Das sollte genügen. Gute Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29296] = { id = 29296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Territoriale Vögel", description = "Die Feuerfalken sind aufgebracht über unsere fortgesetzte Anwesenheit. Sie werden langsam extrem feindselig und nicht nur auf die übliche territoriale Art. Ich mache mir Sorgen, dass sie sich schon bald dem Angriff auf unseren Baum anschließen werden, wenn wir sie sich selbst überlassen - und ich bin mir nicht sicher, ob wir in der Lage sein werden, damit umzugehen.\n\nBegebt Euch zum Schwarzrauchgipfel und tut, was Ihr tun müsst, um sie in Schach zu halten. Im Moment ist mir unsere Sicherheit um einiges wichtiger als ihre, handelt also entschlossen.", sourceObjective = "Tötet 5 Feuerfalken.", progress = "Je eher, je besser, {name}. Ihre Aggression könnte sie weiter von ihrem Nest führen, wenn wir sie unkontrolliert sich selbst überlassen.", completion = "Gut gemacht, {name}. Es ist gut zu wissen, dass ich auf Euch zählen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[29297] = { id = 29297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist das Vögelchen?", description = "Hirschhaupts Druiden schlagen an der Wildflammenspitze im Nordosten ordentlich zu.\n\nDie Druiden fliegen in Gestalt von Feuerkrähen über uns und greifen an, wenn wir es am wenigsten erwarten. Das Schlimmste ist, dass sie genau wissen, wie sie außerhalb unserer Reichweite bleiben!\n\nWir wären vollkommen hilflos, wenn mir Damek nicht seine getreue Harpune geliehen hätte. Er sagt, dass diese Waffen gerade und zuverlässig fliegen, selbst in dieser dicken Luft.\n\nNehmt die Waffe des Zwergs und holt ein paar dieser Vögel vom Himmel!", sourceObjective = "Tötet drei Druiden der Flamme, während sie in Feuerkrähengestalt unterwegs sind, mit dem Vogelpiekser.", completion = "Diese verdammten Vögel sind tot? Gut, dass wir die los sind!", sourceObjectiveStatus = "unverified-source-field" }
quests[29298] = { id = 29298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrußtes Medaillon", description = "Auf der Oberseite dieses Medaillons sind einige kleine, blattförmige Schnitzereien zu sehen, aber alle anderen Details haben sich mit der Zeit abgescheuert oder sind durch Feuer verbrannt worden. Es scheint druidischer Natur zu sein.\n\nDie meisten Druiden besuchen die Mondlichtung während ihrer Ausbildung. Wenn Euch jemand dabei helfen kann, die Herkunft dieses Medaillons herauszufinden, dann ist das Rabine Saturna in Nachthafen.", sourceObjective = "Bringt das verrußte Medaillon zu Rabine Saturna in Nachthafen auf der Mondlichtung.", progress = "Ja, junger {race}?", completion = "Was haben wir denn da? Eine Halskette? Nein, ein Medaillon...\n\nOh je...", sourceObjectiveStatus = "unverified-source-field" }
quests[29299] = { id = 29299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manche mögen's heiß", description = "Ich bin in meinen Studien vorangekommen, {name}. Basierend auf den Dingen, die wir in der lokalen Flora beobachtet haben, ist es durchaus möglich, dass Euer Peitscher auch supererhitzte Flüssigkeiten als Hauptnahrungsquelle verträgt.\n\nIch hätte gerne, dass Ihr mir bei einem kleinen Experiment helft. Die Glutspeiskorpione, die in den Magmaquellen im Norden hausen, versprühen im Kampf brennende Feuerlachen.\n\nNehmt den Peitscher und beobachtet seine Reaktion auf die Glutlachen der Skorpione.", sourceObjective = "Beobachtet den Purpurpeitscher, wenn er von 6 Glutlachen trinkt. Glutlachen entstehen durch den Kampf gegen Glutspeiskorpione.", completion = "Hat es funktioniert? Meine Theorie war also korrekt?", sourceObjectiveStatus = "unverified-source-field" }
quests[29302] = { id = 29302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufdecken verborgener Geheimnisse", description = "Die Initialen auf dem Medaillon scheinen verblasst zu sein, aber ich kann eine Macht darin spüren, die auf nur einen möglichen Besitzer schließen lässt:\n\nLeyara, die Druidin der Flamme.\n\nTretet zurück und wir werden sehen, welche Überraschungen dieses Medaillon bereithält.", sourceObjective = "Beobachtet die in dem verrußten Medaillon gespeicherten Erinnerungen.", completion = "Wenn Leyara den Krieg der Sandstürme miterlebt hat, dann ist es wahrscheinlich, dass sie Fandral kannte - und seinen verstorbenen Sohn, Valstann - und zwar sehr viel näher, als wir jemals vermutet hätten.\n\nEs scheint, dass Eure Reise hier noch nicht endet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29303] = { id = 29303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tragödie und Familie", description = "Es war sehr einsichtsvoll von Euch, mir dieses Medaillon zu bringen, {name}. Ich bin einer der wenigen, die wissen, wo Valstanns Leichnam begraben ist.\n\nIhr findet seine letzte Ruhestätte auf einem kleinen Friedhof, südöstlich von Astranaar im Eschental. Bringt dieses Medaillon zu dem Ort und vielleicht eröffnet es Euch weitere Erinnerungen.\n\nLebt wohl, {name}, und viel Glück für Eure Reise.", sourceObjective = "Bringt das verrußte Medaillon zu dem nachtelfischen Grab in der Nähe von Astranaar im Eschental.", sourceObjectiveStatus = "unverified-source-field" }
quests[29304] = { id = 29304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hunde des Krieges", description = "Unsere Truppen werden von entfesselten Monstrositäten in die Knie gezwungen - Aschenhunde aus den geschmolzenen Tiefen.\n\nDiese Hunde fürchten nichts und niemanden und werden nicht innehalten, bis ihr Blutdurst befriedigt ist. Unsere Streitkräfte können sie gerade so zurückhalten.\n\nGeht und schließt Euch den Verteidigern auf den Aschenfeldern oder im Geschmolzenen Strom an. Vielleicht gelingt es Euch, ihre Anzahl ein wenig zu reduzieren.", sourceObjective = "Tötet 5 Aschenhunde oder uralte Aschenhunde.", completion = "Gut, {class}. Der Feind mag hart sein, aber Ihr habt heute bewiesen, dass Ihr härter seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[29305] = { id = 29305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Stich ins Herz", description = "Einer von Ragnaros' Leutnants hat sich auf Ragnaros' Ebenen gezeigt, dem von Mauern umgebenen Bereich im Nordosten von uns.\n\nIch hatte gehofft, Euch direkt nach Eurer Rückkehr wieder aussenden zu können, aber ich fürchte, dass Dorrzweig und einige unserer Streitkräfte sich bereits in die Schlacht gestürzt haben. Ihr solltet Euch beeilen.\n\nEs sollte Euch möglich sein, diese Klippe direkt hier hinunterzuspringen und sie so schnell zu erreichen.", sourceObjective = "Tötet den Leutnant der Flamme.", completion = "Sehr gut gemacht, {name}! Das sollte sie erheblich hemmen.\n\nWenn wir das durchhalten, sollten wir den Kampf leicht zu Ragnaros selbst tragen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[29307] = { id = 29307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz der Flamme", description = "Ihr seid <der/die> erste Sterbliche, <der/die> einem Drachenkonzil beiwohnt und gehört zu den einzigen Wesen in Azeroth, die an der Wahl eines Aspekts teilnehmen.\n\nMein Aufstieg hat mich mit unglaublicher Macht erfüllt. Ich habe mir erlaubt, Tarecgosas Band mit Euch zu stärken, obschon sie ein... permanenteres Zuhause benötigt.\n\nIch möchte, dass Ihr ein letztes Mal in die Ebene des Feuers reist und mir das Herz von Ragnaros bringt.\n\nWenn wir uns das nächste Mal begegnen, werde ich Euch angemessen für alles, was Ihr getan habt, belohnen können.", sourceObjective = "Verstärkt den Runenstab von Nordrassil mit 250 schwelenden Essenzen und besorgt Euch das Herz der Flamme.", progress = "Ein feiner Tag für eine Zeremonie. Findet Ihr nicht, {name}?", completion = "Ihr habt Großes geleistet, {name}.\n\nBereitet Euch nun darauf vor, die Belohnung eines Helden zu empfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29308] = { id = 29308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz der Flamme", description = "Ihr seid <der/die> erste Sterbliche, <der/die> einem Drachenkonzil beiwohnt und gehört zu den einzigen Wesen in Azeroth, die an der Wahl eines Aspekts teilnehmen.\n\nMein Aufstieg hat mich mit unglaublicher Macht erfüllt. Ich habe mir erlaubt, Tarecgosas Band mit Euch zu stärken, obschon sie ein... permanenteres Zuhause benötigt.\n\nIch möchte, dass Ihr ein letztes Mal in die Ebene des Feuers reist und mir das Herz von Ragnaros bringt.\n\nWenn wir uns das nächste Mal begegnen, werde ich Euch angemessen für alles, was Ihr getan habt, belohnen können.", sourceObjective = "Verstärkt den Runenstab von Nordrassil mit 250 Essenzen der Seelenflamme und besorgt Euch das Herz der Flamme.", progress = "Ein feiner Tag für eine Zeremonie. Findet Ihr nicht, {name}?", completion = "Ihr habt Großes geleistet, {name}.\n\nBereitet Euch nun darauf vor, die Belohnung eines Helden zu empfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29309] = { id = 29309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stoff, aus dem Legenden sind", description = "Es ist eine Ehre, Euch kennen zu lernen, {race}.\n\nEure Taten sind bei den Kreaturen Azeroths in aller Ohren, sowohl sterblich als auch unsterblich.\n\nIch werde Kalecgos nach seiner Ankunft das Herz von Ragnaros präsentieren. Seine Macht wird dazu verwendet werden, Eure Waffe noch zu verstärken.\n\nDie Zeremonie beginnt in Kürze. Ich wurde dazu ernannt, Euch dort hinzuführen, sobald Ihr bereit seid.", sourceObjective = "Sprecht mit Hallegosa.", progress = "Seht! Drachenzorn, Tarecgosas letzte Ruhe.", completion = "Eure Heldentaten werden nie vergessen werden, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29310] = { id = 29310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Trendwende", description = "An dem Tag, an dem Leyara Hamuul angriff, hat sie in der Nähe von einigen Ruinen am Hyjal gewartet, nordwestlich des Geheilten Hyjal. Sie hat sich zu der Zeit seltsam verhalten: gefasst, ruhig und mit Blick in die Ferne. Möglicherweise ist der Ort für sie wichtig.\n\nDas Medaillon könnte vielleicht reagieren, wenn es an diesen Ort gebracht wird.", sourceObjective = "Bringt das verrußte Medaillon zu dem kleinen Grabstein bei Leyaras Trauer beim Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29311] = { id = 29311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Rest ist Geschichte", description = "In ihren Erinnerungen hat Leyara von Malfurion gesprochen. Die Tragödien ihrer Vergangenheit sind - zumindest ihrer Meinung nach - hauptsächlich seinen Handlungen geschuldet.\n\nMalfurion muss sich an Leyara erinnern, bevor sie eine Druidin der Flamme wurde. Ihr entschließt Euch, ihm das Medaillon in die Feuerlande zu bringen. Hoffentlich kann er alle offenen Fragen beantworten.", sourceObjective = "Bringt das verrußte Medaillon zu Malfurion an der Geschmolzenen Front.\n\nBereitgestellter Gegenstand:", completion = "Ja, ich kannte Leyara und ich war mir ihres Zorns bewusst, selbst bevor sie sich den Druiden der Flamme anschloss. Einst war sie eine vielversprechende junge Druidin. Leider sind Familienbande oft stärker als die Macht der Vernunft und letztendlich hat sie sich dafür entschieden, Fandral auf seinem verräterischen Pfad zu folgen.\n\nIhr solltet dieses Medaillon behalten, {name}. Möge es Euch daran erinnern, dass jeder von uns auf seinem eigenen Pfad durchs Leben geht... und dass einige Pfade einfacher sind als andere.", sourceObjectiveStatus = "unverified-source-field" }
quests[29312] = { id = 29312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stoff, aus dem Legenden sind", description = "Es ist eine Ehre, Euch kennen zu lernen, {race}.\n\nEure Taten sind bei den Kreaturen Azeroths in aller Ohren, sowohl sterblich als auch unsterblich.\n\nIch werde Kalecgos nach seiner Ankunft das Herz von Ragnaros präsentieren. Seine Macht wird dazu verwendet werden, Eure Waffe noch zu verstärken.\n\nDie Zeremonie beginnt in Kürze. Ich wurde dazu ernannt, Euch dort hinzuführen, sobald Ihr bereit seid.", sourceObjective = "Sprecht mit Hallegosa.", progress = "Seht! Drachenzorn, Tarecgosas letzte Ruhe.", completion = "Eure Heldentaten werden niemals in Vergessenheit geraten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29313] = { id = 29313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geheimnis des perfekten Kimchis", description = "Meine Familie stellt seit Generationen das beste Kimchi in ganz Darnassus her, {name}. Das Geheimnis ist eine ganz einfache Sache, aber sie macht den ganzen Unterschied.\n\nWir vergraben die Krüge im Boden, bis der Inhalt bereit ist, serviert zu werden, und die letzte Ladung hat gerade diesen Punkt erreicht. Ihr könnt die Krüge überall in der Stadt in Erdhügeln vergraben finden. Würdet Ihr mir helfen, sie einzusammeln, solange ihr Inhalt genau richtig ist?", sourceObjective = "Findet 8 vergrabene Kimchikrüge in Darnassus.", progress = "Habt Ihr die Krüge gefunden?", completion = "Habt Dank, {name}. Ich hätte sie nie alle rechtzeitig finden können und es wäre doch schade gewesen, so viel gutes Kimchi zu verpassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29314] = { id = 29314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gedenkt der Vorfahren", description = "Die Lebenden sind nicht die einzigen, die Nahrung brauchen. Eine meiner Pflichten besteht darin, die Reiskuchen zuzubereiten, die den Vorfahren dargebracht werden. Normalerweise hat meine oberste Schülerin die Ehre, die Kuchen zum Tempel des Mondes zu bringen, damit sie dort gesegnet werden, und sie dann den Vorfahren darzubieten. Würdet Ihr, da sie heute nicht in der Stadt ist, diese Pflicht an ihrer Stelle übernehmen?", sourceObjective = "Sammelt die gesegneten Reiskuchen aus dem Tempel des Mondes ein.", progress = "Dies ist der Schrein, von dem der Ausbilder gesprochen hat.", completion = "<Ihr plaziert die Reiskuchen um den Schrein herum, der anfängt, sanft zu leuchten. Euch überkommt ein mildes Gefühl der Dankbarkeit.>", sourceObjectiveStatus = "unverified-source-field" }
quests[29315] = { id = 29315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fungourmet", description = "Manche Köche beschweren sich darüber, dass unsere geliebte Unterstadt nicht mit den nötigen Zutaten aufwarten kann, um wahrhaftig köstliche Speisen zuzubereiten.\n\nWas für jammernde Einfaltspinsel. Dabei gibt es hier doch solche Köstlichkeiten!\n\nSammelt einige der ranzigen, schleimigen Abflusskappen, die entlang der Nordwestkanäle der Unterstadt wachsen und bringt sie zu mir.", sourceObjective = "Besorgt 12 Abflusskappen. Liefert die Pilze bei Eunice Burch in Unterstadt ab.", progress = "Habt Ihr genügend Abflusskappen finden können?", completion = "Die riechen ja einfach nur widerlich. Perfekt!", sourceObjectiveStatus = "unverified-source-field" }
quests[29316] = { id = 29316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grundnahrungsmittel", description = "Es gibt bestimmte Dinge, die jeder braucht, vom Koch im kleinsten Haushalt bis zum obersten Küchenchef. Eines der wichtigsten Grundnahrungsmittel der Stadt ist Reismehl. Die meisten Familien haben mindestens einen Korb Reis in ihrem Haus und das gilt genauso für die Bewohner der Terrassen der Handwerker und der Händler.\n\nIch trage meinen Schülern oft auf, dabei zu helfen, Reis in Mehl zu verwandeln, da es eine gute Übung und eine Endlosaufgabe ist. Warum versucht Ihr es nicht einmal?", sourceObjective = "Helft den Bewohnern der Terrasse der Handwerker und der Terrasse der Händler Reis in Mehl zu verwandeln, indem Ihr den Inhalt der Reiskörbe zermahlt.", completion = "Nur durch viel Fleiß und Mühe können wir sicherstellen, dass es genügend Mehl für alle gibt. Danke für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29317] = { id = 29317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fischkopp", description = "Es hat einen... Vorfall mit einer Orcwache und einer von Apothekermeister Faranells Monstrositäten gegeben.\n\nOffenbar hat der Aufseher der Kor'kron ihr kurzerhand den Kopf abgeschlagen und ihn in den Schleim getreten.\n\nFaranells Lehrlinge suchen schon seit Stunden danach, können das Ding aber einfach nicht finden. Würdet Ihr versuchen, nach ihm zu angeln? Ich bin sicher, dass der alte Knabe sehr dankbar wäre.", sourceObjective = "Armand Kromwell möchte, dass Ihr für Apothekermeister Faranell einen abgetrennten Monstrositätenkopf aus den Kanälen von Unterstadt angelt.", progress = "Ihr habt nicht rein zufällig einen abgetrennten Monstrositätenkopf gesehen, oder...?", completion = "Ah! DA ist er ja! Wie habt Ihr ihn nur gefunden?\n\nNun, ganz gleich. Meine Schüler waren nicht in der Lage, den Kopf zu finden, obwohl sie stundenlang im Schleim herumgeplantscht haben. Aber dabei haben sie IMMERHIN diesen Beutel mit Glitzerkram gefunden... vielleicht könnt Ihr ja mit dem Inhalt etwas anfangen?\n\nIch danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[29318] = { id = 29318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rippchen für die Schildwachen", description = "Einer meiner Verantwortungsbereiche umfasst die Verpflegung der Schildwachen von Darnassus, wenn sie im Dienst sind. Diese Aufgabe kostet Zeit, aber es ist eine, die ich gerne erledige. Würde es Euch etwas ausmachen, mir beim heutigen Essen zu helfen? Nehmt einfach diese Rippchen, bereitet sie in einem Herd oder über einem Feuer zu und verteilt sie unter den Schildwachen in der Stadt.", sourceObjective = "Benutzt die rohen Rippchen in der Nähe eines Herdes oder Lagerfeuers, um sie zu kochen und benutzt sie dann, um 5 Schildwachen von Darnassus zu verpflegen.", completion = "All diese Schildwachen zu verköstigen ist mit Eurer Hilfe viel einfacher. Diesmal musste sich niemand für sein Essen anstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29319] = { id = 29319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaulquappen des Todes", description = "Einige unserer Apotheker haben es sich zur Gewohnheit gemacht, ihren etwas bedenklicheren chemischen Müll in den Stillwassertümpel zu kippen und... nun, sagen wir einfach, dass niemand so genau wissen möchte, wie groß mutierte fleischfressende Kröten werden können.\n\nWärt Ihr bereit, ein paar riesige fleischfressende Kaulquappen zu fangen, bevor es soweit kommt? Fasst sie nur besser nicht mit bloßen Händen an.", sourceObjective = "Armand Kromwell in Unterstadt möchte, dass Ihr ihm 8 riesige fleischfressende Kaulquappen bringt.", progress = "Habt Ihr ein paar mutierte Kaulquappen finden können? Ihr solltet sie besser nicht mit bloßen Händen anfassen.", completion = "Ausgezeichnete Arbeit, {name}. Ich sorge dafür, dass sie sofort... verwahrt werden.\n\nWas könnten unsere wunderbaren Apotheker denn auch mit einer Armee monströser, giftspuckender, fleischfressender Superkröten anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29320] = { id = 29320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein toller Hecht", description = "Ihr habt doch schon im Blendwassersee geangelt, oder?\n\nDer größte Fang in dem See ist, einen der riesigen leichengefütterten Hechte an Land zu ziehen. Sie beißen allerdings nur bei einer ganz besonderen Ködersorte an... Leichenwürmer.\n\nSucht bei den Gräbern im Innenhof an der Oberfläche. Dort solltet Ihr welche finden können.", sourceObjective = "Grabt einen Leichenwurm im Innenhof der Ruinen von Lordaeron aus und benutzt ihn als Köder um einen leichengefütterten Hecht zu fangen. Leichengefütterte Hechte gibt es im Blendwassersee, nordöstlich von Unterstadt.", progress = "Schon den Hecht gefangen?", completion = "Das ist ein toller Hecht, {name}. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[29321] = { id = 29321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muscheltaucher", description = "Es scheint, als würden alle, die ich kenne, Muscheln lieben, aber ich kann ihren Anblick nicht ertragen! Sie riechen schlecht und sind schleimig und um sie zu ernten, muss man im Matsch graben. Da würde ich einer Angel und ein bisschen Köder doch jeden Tag den Vorzug geben.\n\nTrotzdem möchte ich meinen Bruder mit einem Eimer frischer Muscheln überraschen. Euch winkt eine Belohnung, wenn Ihr Euch bereit erklärt, mir diese Muscheln zu beschaffen.\n\nGeht einfach durch das Portal nach Rut'theran und sucht in den seichten Stellen am Ufer nach Muscheln.", sourceObjective = "Sammelt 10 Teldrassilmuscheln von den Ufern in der Nähe von Rut'theran.", progress = "Habt Ihr genug Muscheln gefunden?", completion = "Igitt, die sehen so eklig aus, aber mein Bruder mag sie am liebsten. Danke, dass Ihr mir diese unangenehme Aufgabe abgenommen habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[29322] = { id = 29322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schleim-Time", description = "Es braucht schon eine ganz besondere Art von Angler, um die Schätze der blubbernden Schleimkanäle von Unterstadt wertzuschätzen. Meint Ihr, Ihr könnt ein paar der zuckenden Schleimschimmel einsammeln, die dort unten herumkriechen?\n\nIhr könnt versuchen, sie zu angeln, aber sie sind verschlagen; vielleicht wäre es einfacher, ein Schleimbad zu nehmen und sie einfach zu packen.\n\nDenkt daran, dass sie uns nur lebendig und intakt etwas nützen... Wer möchte schon gern tote Schleimschimmel essen?! Widerwärtig.", sourceObjective = "Sammelt 10 zuckende Schleimschimmel. Liefert sie bei Armand Kromwell in Unterstadt ab.", progress = "Gar nicht so einfach zu fangen, was?", completion = "Diese Schleime sehen perfekt aus. Ich schicke sie auf den Weg zu Eunice, damit sie sie zubereitet. Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[29323] = { id = 29323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstockung", description = "Wir haben die meisten unserer Lebensmittelvorräte benutzt, um diejenigen zu versorgen, deren Häuser und Lebensgrundlagen zerstört wurden. Wenn wir unsere Vorräte nicht wieder aufstocken, werden wir alle in Gefahr sein, wenn das nächste Mal ein schlimmer Sturm oder eine Invasion der Horde über uns hereinbricht.\n\nVielleicht seid Ihr bereit, mir dabei zu helfen, unsere Bestände an Seefelchen wieder aufzufüllen. Ihr könnt sie überall in Darnassus fangen und sobald sie getrocknet sind, halten sie sich, bis sie gebraucht werden.", sourceObjective = "Fangt 5 Seefelchen, indem Ihr in Darnassus angelt.", progress = "Wenn all unsere Fischer mit anpacken, dann wird es nicht lange dauern, bis wir unsere Vorräte wieder aufgefüllt haben.", completion = "Die sind prächtig! Danke, {name}. Ich hänge sie zum Trocknen auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[29324] = { id = 29324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Anhänger der Schwester", description = "Habt Ihr schon Schwester Aquinne kennengelernt? Sie und ich sind gemeinsam in Dolanaar aufgewachsen und sie ist vor kurzem in der Stadt angekommen, um im Tempel des Mondes ausgebildet zu werden. Wir haben eine Bootsfahrt gemacht, aber der ungeschickte Ruderer hat das Boot zum Kentern gebracht!\n\nAls wir wieder am Ufer waren, war Aquinnes Anhänger verschwunden. Die Seen von Darnassus sind voll von riesigen Welsen, die alles was glänzt verschlucken.\n\nIch habe ohne Pause nach ihnen geangelt und gehofft, dass ich einen mit ihrem Anhänger finde. Wollt Ihr mir vielleicht helfen?", sourceObjective = "Erhaltet Aquinnes Mondanhänger aus dem Magen eines riesigen Welses. Ihr solltet sie an jeder Angelstelle in Darnassus fangen können.", progress = "Konntet Ihr Aquinnes verlorenen Anhänger finden? Ich muss schon etwa fünfzig dieser Monster gefangen haben und habe nicht die geringste Spur!", completion = "<Astaia nimmt Euch den Anhänger ab.>\n\nUnter all dem Schleim und Anlauf glaube ich, es wiederzuerkennen! Aquinne wird sich so freuen, es wiederzubekommen... natürlich nachdem ich es gründlich gereinigt habe. Ich kann Euch nicht genug danken, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29325] = { id = 29325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein glitschiger Snack", description = "Habt Ihr schon einmal Oktopusfleisch gegessen? Es ist etwas gewöhnungsbedürftig, aber es ist mein Leibgericht! Ich kenne sogar Leute, die die Dinger am Stück und lebendig essen!\n\nIch habe nicht vor, das bald auszuprobieren, aber mir sind gerade die frischen Oktopusse ausgegangen. Helft Ihr mir, neue zu bekommen? Sie leben im seichten Wasser an der Küste von Rut'theran.", sourceObjective = "Sammelt 6 Babyoktopusse aus dem seichten Wasser in der Nähe von Rut'theran.", progress = "Es ist unmöglich, Oktopusse mit einer Rute zu fangen. Ihr müsst sie einfach packen!", completion = "Die werden köstlich sein, das weiß ich jetzt schon! Danke, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[29326] = { id = 29326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Nordrassilgipfeltreffen", description = "Hallo, {class}! Meine Brüder und Schwestern vom Irdenen Ring haben Gutes über Eure Taten nach dem Kataklysmus zu berichten gewusst. Doch noch immer muss vieles getan werden, wenn diese zerbrochene Welt geheilt werden soll.\n\nBegleitet mich ein paar Schritte. Vorbereitungen für eine Zeremonie sind im Gange, für ein Ritual, von dem ich hoffe, dass es der Wendepunkt in unserem Kampf gegen den Schattenhammer darstellen wird.\n\nSobald alles abgeschlossen ist, werdet Ihr das Wort über unseren Triumph hier in die Welt tragen können.", sourceObjective = "Sprecht mit Thrall unter dem Weltenbaum am Hyjal und beobachtet die Zeremonie des Irdenen Rings.", completion = "Es kann nicht vorbei sein. Wir dürfen die Hoffnung nicht aufgeben!", sourceObjectiveStatus = "unverified-source-field" }
quests[29327] = { id = 29327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementare Bande: Zweifel", description = "Ich kenne denjenigen, nach dem Ihr sucht... aber ich weiß nicht, ob es weise von Euch ist, ihm zu folgen. Er hat sich selbst in den Zyklon gestürzt. Die Winde zehren nun an seinem Körper und seinem Geist, zweifellos lassen sie nichts zurück als Fetzen und Zweifel.\n\nHinter ihm herzujagen würde Euch nur demselben Schicksal aussetzen. Der schneidende Wind lässt nichts unberührt.\n\nIhr seid gewarnt worden. Was habt Ihr jetzt vor?", sourceObjective = "Sprecht mit Zyklonas, um eine sichere Passage zu Thrall zu bekommen. Kämpft dann mit den Windelementaren, die ihn peinigen, bis er frei ist.", progress = "Bleibt wachsam, {name}! Gebt Go'el nicht auf.", completion = "Was ist dieses... Wasser?", sourceObjectiveStatus = "unverified-source-field" }
quests[29328] = { id = 29328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementare Bande: Verlangen", description = "Noch einmal, {class}, ich schaffe es nicht ohne Eure Hilfe. Ich werde versuchen, den Sturm zu besänftigen, aber Ihr werdet die instabilen Elementare zurückdrängen müssen, die darum herumwirbeln. Nur dann können wir Go'el befreien!", sourceObjective = "Vernichtet die Fluten des Verlangens und die Wirbel des Verlangens in der Nähe des Wirbelnden Abgrunds, bis Thrall aus ihren Fängen befreit ist.", completion = "Luft, Wasser... und jetzt Erde?", sourceObjectiveStatus = "unverified-source-field" }
quests[29329] = { id = 29329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementare Bande: Geduld", description = "Mit dem Segen der Steinmutter kann ich uns dahin bringen, wo Go'el gefangen gehalten wird.\n\nWir müssen vorsichtig sein. Der Schattenhammer verfügt überall über Agenten. Helft mir, sie zurückzuhalten, während ich versuche, zu Go'el durchzukommen!\n\nSprecht mit mir, wenn Ihr bereit seid, und ich werde Euch zu ihm bringen.", sourceObjective = "Sprecht mit Aggra, wenn Ihr bereit seid, Thrall zu helfen. Bezwingt dann die Elemente und Kernsteine der Geduld, die ihn gefangen halten.", progress = "Wir sind fast da, {name}. Bleibt noch ein wenig länger an meiner Seite. Wir werden es schaffen, zu ihm durchzudringen.", completion = "<Aggra ballt ihre Fäuste und starrt auf die Stelle, an der Thrall noch vor wenigen Augenblicken stand.>", sourceObjectiveStatus = "unverified-source-field" }
quests[29330] = { id = 29330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementare Bande: Zorn", description = "Die Totems, {name}! Wir müssen sie aktivieren oder Go'el ist verloren!\n\nTötet die Elementare neben jedem meiner Totems, die an den Kanten dieses Plateaus platziert sind. Sobald alle vier Totems aktiviert sind, sollte es uns möglich sein, das letzte Stück von Go'els Seele zu befreien!", sourceObjective = "Tötet Feuerelementare neben Aggras Lufttotem an der westlichen Kante des Plateaus, bis es aktiviert ist. Macht dann bei Aggras Wassertotem, Aggras Erdtotem und Aggras Feuertotem weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[29331] = { id = 29331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementare Bande: Das Gelübde", description = "Bevor er durch das Portal zum Hyjal trat, hat Thrall Euch gebeten, ihm zu folgen. Es gibt da etwas, von dem er möchte, dass Ihr es seht.", sourceObjective = "Sprecht mit Thrall bei Nordrassil auf dem Hyjal.", completion = "Ich danke Euch – ich lebe erneut! Und dank der gemeinsamen Anstrengungen des Zirkels des Cenarius und dem Irdenen Ring wird der Weltenbaum ebenfalls neues Leben nach Azeroth bringen.\n\nWährend wir uns weiterhin um Todesschwinge und den Rest unserer Feinde kümmern müssen, möchte ich gerne etwas mit Euch teilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29332] = { id = 29332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leckere Lilien", description = "Die Lilien, die um den Stillwassertümpel herum wachsen, lassen sich zu einer köstlichen Suppe verkochen.\n\nNun ja... \"köstlich\" in dem Sinne, dass nicht sofort jedem Orc schlecht wird, der sie trinkt.\n\nWarum sammelt Ihr nicht ein paar für mich, hmmm? Gebt nur gut auf die riesigen fleischfressenden Kaulquappen Acht.", sourceObjective = "Besorgt 10 Stillwasserlilien. Liefert die Pflanzen bei Eunice Burch in Unterstadt ab.", progress = "Habt Ihr genügend Stillwasserlilien finden können?", completion = "Ah, so eine üppige Ladung Lilien. Bravo! Ich koche sie sofort ein...", sourceObjectiveStatus = "unverified-source-field" }
quests[29333] = { id = 29333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneckt lecker!", description = "Die Orcwachen beschweren sich ständig über fade, schimmlige Kost in Unterstadt - als ob WIR etwas dafür könnten, dass sie sich nicht von Pilzen und alten Leichen ernähren können - also finde ich, dass es an der Zeit ist, dass sie herausfinden, was für exotische Köstlichkeiten wir zubereiten können, wenn wir wollen.\n\nSammelt ein paar Süßwasserschnecken aus dem Blendwassersee und ich zeige ihnen, was eine wahre kulinarische Meisterin zaubern kann.", sourceObjective = "Sammelt 8 Blendwasserschnecken. Liefert sie bei Eunice Burch in Unterstadt ab.", progress = "Schon die Süßwasserschnecken gesammelt?", completion = "Ihr müsst ein guter Schwimmer sein... Ich kann höchstens Toter-Mann spielen.\n\nWie dem auch sei, Ihr habt da ein hervorragendes Bündel Schnecken gesammelt. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[29334] = { id = 29334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wahres Schabsal", description = "Bei all dem Gemecker, das diese Aufseher der Kor'kron für die Verpflegung in Unterstadt übrig haben, gibt es eine Sache, die sie schaufelweise essen: der dreifach gewürzte Knuspereintopf meiner Schwester.\n\nWeil er so beliebt ist, gehen ihr ständig die Zutaten aus. Würdet Ihr ein paar zu ihr zum Wagen bringen, aus dem sie den Eintopf verkauft?\n\nÜberall in der Stadt werdet Ihr Fallen finden; bringt einfach deren Inhalt zu Audrey und sie kümmert sich um den Rest!", sourceObjective = "Beschafft 20 träge Kakerlaken. Liefert die Insekten bei Chefköchin Audrey in Unterstadt ab.", progress = "Ich nenne meine kleinen Fallen \"Kakerlabinen\".\n\nKakerlaken spazieren hinein, sie spazieren aber nicht wieder heraus.", completion = "Gerade noch rechtzeitig bevor meine Vorräte erschöpft waren. Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[29335] = { id = 29335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die beißenden Winde", description = "{class}, ich weigere mich zu glauben, dass mein Go'el für immer verloren ist. Sein Geist ist über die Elementarebene zerstreut worden. Sollte auch nur ein Teil von ihm noch existieren, dann können wir ihn finden, ich brauche allerdings Eure Hilfe.\n\nWir werden mit der Ebene der Luft beginnen.\n\nSprecht mich erneut an und wir werden gemeinsam zum Vortexgipfel reisen. Wir müssen mit einem Elementar namens Zyklonas sprechen. Ein launischer Geselle, aber im Reich der Luft sieht er alles. Wenn mein Liebster dort sein sollte, so wird Zyklonas wissen, was mit ihm geschehen ist.", sourceObjective = "Sprecht mit Zyklonas auf dem Felsen des Südwinds in Uldum.", completion = "<Ihr spürt, wie der Wind über Eure Arme fegt, über Euer Gesicht, Eure Waffen und Rüstung...>\n\n<Zyklonas inspiziert Euch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[29336] = { id = 29336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die drängenden Fluten", description = "Go'el muss sich auf der Ebene des Wassers befinden... im Meeresschlund selbst! Mich fröstelt, wenn ich mir vorstelle, was ihn dort erwartet.\n\nFindet den Elementar Hydrius, in der Nähe des Wirbelnden Abgrunds. Er weiß von Go'el und sympathisiert mit unserem Kampf gegen Ragnaros. Wenn Euch jemand dort helfen kann, dann er.\n\nIch werde Euch unter den Strömen Vashj'irs treffen, {race}...", sourceObjective = "Sprecht mit Hydrius beim Wirbelnden Abgrund in den Abyssischen Tiefen von Vashj'ir.", completion = "Ich werde tun, was ich kann, um Euch zu helfen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29337] = { id = 29337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die beständige Erde", description = "Die Zeit ist knapp! Mein Liebster liegt in Tiefenheim. Ich werde uns dorthin bringen, sobald Ihr bereit seid, und wir werden mit Therazane, der Steinmutter, sprechen.", sourceObjective = "Sprecht mit Therazane bei Therazanes Thron in Tiefenheim.\n\nAggra kann Euch vom Wirbelnden Abgrund aus zu Therazanes Thron teleportieren.", completion = "Ich weiß bereits, wonach Ihr sucht, Fleischlinge. Und ich habe mich entschieden, Euch zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29338] = { id = 29338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die unnachgiebige Flamme", description = "Wir müssen nun zu den Feuerlanden reisen. In diesem Reich kann Go'els brennender Geist so fürchterlich wie Ragnaros selbst werden! Macht Euch bereit, da er allein in einer feindlichen Welt sein wird.\n\nSprecht mich an, wenn Ihr bereit seid... und mögen die Vorfahren uns beschützen!", sourceObjective = "Sprecht mit Aggra auf dem Nimbusrücken in Tiefenheim, um eine Passage in die Feuerlande zu sichern.", completion = "Haltet Euch bereit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29339] = { id = 29339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[29340] = { id = 29340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[29341] = { id = 29341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[29342] = { id = 29342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisangeln", description = "Die leckersten Fische leben in den kalten Gewässern Dun Moroghs, {name}, lasst Euch da mal nichts anderes erzählen! Mein Favorit, und am beliebtesten in Eisenschmiede, ist der Seesaibling, der aus den Ländern unserer Ahnen kommt.\n\nIch möchte ihn als Eisenschmiedes Geschenk an die Welt bezeichnen!\n\nWarum versucht Ihr nicht mal selbst, ein paar davon zu fangen? Der beste Ort, um diesen Fisch zu finden, ist im Helmsbettsee, im östlichen Teil von Dun Morogh.", sourceObjective = "Fangt 5 Seesaiblinge, indem Ihr im Helmsbettsee in Dun Morogh angelt.", progress = "Habt Ihr schon versucht, diese Saiblinge zu fangen?", completion = "Sie sind wunderschön, {name}! Ich glaube, Ihr habt jetzt langsam den Dreh raus.", sourceObjectiveStatus = "unverified-source-field" }
quests[29343] = { id = 29343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Nachwelt", description = "Ich bin mir sicher, dass Ihr inzwischen schon mal vom alten Eisenkiefer gehört habt, dem berühmtesten und am schwersten fassbaren Fisch in den Gewässern von Eisenschmiedes Düsterem Viertel. Nun, in seinen vielen Lebensjahren war er dafür verantwortlich, dass jede Menge Nachkommen das Licht der Welt erblickten. Lasst Euch nicht von dem Namen \"Junger Eisenkiefer\" täuschen, {name}, diese Jungfische sind genauso clever wie ihr Vater, ihnen mangelt es nur ein wenig an Erfahrung.\n\nMit Können und Geduld wird es Euch sicher gelingen, einen zu fangen, und wenn es so weit ist, dann bringt ihn zum Museum in Eisenschmiedes Bibliothek und stellt ihn aus, damit ihn alle sehen können!", sourceObjective = "Fangt einen jungen Eisenkiefer in Eisenschmiedes Düsterem Viertel und stellt ihn in der Bibliothek neben der leeren Plakette aus.", completion = "Gut gemacht, {name}! Vielleicht wird Euer Fang ja mehr Zwerge dazu inspirieren, das Angeln anzufangen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29344] = { id = 29344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fische für Squirky", description = "Hab ich Euch schon meinen Begleiter Squirky vorgestellt? Ich bringe ihm bei, wie man angelt, so richtig mit allen Schikanen! Bisher habe ich ihn mit Elritzen gefüttert, die ich aus dem Teich in diesem Viertel gefischt habe.\n\nVielleicht wollt Ihr es ja mal versuchen? Werft einfach Euren Köder in dem Teich da drüben aus und füttert Squirky mit den Elritzen, die Ihr rauszieht. Er wird Euch für immer lieben!", sourceObjective = "Angelt 3 blinde Elritzen aus dem Teich im Düsteren Viertel und verfüttert sie an Squirky.", completion = "Ihr habt gute Arbeit geleistet. Squirky sieht zufrieden aus und ich hatte Zeit, ein paar neue Köder zu basteln. Danke für Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[29345] = { id = 29345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tümpelschrecken", description = "Ein Goblinbesucher, der es sicher nur gut meinte, hat Azsharaschlangenköpfe in unseren Gewässern ausgesetzt und die überrennen jetzt unseren Teich.\n\nIch bitte Euch, wenn Ihr ein paar von diesen gefräßigen Raubfischen fangen könnt, bevor sie alle Kleinfische und Matschschnapper in Donnerfels gefressen haben, wäre ich sehr dankbar.", sourceObjective = "Kah Nebelläufer in Donnerfels braucht 8 Azsharaschlangenköpfe aus dem Teich in Donnerfels.", progress = "Konntet Ihr schon ein paar Azsharaschlangenköpfe fangen?", completion = "Gut gemacht, {name}. Alle Angler von Donnerfels müssen mit anpacken, damit sich diese boshaften Geschöpfe nicht in Mulgores Gewässern ansiedeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[29346] = { id = 29346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ring sie zu knechten", description = "Einer der Verlassenen aus den Teichen der Visionen ist an mich herangetreten und hat mir gesagt, dass sein Ring von einem blinden Höhlenfisch in den dortigen Teichen verschluckt worden ist.\n\nEs könnte auch sein Finger gewesen sein. So richtig verstanden habe ich ihn nicht; sein Kiefer hat sich nicht bewegt und sein Orcisch war nicht besser als mein eigenes.\n\nWie dem auch sei, ich dachte mir, dass wir unseren ungewöhnlichen Gästen einen Gefallen tun könnten und Höhlenfische ausnehmen könnten, bis wir den Ring - oder den Finger - gefunden haben.\n\nWürdet Ihr mir helfen?", sourceObjective = "Angelt einen blinden Höhlenfisch aus den Teichen der Visionen in Donnerfels. Wenn Ihr einen gefangen habt, nehmt ihn aus und seht nach, ob er den Ring verschluckt hat.", progress = "Ihr habt nicht zufällig meinen Ring gesehen, oder? Ich glaube, einer der Höhlenfische hat ihn verschluckt...", completion = "Ihr habt also meinen Ring gefunden, wie? Ich bin Euch überaus dankbar.\n\nUm ganz ehrlich zu sein, ich habe keine Ahnung, warum ich das Ding überhaupt behalte. Ich erinnere mich noch nicht einmal, wie er in meinen Besitz gekommen ist... vermutlich bin ich einfach ein Gewohnheitstier.\n\nWie ich schon sagte, bin ich Euch sehr dankbar. Diese Dinge hier habe ich während meiner Suche nach dem Ring gefunden. Vielleicht sind sie für Euch von Nutzen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29347] = { id = 29347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebendköder", description = "Wenn Ihr schon mal auf der Jagd nach Flusskrebsen wart, dann wisst Ihr, dass sie am besten auf Lebendköder reagieren. Und je mehr Köder, desto besser! Würdet Ihr gerne meinen neuen Köder ausprobieren? Schmiert Euch einfach damit ein und hüpft in den Helmsbettsee im östlichen Dun Morogh.\n\nBringt Euren Fang zu Koch Ghilm am Steinbruch Gol'Bolar westlich des Sees. Er ist ein Experte in der Zubereitung dieser zu groß geratenen Krabbeltiere!", sourceObjective = "Benutzt Grimnurs Köder an Euch selbst und springt dann in den Helmsbettsee in Dun Morogh.", completion = "Sie sind wunderschön, {name}! Grimnur wird so stolz sein, wenn er davon hört!\n\nOh, er hat mir gesagt, ich soll Euch das hier geben, wenn der Plan aufgeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[29348] = { id = 29348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Fische für Donnerfels", description = "Der Fischteich von Donnerfels wird von gefräßigen Azsharaschlangenköpfen heimgesucht. Es sind kaum noch Kleinfische oder Matschschnapper übrig.\n\nUnsere Angler sind schon dabei, so viele Schlangenköpfe wie möglich zu töten, aber könntet Ihr uns bei unseren Bemühungen, den Teich wieder zu bevölkern, ein wenig zur Hand gehen?\n\nWenn Ihr ein paar Fische aus dem Steinbullensee sammeln könntet und sie hierher nach Donnerfels bringt, wäre ich sehr dankbar.", sourceObjective = "Kah Nebelläufer in Donnerfels braucht 2 scharfe Kleinfische und 2 liebestolle Matschschnapper aus dem Steinbullensee in Mulgore.", progress = "Habt Ihr die Fische aus dem Steinbullensee dabei?", completion = "Wir wissen Eure Hilfe sehr zu schätzen, {name}.\n\nHoffentlich helfen diese Fische dabei, unseren Fischteich wieder zu bevölkern.", sourceObjectiveStatus = "unverified-source-field" }
quests[29349] = { id = 29349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lust auf Flusskrebs", description = "Eine der berühmtesten Delikatessen Mulgores sind die Flusskrebse, die in unseren Seen und Flüssen leben. Sie sind besonders beliebt bei Hochzeiten oder Geburtsfeiern.\n\nWürdet Ihr mir dabei helfen, einige dieser gerissenen Krustentiere für die Kochtöpfe von Donnerfels zu fangen?\n\nIhr könnt sie im Steinbullensee angeln, oder einfach hineinspringen und sie so fangen.", sourceObjective = "Kah Nebelläufer in Donnerfels braucht 10 Steinbullenflusskrebse aus dem Steinbullensee in Mulgore.", progress = "Krebse sind so schmackhaft. Habt Ihr viele gefangen?", completion = "Ah, so viele Krebse!\n\nHabt Ihr sie geangelt? Oder seid Ihr ihnen hinterhergeschwommen?\n\nIst auch egal. Ausgezeichnete Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29350] = { id = 29350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gnomische Köder-o-Matik", description = "Einer von den gnomischen Ingenieurskunstlehrern hat mir die Baupläne für einen raffinierten Köder gegeben, von dem er behauptet, dass er mir hilft, Fische schneller zu fangen und sie davon abzuhalten, abzuhauen.\n\nHier sind die Baupläne. Ihr werdet glänzende Schmuckstücke benötigen, die Ihr von meiner Assistentin im Gebäude erhalten könnt, einen haarfeinen Sprengstoffauslöser von einem Händler für Ingenieurskunstwaren in Tüftlerstadt und ein paar Rattenfallen von der Tiefenbahn.", sourceObjective = "Benutzt die Baupläne für einen Köder-o-Matik mit 5 glänzenden Schmuckstücken, einem haarfeinen Sprengstoffauslöser und 3 Rattenfallen um einen gnomischen Köder-o-Matik herzustellen.", progress = "Und, wie sieht's aus mit diesem raffinierten neuen Köder?", completion = "Ich denke, es sieht nicht nach was aus, was ein Fisch interessant finden könnte, aber man weiß ja nie. Fische sind seltsame Viecher. Danke, dass Ihr es versucht habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29351] = { id = 29351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Runde für die Wachen", description = "Die Wachen, die Eisenschmiede schützen, riskieren ihr Leben im Kampf gegen unsere vielen Feinde, und es ist an uns, uns um sie zu kümmern.\n\nHeute bestehen ihre Rationen aus zwei Lieblingsdingen der Zwerge: Haggis und Silberbräu aus Eisenschmiede. Wäret Ihr so gut, mir dabei zu helfen, die Rationen zu verteilen? Dadurch bekommen alle ihr Essen rechtzeitig und wir können zu der Erledigung anderer Aufgaben übergehen.", sourceObjective = "Verteilt die Rationen aus Eisenschmiede an 6 Wachen aus Eisenschmiede.", completion = "Eine volle Wache ist eine glückliche Wache, pflege ich immer zu sagen. Danke für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29352] = { id = 29352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geflügelmangel", description = "Oh nein, {name}, das wird ein Desaster, wenn wir nicht bald ein paar Hühner finden... Man kann doch eine Lauch-Hühnersuppe nicht ohne Huhn kochen! Das geht einfach nicht!\n\nEs ist immer noch Zeit genug, die Suppe und die Brühe herzustellen, wenn Ihr ein paar frische Hühner findet. Werdet Ihr mir helfen? Es laufen normalerweise immer ein paar Hühner außerhalb des Haupteingangs der Stadt herum. Wenn Ihr, sagen wir mal, sechs von ihnen erwischt, dann würdet Ihr mir den Hals retten.", sourceObjective = "Fangt 6 Hühner von Dun Morogh in der Nähe des Eingangs von Eisenschmiede.", progress = "Die Hühner, {name}, habt Ihr sie oder nicht?", completion = "Ja, das ist genau das, was ich brauchte. Ihr habt meinen Dank, {name}, und meine Entschuldigung, dass ich vorher so barsch war. Ich kann den Gedanken einfach nicht ertragen, dass eine Mahlzeit nicht rechtzeitig fertig wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[29353] = { id = 29353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haggis für alle!", description = "Der Haggis muss fließen. Na gut, bildlich gesprochen. Haggis wird niemals flüssig sein! Ihr wollt gar nicht wissen, was passiert, wenn die Bevölkerung von Eisenschmiede keinen Haggis bekommt.\n\nIch arbeite gerade an der nächsten Ladung, aber mir fehlen noch ein paar Zutaten.\n\nSognar Klippenbart ist der Fleischverkäufer im Militärviertel und er kann Euch den Sack voller Schafsinnereien verkaufen, den ich brauche. Milde Gewürze bekommt Ihr von jedem Kochbedarfshändler und Säcke voller Hafermehl findet Ihr in den Gasthäusern oder den Vorratslagern der Stadt.", sourceObjective = "Besorgt einen Sack voller Schafsinnereien, 5 Pakete milder Gewürze und 4 Säcke voller Hafermehl.", progress = "Habt Ihr die Zutaten?", completion = "Ihr habt sie alle? Wunderbar! Dann frisch ans Werk.", sourceObjectiveStatus = "unverified-source-field" }
quests[29354] = { id = 29354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glänzende Schmuckstücke", description = "Eines der einfachsten und nützlichsten Hilfmittel eines jeden Anglers ist das glänzende Schmuckstück. Selbst der ungeübteste Angler hat mit einem glänzenden Schmuckstück an der Sehne gute Chancen.\n\nBei all dem Fischen in letzter Zeit gehen die Vorräte von Donnerfels aber schnell zur Neige!\n\nKönnte ich Euch bitten, glänzende Steine vom Fuß der zentralen Anhöhe zu sammeln? Bringt sie zu Nahari Wolkenjäger, damit sie mit ihnen Nachschub anfertigen kann.", sourceObjective = "Nahari Wolkenjäger in Donnerfels braucht 20 glänzende Steine vom Fuß der zentralen Anhöhe.", progress = "Habt Ihr mir vielleicht ein paar glänzende Steine mitgebracht?", completion = "Das sind aber besonders hübsche Steine! Daraus werden perfekte glänzende Schmuckstücke werden, danke sehr.\n\nHier... Kah hat mir Bescheid gesagt, dass Ihr mit den Steinen vorbeikommen würdet und hat mich gebeten, Euch dies bei Eurer Ankunft zu geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[29355] = { id = 29355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewürzbrot en masse", description = "Es mag zwar nichts Besonderes sein, {name}, aber Gewürzbrot ist in Eisenschmiede schon seit jeher sehr beliebt. Manchmal komme ich mit meinen Lieferungen gar nicht hinterher!\n\nMöchtet Ihr vielleicht ein paar Laibe backen, damit Ihr nicht aus der Übung kommt, und mir damit helfen, meine Kunden zu versorgen? Ihr könnt alle Zutaten, die Ihr braucht, von meinem Bruder, Emrul Riknussun, ein Stockwerk unter uns erhalten.", sourceObjective = "Backt oder erhaltet 10 Scheiben Gewürzbrot.", progress = "Wie läuft es mit dem Gewürzbrot?", completion = "Dieses Brot sieht köstlich aus. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29356] = { id = 29356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft den Bierdürftigen", description = "Mein Vorrat an EKW, Eisenschmieder Kristallweizen für Euch Grünschnäbel, gehen zur Neige. Zum Glück ist die Brauerei nicht weit weg und die sollten schon ein neues Fass voll Drugans EKW für uns haben. Dieser Drugan ist ein echtes Brauereigenie, sag' ich Euch.\n\nIch werde es heute nicht schaffen, selbst nach Kharanos hinunterzulaufen, aber vielleicht könnt Ihr dort hinunter flitzen, ein neues Fass abholen und es hierher bringen? Was sagt Ihr?", sourceObjective = "Holt das Fass voll Drugans EKW von der Brauerei in Kharanos ab und bringt es nach Eisenschmiede zurück.", progress = "Und? Habt Ihr das Fass oder nicht?", completion = "Ah, gut gemacht! Ich sage Euch, dieser Drugan ist ein echtes Universalgenie - Entdecker, Historiker, Brauer - gibt es etwas, das dieser Zwerg nicht gemeistert hat?", sourceObjectiveStatus = "unverified-source-field" }
quests[29357] = { id = 29357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jede Menge Gewürzbrot", description = "Ist es nicht erstaunlich, wie etwas so einfaches wie Gewürzbrot jeden Tag in Darnassus verbraucht wird? Wenn ich mich nicht um meine anderen Verantwortlichkeiten kümmere, dann backe ich gerne Gewürzbrot, um meine Fähigkeiten als Koch zu verfeinern und an meiner Technik zu arbeiten.\n\nWarum probiert Ihr es nicht mal aus? Ihr solltet die Zutaten eigentlich hier im Laden finden.\n\nEgal wie viel wir herstellen, es wird nie schlecht. Bringt mir einige Laibe, wenn Ihr fertig seid und ich werde jemanden schicken, um sie mit unseren Freunden, den Gilneern, zu teilen.", sourceObjective = "Stellt 10 Laibe Gewürzbrot her oder besorgt sie Euch anderweitig.", progress = "Ich liebe diesen Geruch von frisch gebackenem Brot einfach, besonders von Gewürzbrot, Ihr nicht?", completion = "Diese hier sind gut gemacht, {name}. Ich hoffe, Ihr fandet es genauso entspannend wie ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[29358] = { id = 29358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir benötigen mehr Pinienkerne", description = "Die Shu'halo verwenden Pinienkerne in so vielen Gerichten: Wild, Fisch, Gemüse, selbst Backwaren versetzen wir mit ihnen.\n\nDie Erdenmutter hat uns damit gesegnet, dass die allerbesten Pinienkerne von den Bäumen auf diesen Anhöhen stammen.\n\nSammelt einfach Kienäpfel und röstet sie über einem Feuer, damit die Kerne herausfallen. Es sind fast nie genug für alle da...", sourceObjective = "Sammelt 30 Pinienkerne, indem Ihr Kienäpfel von Mulgore in Donnerfels sammelt und sie röstet. Liefert die Kerne bei Aska Nebelläufer in Donnerfels ab.", progress = "Habt Ihr viele dieser leckeren Pinienkerne finden können?", completion = "Ihr arbeitet so schnell!\n\nIch sorge dafür, dass sie an die verschiedenen Köche und Bäcker von Donnerfels verteilt werden.\n\nHabt Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[29359] = { id = 29359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Klassiker", description = "Hering ist eine der meistverlangten Fischarten in Darnassus, aber Hering ist nicht gleich Hering. Der Kaldoreihering kommt nur in den Gewässern um Teldrassil vor.\n\nIch versuche, immer ein paar vorrätig zu haben, weil dieser Fisch so vielseitig ist! Ich habe gerade erst wieder welche fertig geräuchert, deshalb muss ich meine Vorräte aufstocken. Würde es Euch etwas ausmachen, mir zu helfen? Ihr könnt Kaldoreihering fangen, wenn Ihr in der Nähe von Rut'theran angelt.", sourceObjective = "Angelt 8 Kaldoreiheringe, indem Ihr in der Nähe von Rut'theran Eure Angel auswerft.", progress = "Habt Ihr die Heringe?", completion = "Danke! Ich frage mich, was ich mit denen wohl anstellen könnte...", sourceObjectiveStatus = "unverified-source-field" }
quests[29360] = { id = 29360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und als Beilage: Fliegen", description = "Wir verpflegen hier nicht nur die Orcs, {class}. Diesmal geht es darum, Nahrung für deren Ablösung zuzubereiten.\n\nWir müssen klein beginnen und Fliegen fangen. Fliegen lieben fauliges Fleisch und wir lieben fauliges Fleisch... als Belagerungsgeschosse!\n\nDurchsucht die Fleischwagen nach überschüssigen Fleischbrocken. Wo es Fleisch gibt, gibt es auch Fliegen.\n\nBringt mir 25 fette Fliegen, damit ich Phase Zwei unseres Kochplans einleiten kann.", sourceObjective = "Beschafft 25 fette Fliegen von dem \"Fleisch\" in der Nähe der Fleischwagen. Kehrt anschließend zu Eunice Burch in Unterstadt zurück.", progress = "Ich wette, ein Bisschen von dem \"Fleisch\" ist noch gut.", completion = "Ah! Perfekt! Fett, träge und bereit, gefressen zu werden! Als nächstes werden wir sie an unsere Spinnen verfüttern. Die werden gemästet und dann verfüttern wir sie an die Frösche...\n\nAch, ich plappere schon wieder. Die Details müsst Ihr gar nicht wissen. Das ist nur ein kleiner Schritt in einem großen kulinarischen Plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[29361] = { id = 29361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Monster im Burggraben", description = "Manchmal muss man beim Angeln seinen Fang wieder ins Wasser zurückwerfen, {class}.\n\nWir haben diese Frösche nur für diesen Zweck gemästet. Sie haben fette Spinnen bekommen, die ihrerseits mit fetten Fliegen gefüttert worden sind, und jetzt füttern wir ein echtes Monster.\n\nIn den Burggräben an der Oberfläche, in den Ruinen von Lordaeron, lebt unser eigenes Burggrabenmonster.\n\nHeute ist Fütterungstag. Aber wir müssen es dabei auch abrichten. In diesem Beutel findet Ihr einen Lockvogelbausatz und ein paar fette Frösche. Stellt den Lockvogel auf und werft dem Monster die Frösche zu, sobald es auftaucht.", sourceObjective = "Benutzt den Allianzlockvogelbausatz, um das Burggrabenmonster in den Ruinen von Lordaeron hervorzulocken. Verwendet dann die fetten Frösche, um das Monster zu füttern.", completion = "Die Toten ernähren die Fliegen. Die Fliegen ernähren die Spinnen. Die Spinnen ernähren die Frösche. Die Frösche füttern unser Burggrabenmonster... ein entzückender Lebenszyklus, bei dem so viele Leben beendet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29362] = { id = 29362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Magische\" Pilze", description = "Ihr kennt doch sicher die Teiche der Visionen, oder?\n\nDort wächst eine bestimmte Pilzart... nicht die ledrigen, wuchernden Pilze, die dort überall stehen, sondern kleinere, zerbrechlichere Schwämme, die unter ihnen wachsen.\n\nSie sind selten, sehr köstlich und verleihen Gerichten einen Geschmack, den man magisch nennen könnte.\n\n...Was denn? Ernsthaft. Sie schmecken einfach nur gut. Sonst nichts.", sourceObjective = "Sammelt 6 \"magische\" Pilze aus den Teichen der Visionen in Donnerfels. Liefert sie bei Aska Nebelläufer in Donnerfels ab.", progress = "Konntet Ihr die Pilze finden?", completion = "Danke, {name}! Ich bin sicher, dass sie ein einfach magisches Aroma in jedes Gericht zaubern.\n\nWas ist denn? Hört auf mich so anzuschauen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29363] = { id = 29363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewürzbrot aus Mulgore", description = "Ich werde oft gefragt \"Aska, wer bäckt eigentlich all dieses Gewürzbrot aus Mulgore?!\"\n\nEine berechtigte Frage. Unser gutes und edles Brot wird an unzähligen Orten in jedem Winkel Azeroths gehandelt, selbst von unseren erbittertsten Feinden. SO LECKER IST ES!\n\nUnd die Antwort lautet...?\n\n\"IHR seid es.\" Bitte nehmt dieses Paket mit Gewürzen aus Mulgore und macht damit aus fadem, langweiligem Gewürzbrot Gewürzbrot aus MULGORE!", sourceObjective = "Kombiniert die Gewürze aus Mulgore mit Gewürzbrot, um 5 Laibe frisches Gewürzbrot aus Mulgore herzustellen (Ihr könnt Euer eigenes Gewürzbrot backen, oder welches aus anderen Quellen verwenden). Liefert die Brote bei Aska Nebelläufer in Donnerfels ab.", progress = "Habt Ihr schon das Gewürzbrot aus Mulgore gebacken?", completion = "Ooh, das Brot duftet aber köstlich. Ihr seid ja ein Meisterbäcker.\n\nWer weiß, wie weit diese exquisiten Laibe reisen werden... wie ich höre, sind sie sogar bei den Draenei auf der Azurmythosinsel beliebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29364] = { id = 29364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maisbrei", description = "Eins der wichtigsten Grundnahrungsmittel hier in Donnerfels ist Maismehl; in fast jedem Haushalt findet man Schüsseln mit Mais.\n\nDa so viele Mühlen im Land ständig von Harpyien, Gnollen, rücksichtslosen Bergbaugesellschaften und weiß die Erdenmutter wem angegriffen werden, bitte ich oft meine Lehrlinge, beim Maismahlen mitzuhelfen.\n\nWürdet Ihr vielleicht auch mit anfassen?", sourceObjective = "Helft den Bewohnern von Donnerfels, Maismehl herzustellen, indem Ihr Schüsseln mit Maiskörnern mahlt.", completion = "Es steckt viel Arbeit darin, genügend Maismehl für alle zu machen. Danke für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29365] = { id = 29365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfekt ausgewählte Portionen", description = "Selbst Einsteigerköche wissen, dass ein großartiges Gericht mit großartigen Zutaten beginnt.\n\nIch habe bei den Händlern von Donnerfels Daueraufträge, aber ich möchte gern sehen, wie ihr Euch dabei schlagt, die allerbesten Waren auszuwählen, die sie im Angebot haben.\n\nBitte geht von Händler zu Händler und besorgt mir perfekte Portionen Fleisch, Fisch, Gemüse und Kräuter.", sourceObjective = "Besorgt vier \"perfekte Portionen\" von den Händlern in Donnerfels. Liefert die Zutaten bei Aska Nebelläufer in Donnerfels ab.", progress = "Habt Ihr alle nötigen Zutaten gesammelt?", completion = "<Aska beäugt die Zutaten, die Ihr ausgewählt habt.>\n\nMmmhmmm. Ja. Gut gemacht!\n\nIch hätte sie selbst nicht besser auswählen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[29371] = { id = 29371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Zeit des Verlierens", description = "Seid gegrüßt, {class}. Während wir versuchen, uns an der Weidenmannzeremonie zu erfreuen, ist es nicht verwunderlich, dass die Horde versucht, unsere Feierlichkeiten zu ruinieren.\n\nDie schlauste Lösung wäre es wohl, einfach darüber zu stehen und diese Angriffe zu ignorieren.\n\nIch bewundere diejenigen, die das schaffen, doch ich kann ihnen nicht helfen. Doch denjenigen, die zurückschlagen möchten... denen kann ich helfen. Falls Ihr Interesse habt, {class}, nehmt dieses Löschmittel und setzt es gegen den Weidenmann der Horde in den Ruinen von Lordaeron ein.", sourceObjective = "Benutzt das Löschmittel gegen den Weidenmann in den Ruinen von Lordaeron.", sourceObjectiveStatus = "unverified-source-field" }
quests[29372] = { id = 29372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger in Posemuckel", description = "Gesetzlose haben den Sheriff entführt!", sourceObjective = "Rettet den Sheriff.", sourceObjectiveStatus = "unverified-source-field" }
quests[29373] = { id = 29373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger in Posemuckel", description = "Wir haben Sheriff Blundy niemals besonders viel Aufmerksamkeit geschenkt, wie er sich da ständig aufgeplustert hat wegen seinen \"Gesetzen\" und \"Fehl-ver-halt-en\". Aber den dreckigen alten McClintocks und ihrem Kuhtreiber von einem Vater vom Truckshawgrat hat es bis hier gestanden mit den ständigen Kerkerhaften und Verhandlungen und Sippenhaften und \"Tot oder lebendig!\"-Steckbriefen und da sind sie letzte Woche gekommen und haben das Gesetz in die eigenen Hände genommen - im wahrsten Sinne des Wortes - indem sie den guten Sheriff verschleppt haben.", sourceObjective = "Rettet den Sheriff.", sourceObjectiveStatus = "unverified-source-field" }
quests[29374] = { id = 29374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stinkbomben los!", description = "Die närrische Allianz hat Hexen eingestellt, um einen Angriff auf unsere Stadt durchzuführen. Na, wie meine Schwester mal gesagt hat: \"Gleiches Recht für alle!\".\n\nWir werden ihnen den Gefallen mit Freuden zurückzahlen. Sprecht mit meiner Schwester und sie wird Euch einen Ritt auf einem Besen über Sturmwind organisieren. Sobald Ihr Euch über Sturmwind befindet, solltet Ihr die Stinkbomben auf die Stadt und ihre Einwohner fallenlassen. Lasst sie leiden!\n\nWir werden diesen Hexen in Sturmwind schon zeigen, wer mächtiger ist.", sourceObjective = "Sprecht mit Crina Fenlow und nehmt einen Besen, um damit über Sturmwind zu fliegen. Benutzt die Stinkbomben, um die Stadt und ihre Einwohner damit zu bewerfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29375] = { id = 29375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufräumen in Unterstadt", description = "Seid gegrüßt, {class}! Genießt Ihr die Schlotternächte? Es scheint, dass die Allianz als Antwort auf unseren Stinkbombenangriff auf Sturmwind auch unsere Stadt mit Stinkbomben angreift.\n\nZum Glück verfügen wir über Magien, die mit dem Gestank der Allianz fertigwerden. Benutzt diesen Arkanreiniger, um die Stinkbomben aus der Stadt zu beseitigen.", sourceObjective = "Benutzt den Arkanreiniger, um die Stinkbomben in Unterstadt zu entfernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29376] = { id = 29376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Zeit des Aufbaus", description = "Wir verbrennen den Weidenmann als Symbol für unseren Kampf gegen diejenigen, die sich uns in den Weg stellen. Wir tragen die Asche des verbrannten Weidenmanns als Symbol für den niemals endenden Kampf gegen diejenigen, die uns versklaven wollen.\n\nBenutzt das nahe Lagerfeuer, um den Weidenmann zu entzünden. Nehmt Euch dann die herumliegende Asche und beschmiert Euer Gesicht damit.\n\nDiese Gesten werden unsere Feinde daran erinnern, dass wir niemals innehalten werden.", sourceObjective = "Benutzt das Freudenfeuer vor dem Weidenmann, um ihn in Brand zu stecken. Benutzt die Asche auf dem Boden in der Nähe des Weidenmanns.", sourceObjectiveStatus = "unverified-source-field" }
quests[29377] = { id = 29377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Zeit des Vandalismus", description = "Seid gegrüßt, {class}. Während wir versuchen, uns an der Weidenmannzeremonie zu erfreuen, ist es nicht verwunderlich, dass die Allianz versucht, unsere Feierlichkeiten zu ruinieren.\n\nWir haben die Möglichkeit, es ihnen heimzuzahlen. Falls Ihr Interesse habt, {class}, nehmt dieses Löschmittel und setzt es gegen den Weidenmann der Allianz vor Sturmwind ein.\n\nLöscht ihre Flamme und erfreut Euch an ihrem Leid.", sourceObjective = "Benutzt das Löschmittel gegen den Weidenmann vor Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[29382] = { id = 29382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Danke, aber nein danke", description = "Ein Feiertagspulli gefällt vielleicht nicht jedem.\n\nAuf dem Beleg steht, dass Ihr ihn bei jedem Händler der Kokelwälder gegen Gold umtauschen könnt.\n\nDer Umtausch lässt sich nicht rückgängig machen.", sourceObjective = "Wenn Euch Euer Geschenk wirklich nicht gefällt, dann könnt Ihr es gegen Gold eintauschen, indem Ihr mit einem Händler der Kokelwälder sprecht.\n\nDer Umtausch lässt sich nicht rückgängig machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29383] = { id = 29383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Danke, aber nein danke", description = "Ein Feiertagspulli gefällt vielleicht nicht jedem.\n\nAuf dem Beleg steht, dass Ihr ihn bei jedem Händler der Kokelwälder gegen Gold umtauschen könnt.\n\nDer Umtausch lässt sich nicht rückgängig machen.", sourceObjective = "Wenn Euch Euer Geschenk wirklich nicht gefällt, dann könnt Ihr es gegen Gold eintauschen, indem Ihr mit einem Händler der Kokelwälder sprecht.\n\nDer Umtausch lässt sich nicht rückgängig machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29385] = { id = 29385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Winterhauchgeschenk", sourceObjective = "Auf dem Schildchen des Geschenks steht:\n\nFrohe Feiertage, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[29386] = { id = 29386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Hyjal!", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Botschafterin Windweise in Nachthafen auf der Mondlichtung zu melden.\n\nUnsere Brüder im Zirkel des Cenarius haben uns berichtet, dass Todesschwinges Anhänger einen vernichtenden Angriff gegen den Weltenbaum gestartet haben und drohen, ihn zu verbrennen!\n\nSprecht mit Cenarius' Abgesandter Jademond in Sturmwind, um Zugang zur Mondlichtung zu erlangen.\n\nFür den Ruhm und die Ehre der Allianz! Auf in den Kampf, <Bruder/Schwester>!", sourceObjective = "Sprecht mit Cenarius' Abgesandter Jademond, um auf die Mondlichtung zu reisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29387] = { id = 29387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wächter des Hyjal: Die Invasion der Feuerlande!", description = "Die Wächter des Hyjal, angeführt von dem Erzdruiden Malfurion Sturmgrimm, suchen nach tapferen Helden, die bei einem großangelegten Angriff auf die Feuerlande helfen.\n\nFähige Helden der Allianz sollten sich augenblicklich beim Heiligtum von Malorne am Hyjal einfinden.", sourceObjective = "Meldet Euch bei Matookla beim Heiligtum von Malorne am Hyjal.", completion = "Danke, dass Ihr unserem Ruf gefolgt seid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29388] = { id = 29388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wächter des Hyjal: Die Invasion der Feuerlande!", description = "Die Wächter des Hyjal, angeführt von dem Erzdruiden Malfurion Sturmgrimm, suchen nach tapferen Helden, die bei einem großangelegten Angriff auf die Feuerlande helfen.\n\nFähige Champions der Horde sollten sich augenblicklich beim Heiligtum von Malorne am Hyjal einfinden.", sourceObjective = "Meldet Euch bei Matookla beim Heiligtum von Malorne am Hyjal.", completion = "Danke, dass Ihr unserem Ruf gefolgt seid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29389] = { id = 29389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wächter des Hyjal: Die Invasion der Feuerlande!", description = "Eure Arbeit hat uns den Vorteil verschafft, den wir brauchen, um gegen die Bewohner der Feuerlande zu mobilisieren. Genau in diesem Moment versammeln wir unsere Invasionsstreitkräfte südlich Eurer Position.\n\nWir könnten Eure Stärke ein weiteres Mal brauchen, {race}. Sprecht mit Matookla am Heiligtum von Malorne. Sie koordiniert die Invasionsanstrengungen.", sourceObjective = "Meldet Euch bei Matookla beim Heiligtum von Malorne am Hyjal.", completion = "Danke, dass Ihr unserem Ruf gefolgt seid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29390] = { id = 29390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wächter des Hyjal: Der Ruf der Uralten", description = "Die Wächter des Hyjal, angeführt von dem Erzdruiden Malfurion Sturmgrimm, suchen nach tapferen Helden, die helfen, den Hyjal vor den Elementarangreifern zu schützen. Diese Angreifer müssen zurückgedrängt werden, bevor Streitkräfte für den direkten Angriff auf die Feuerlande mobilisiert werden können.\n\nFähige Helden sollten sich augenblicklich am Hyjal einfinden und den uralten Verteidigern zu Hilfe kommen: Lo'Gosh, Tortolla, Aviana und Aessina.\n\nReisende, die sich zum ersten Mal zum Hyjal aufmachen, können sich nach einem Befehl des Kriegshäuptlings auf einem beliebigen Aufrufbrett der Horde umsehen.", sourceObjective = "Helft Lo'Gosh, Tortolla, Aviana und Aessina beim Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29391] = { id = 29391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wächter des Hyjal: Der Ruf der Uralten", description = "Die Wächter des Hyjal, angeführt von dem Erzdruiden Malfurion Sturmgrimm, suchen nach tapferen Helden, die helfen, den Hyjal vor den Elementarangreifern zu schützen. Diese Angreifer müssen zurückgedrängt werden, bevor Streitkräfte für den direkten Angriff auf die Feuerlande mobilisiert werden können.\n\nFähige Helden sollten sich augenblicklich am Hyjal einfinden und den uralten Verteidigern zu Hilfe kommen: Goldrinn, Tortolla, Aviana und Aessina.\n\nReisende, die sich zum ersten Mal zum Hyjal aufmachen, können sich nach einem Heldenaufruf auf einem beliebigen Aufrufbrett der Allianz umsehen.", sourceObjective = "Helft Goldrinn, Tortolla, Aviana und Aessina beim Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29392] = { id = 29392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisste Erbstücke", description = "Meine letzten Besitztümer hätten eigentlich heute aus Theramore eintreffen sollen. Das Schiff ist angekommen, aber ich habe nichts von dem Kurier gehört. Die Kiste, die er transportieren sollte, enthält Gegenstände, die schon seit Generationen im Familienbesitz sind.\n\nWürdet Ihr vielleicht hinunter zum Hafen von Sturmwind gehen und nachsehen, was ihn aufhält?", sourceObjective = "Durchsucht die Kabine auf dem Schiff des angeheuerten Kuriers im Hafen von Sturmwind nach Hinweisen, was den Kurier aufhalten könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[29393] = { id = 29393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebräu fürs Braufest", description = "Ihr wollt also die Rennwidder testen? Die Zwerge bilden sich ein, dass sie's besonders drauf hätten; aber seien wir mal ehrlich, die meiste Zeit sind sie ja sowieso betrunken, so schwer kann's also gar nicht sein!\n\nSo, bevor Ihr Euch ins Abenteuer stürzt, müsst Ihr mir zeigen, dass Ihr mit diesen feinen, auf legale Weise erworbenen Widdern umgehen könnt.\n\nJetzt zur Abmachung. Ich borge Euch Zügel und lasse Euch auf einem Widder reiten. Mal sehen, was Ihr drauf habt.\n\nLasst den Widder traben, dann leicht galoppieren und schließlich richtig galoppieren. Ihr müsst jede Geschwindigkeit 8 Sekunden lang halten.", sourceObjective = "Ihr habt 4 Minuten, um den Widder zu reiten und dabei 3 verschiedene Geschwindigkeitsstufen für jeweils 8 Sekunden zu halten.", completion = "Der Unfall auf dem Weg nach Messerbucht hat den Bierfluss ganz schön ins Stocken gebracht! Und es hilft natürlich überhaupt nicht, dass die Dunkeleisenzwerge gefühlt jede Stunde angreifen!\n\nWenn Ihr also helfen wollt, machen wir es so: Ich borge Euch Zügel und lasse Euch auf einem Widder reiten.\n\nJedes Mal, wenn Ihr mir einen Becher bringt, gebe ich Euch ein paar Abzeichen. Für jeden Becher, den Ihr mir bringt, werde ich Euch den Widder ein wenig länger nutzen lassen!\n\nABER: Wenn Ihr einmal damit angefangen habt, dann könnt Ihr es erst morgen erneut versuchen.\n\nSeid Ihr sicher, dass Ihr bereit seid, es zu versuchen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29394] = { id = 29394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebräu fürs Braufest", description = "Ihr wollt also die Rennwidder testen? Die Zwerge bilden sich ein, dass sie's besonders drauf hätten; aber seien wir mal ehrlich, die meiste Zeit sind sie ja sowieso betrunken, so schwer kann's also gar nicht sein!\n\nSo, bevor Ihr Euch ins Abenteuer stürzt, müsst Ihr mir zeigen, dass Ihr mit diesen feinen, auf legale Weise erworbenen Widdern umgehen könnt.\n\nJetzt zur Abmachung. Ich borge Euch Zügel und lasse Euch auf einem Widder reiten. Mal sehen, was Ihr drauf habt.\n\nLasst den Widder traben, dann leicht galoppieren und schließlich richtig galoppieren. Ihr müsst jede Geschwindigkeit 8 Sekunden lang halten.", sourceObjective = "Ihr habt 4 Minuten, um den Widder zu reiten und dabei 3 verschiedene Geschwindigkeitsstufen für jeweils 8 Sekunden zu halten.", completion = "Beim Braufest besteht immer Bedarf nach weiteren Bechern und Kharanos verfügt über jede Menge Becher, die sie entbehren können!\n\nIch werde Euch die Zügel zu einem meiner Privatwidder leihen.\n\nJedes Mal, wenn Ihr mir einen Becher bringt, gebe ich Euch ein paar Abzeichen. Für jeden Becher, den Ihr mir bringt, werde ich Euch den Widder ein wenig länger nutzen lassen!\n\nBeachtet aber: Wenn Ihr einmal damit angefangen habt, dann könnt Ihr es erst morgen erneut versuchen.\n\nSeid Ihr sicher, dass Ihr bereit seid, es zu versuchen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29396] = { id = 29396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neuer Souvenirlieferant", description = "<seufz>\n\nHört mir auf mit den Krügen vom letzten Jahr...\n\nIch glaube, dass diese zwielichtigen Bierkruglieferanten irgendwas mit diesem merkwürdigen Schattenhammerkult zu tun hatten, der aufgetaucht ist, bevor die Elementare eingefallen sind.\n\nUnd das ist der Grund, warum wir einen neuen Lieferanten und einen besseren Krug haben!\n\nHier habt Ihr einen Gutschein für einen Bierkrug.\n\nSprecht mit Blix in der Nähe des hinteren Endes des Braufestlagers. Er ist ziemlich seltsam, vor allem, weil er immer diese Brille aufhat. Er wird den Gutschein für Euch bearbeiten, und alle anderen Transaktionen des Braufests.", sourceObjective = "Löst Euren Gutschein für einen Braufestkrug bei Blix Fixtand im hinteren Teil des Braufestlagers ein.", progress = "Was ist los, Schätzchen? Habt Ihr etwas für mich?", completion = "Was ist das? Ein Gutschein für einen Braufestkrug? Ihr trinkt also gerne? Großartig! Sobald Ihr den Krug habt, solltet Ihr Euch ein paar Schluck gönnen... und noch ein paar mehr... und mehr... Dann, und das ist wichtig, kommt wieder hierher zu mir.\n\nIch weiß doch, dass Ihr wieder hierherkommt. Wenn Ihr Eure Gutscheine einlösen möchtet, dann müsst Ihr hierher zu mir.\n\nNaja, hier ist der Krug. Vergesst nicht, später noch einmal mit mir zu sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29397] = { id = 29397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neuer Souvenirlieferant", description = "Je weniger Worte wir über die Krüge vom letzten Jahr verlieren, je besser, {name}. Ich kann Euch sagen, die letzten Lieferanten, das waren zwielichtige Typen. Letztendlich hat sich herausgestellt, dass sie in irgendwelche Kultistenaktivitäten verwickelt waren...\n\nMit Leuten, die versuchen, die Welt zu zerstören, können wir nicht arbeiten!!\n\nDeshalb haben wir uns einen neuen Lieferanten und einen neuen Krug gesucht.\n\nBringt diesen Gutschein zu Belbi Blitzknips im hinteren Teil des Braufestlagers. Sie kümmert sich außerdem um alle sonstigen Braufestgeschäfte, die während der Festtage anstehen.", sourceObjective = "Löst Euren Gutschein für einen Braufestkrug bei Belbi Blitzknips im Braufestlager ein.", progress = "Was ist los, Schätzchen? Habt Ihr etwas für mich?", completion = "Ooch, es ist nur ein Gutschein für einen Braufestkrug... vielleicht gebt Ihr Euch ja auch nur so unnahbar. So, hier habt Ihr den diesjährigen Krug.\n\nIch nehme an, dass ich Euch noch öfter hier sehen werde. Denn wenn Ihr Eure Gutscheine einlösen möchtet, dann bin ich Euer Mädel hier...\n\noder vielleicht seins...\n\nooohhh... oder seins...", sourceObjectiveStatus = "unverified-source-field" }
quests[29398] = { id = 29398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hehlerware", description = "Eine schnelle Überprüfung der Kabine ergibt keine Hinweise auf die Identität des Mörders oder seine Motive. Die Kiste, wegen der Ihr gekommen seid, ist verschwunden.\n\nWährend Ihr Euch umdreht, um die Kabine zu verlassen, bemerkt Ihr, dass sich am Boden etwas Kleines bewegt. Eine Gruppe Spinnen kriecht unter dem Bett des erschlagenen Kuriers hervor. Wo könnten sie hinwollen?", sourceObjective = "Folgt den Spinnen zu ihrem Ziel und befragt den Mann, den Ihr dort findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29399] = { id = 29399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preise vergleichen", description = "Ich habe dem 'Herrn' gesagt, dass es da einen Laden im Zwergendistrikt gibt, der vielleicht besser geeignet ist für seine Bedürfnisse. Er heißt \"Schattenspiele\" und Ihr findet den Eingang in der Nähe der Kanäle auf der westlichen Seite des Distrikts.\n\nQuincy Messerschmied ist Euer Mann. Er handelt mit Waren, die ein ehrlicher Händler nicht mal mit der Kneifzange anfassen würde!", sourceObjective = "Begebt Euch zum Laden \"Schattenspiele\" im Zwergendistrikt von Sturmwind und sucht nach Hinweisen auf den Besuch des Kistendiebes.", sourceObjectiveStatus = "unverified-source-field" }
quests[29400] = { id = 29400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Zeit zum Feiern", description = "Frohe Grüße, {class}.\n\nDie Schlotternächte sind eine Zeit des Feierns und der Besinnlichkeit, obwohl es scheint, dass viele von uns vergessen haben, warum. Das Verbrennen des Weidenmanns im Besonderen ist ein Rätsel für viele außerhalb der Verlassenen.\n\nBegebt Euch zu den Ruinen von Lordaeron über Unterstadt und sprecht mit der Ruferin der Dunkelheit Yanka. Sie wird Euch mehr von der Weidenmannzeremonie erzählen.", sourceObjective = "Sprecht mit der Ruferin der Dunkelheit Yanka in den Ruinen von Lordaeron direkt außerhalb des Eingangs zu Unterstadt.", completion = "Die Weidenmannzeremonie ist eine ehrwürdige Tradition. Es ist schön zu sehen, dass die Horde sich uns in den Feierlichkeiten anschließt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29401] = { id = 29401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weggeweht", description = "Bitte, <Onkel/Tante>, Ihr müsst mir helfen!\n\nMein Papa hat mir auf dem Dunkelmond-Jahrmarkt ein paar Luftballons gekauft. Das beste Geschenk... aller... ZEITEN! Sie sind magisch, wisst Ihr, und sie verlieren nie ihre Schwebkraft!\n\nDa gibt es nur ein Problem...\n\nEin riesiger Windstoß hat sie mir direkt aus den Händen gerissen. Jetzt sind sie über ganz Orgrimmar verteilt!\n\nIch würde ja selber hinter ihnen herlaufen, aber die Stadt ist so groß, dass ich mich ganz sicher verlaufen würde.\n\nKönnt Ihr sie für mich einsammeln, bevor sie weggeweht werden?\n\nBitte?", sourceObjective = "Jaga möchte, dass Ihr 5 entflohene Ballons in Orgrimmar einsammelt.", progress = "Habt Ihr alle meine Ballons gefunden, Onkel?", completion = "Das ist so SUPER! Ihr habt es geschafft!\n\nDanke, Onkel!", sourceObjectiveStatus = "unverified-source-field" }
quests[29402] = { id = 29402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorsichtsmaßnahmen", description = "Ich wäre vorsichtig mit allen, die sich als rechtmäßige Besitzer der Kiste und ihres Inhalts ausgeben. Hat man Euch nicht vor der Gefahr gewarnt?\n\nHier ist eine bessere Idee: Lasst uns zusammenarbeiten, um die Kiste zurückzuholen und sicherzugehen, dass ihr Inhalt niemandem schadet. Um uns selbst zu schützen werden wir ein Gebräu benötigen, das aus einigen Ingredienzien besteht, die in der Stadt zu finden sind.\n\nKauft etwas seltsamen Staub bei einem Reagenzienhändler, besorgt Euch ein paar Phiolen von einem Alchemisten und sammelt ein paar Blutnesseln in den Feldern nördlich der Stadt.", sourceObjective = "Besorgt Euch 2 Portionen seltsamen Staub, 5 Kristallphiolen und 5 Blutnesseln.", sourceObjectiveStatus = "unverified-source-field" }
quests[29403] = { id = 29403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Agent des Sammlers", description = "Quincy zufolge ist der \"Sammler\", der die Kiste haben will, niemand anders als der wahnsinnige Erzmagier Xylem aus Azshara.\n\nDer treue Diener des Erzmagiers soll sich mit dem Mann, der die Kiste hat, in den Katakomben unterhalb der Kathedrale des Lichts treffen.\n\nIhr müsst Euch rechtzeitig dort einfinden, um den Austausch zu verhindern und die Kiste in Euren Besitz zu bringen, bevor sie für immer an Xylem verloren ist. Trefft mich im \"Goldenen Fass\", sobald Ihr die Kiste habt.", sourceObjective = "Unterbrecht das Treffen zwischen Sanath Lim-yo und dem Dieb in den Katakomben unterhalb der Kathedrale des Lichts.", sourceObjectiveStatus = "unverified-source-field" }
quests[29404] = { id = 29404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viel zu lernen", description = "Nun, da Eure Ausbildung begonnen hat, erhaltet Ihr Eure erste, recht simple Aufgabe: Sprecht mit Meister Shang Xi.", sourceObjective = "Sprecht mit Meister Shang Xi.", sourceObjectiveStatus = "unverified-source-field" }
quests[29405] = { id = 29405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lektion des Eisenstabes", description = "Für Eure Ausbildung müsst Ihr Euch zunächst einmal ausstatten. Beschafft Euch eine Waffe von einem der Waffenregale dort unten, bringt sie zu mir und zeigt mir, dass Ihr auch wisst, wie man sie richtig hält.", sourceObjective = "Nehmt eine Übungswaffe von einem Waffenregal und legt sie an.", sourceObjectiveStatus = "unverified-source-field" }
quests[29406] = { id = 29406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lektion der Sandfaust", description = "Ich würde gern beobachten, wie Ihr Euer neues Werkzeug einsetzt, <mein junger Schüler/meine junge Schülerin>. Das wird mir helfen, darüber zu entscheiden, welcher Grad der Ausbildung Euren Talenten am ehesten entspricht.\n\nWir haben dort unten auf dem Ausbildungsgelände eine Menge Übungsziele. Erprobt Eure Angriffe an ihnen und kehrt zu mir zurück, sobald Ihr ein Gefühl für Eure neue Ausrüstung entwickelt habt.", sourceObjective = "Zerstört 5 Übungsziele.", completion = "Gar nicht schlecht, {name}. Ihr scheint tatsächlich den richtigen Pfad gewählt zu haben.\n\nGut. Lasst uns fortfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[29408] = { id = 29408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lektion der brennenden Schriftrolle", description = "Jede Weisheit hat einen rechten Ort und eine rechte Zeit, aber die Zeiten ändern sich für all diejenigen, die auf Shen-zin Su leben. Für diese Lektion bitte ich Euch um zwei Dinge.\n\nZunächst halte ich eine Flamme in meiner Hand. Konzentriert Euch und versucht, sie mir zu entreißen, sobald Ihr Euch bereit fühlt.\n\nSolltet Ihr erfolgreich sein, möchte ich, dass Ihr den Tempel besteigt und das Edikt der Mäßigung verbrennt, das Ihr dort oben finden könnt.", sourceObjective = "Entreißt Meister Shang Xi die Flamme und verbrennt dann das Edikt der Mäßigung.", completion = "Dass Ihr mir die Flamme so einfach entreißen konntet, ist keine geringe Leistung.\n\nDas Edikt der Mäßigung ist eine Schriftrolle mit Weisheiten, die über unzählige Generationen hinweg überliefert worden sind. Weisheiten aus einer friedlicheren Zeit.\n\nJede Lehre hat einen rechten Ort und eine rechte Zeit... und nun, da sich die Dunkelheit am Horizont zusammenbraut, gehört die rechte Zeit dieser Weisheiten der Vergangenheit an.\n\nDas Verbrennen der Schriftrolle stellt die Akzeptanz dieser Zeichen und gleichzeitig ein Versprechen dar, zu handeln. Eure Hand trug die Flamme und ich bin gewiss, dass sie dies auch in Zukunft tun wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[29409] = { id = 29409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Schülers", description = "Ich sehe große Stärke, gewaltigen Mut und eine unübertroffene Reinheit der Seele in Euch, {name}.\n\nEure Ausbildung hat zwar gerade erst begonnen, aber ich denke, dass Ihr bereits für größere Aufgaben gewappnet seid.\n\nGeht die Treppen hinunter und überquert die Brücke. Dort werdet Ihr Jaomin Ro finden, einen unserer erfahrensten Schüler. Fordert ihn heraus und besiegt ihn in einem ehrenhaften Kampf - dadurch werdet Ihr den ersten Teil Eurer Ausbildung abschließen.", sourceObjective = "Besiegt Jaomin Ro.", completion = "Sehr beeindruckend, {name}. Es scheint, dass Ihr als {class} tatsächlich den richtigen Pfad gewählt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29410] = { id = 29410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aysa, Anhängerin der Tushui", description = "In so kurzer Zeit habt Ihr mir gezeigt, dass in Euch das Potenzial steckt, <ein wahrer Meister/eine wahre Meisterin> Eurer Klasse zu werden, {class}. Das Ausbildungsgelände liegt hinter Euch, und nun müsst Ihr Euch beweisen, indem Ihr eine ungleich größere Herausforderung annehmt, die bislang noch keiner meiner Schüler bewältigt hat.\n\nBitte kehrt zu Huo zurück, dem Geist des Feuers im Tempel der Fünf Sonnenaufgänge.\n\nMeine zwei besten Schüler neben Euch werden Euch bei dieser Aufgabe unterstützen. Sucht zunächst bitte Aysa Wolkensänger auf. Ihr findet sie beim Teich im Westen.", sourceObjective = "Sprecht mit Händler Lorvo bei Fus Teich.", completion = "Ihr sucht nach Aysa? Ihr... Ihr solltet sie besser nicht unterbrechen, bis sie mit ihren Übungen fertig ist. Sie spricht mit niemandem, bevor ihre Übung abgeschlossen ist.\n\nKönntet Ihr mir in der Zwischenzeit vielleicht behilflich sein? Ich hatte etwas Pech mit den Waldgeistern.", sourceObjectiveStatus = "unverified-source-field" }
quests[29411] = { id = 29411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was jetzt?", description = "Endlich habt Ihr die Kiste gefunden, die Anson Euch ausgeschickt hat, zurückzuholen. Es scheint allerdings, dass die Warnungen des Archäologielehrlings korrekt waren.\n\nEs besteht kein Zweifel, dass Euer Auftraggeber Euch bezüglich der Gefahren dieses Auftrags angelogen hat. Wollt Ihr ihm die Kiste wirklich übergeben oder wollt Ihr sie lieber Hudson Barnes geben, der glaubt, dass es besser wäre, den Inhalt der Kiste sicher zu verwahren?", sourceObjective = "Gebt die Kiste Anson Hastings in der \"Güldenen Rose\" in Sturmwind.\n\n-ODER-\n\nGebt die Kiste Hudson Barnes im \"Goldenen Fass\" in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[29412] = { id = 29412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weggeweht", description = "Bitte, <Onkel/Tante>, Ihr müsst mir helfen!\n\nMein Papa hat mir auf dem Dunkelmond-Jahrmarkt ein paar Luftballons gekauft. Das beste Geschenk... aller... ZEITEN! Sie sind magisch, wisst Ihr, und sie verlieren nie ihre Schwebkraft!\n\nDa gibt es nur ein Problem...\n\nEin riesiger Windstoß hat sie mir direkt aus den Händen gerissen. Jetzt sind sie über ganz Sturmwind verteilt!\n\nIch würde ja selber hinter ihnen herlaufen, aber die Stadt ist so groß, dass ich mich ganz sicher verlaufen würde.\n\nKönnt Ihr sie für mich einsammeln, bevor sie weggeweht werden?\n\nBitte?", sourceObjective = "Vin möchte, dass Ihr 5 entflohene Ballons in Sturmwind einsammelt.", progress = "Habt Ihr alle meine Ballons gefunden, Onkel?", completion = "Das ist so SUPER! Ihr habt es geschafft!\n\nDanke, Onkel!", sourceObjectiveStatus = "unverified-source-field" }
quests[29413] = { id = 29413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die unheimliche Kiste", description = "Nach ihr ist gesucht worden, sie wurde gestohlen und verkauft. Jeder, der versucht hat, die in ihr enthaltene Magie anzuzapfen, musste erleben, dass sich diese Macht gegen ihn wandte.\n\nUnd doch erscheint die Kiste selbst unversehrt zu sein und erfüllt von magischer Energie. Von Zeit zu Zeit zittert und hüpft sie, als ob ihr Inhalt lebendig wäre.\n\nSie scheint an Euch gebunden zu sein und jetzt gehört sie Euch." }
quests[29414] = { id = 29414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg der Tushui", description = "Es ist mir eine Freude, Eure Bekanntschaft zu machen, {class}. Ich heiße Aysa und bin eine Anhängerin der Tushui.\n\nIch habe viel Zeit mit Nachsinnen verbracht, seit Meister Shang mir offenbart hat, dass die Suche nach Huo, dem Geist des Feuers, unsere Aufgabe sein würde. Ich weiß, wo er sich aufhält, aber nicht, wie man zu ihm gelangen könnte. Die Antworten sind allerdings zum Greifen nah.\n\nFolgt mir zur Höhle der Meditation gleich in der Nähe. Sie ist ein Ort großer Weisheit. Ich werde dort meditieren und meinen Geist öffnen - dann wird der Weg sich uns offenbaren.", sourceObjective = "Beschützt Aysa, während sie meditiert.", completion = "Euer Weg ist vorgezeichnet. Ihr werdet derjenige sein, der den Geist des Feuers neu entfacht und ihn in die Sicherheit des Tempels zurückführt.\n\nDas wird nicht das letzte Mal sein, dass Ihr mit Aysa zusammenarbeitet. Sie ist stark und weise. Ihr könnt ihr vertrauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29415] = { id = 29415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisste Erbstücke", description = "Ich habe dem Kurier gesagt, dass er den Zeppelin nehmen soll, aber nein, er musste ja unbedingt ein Goblinschiff nehmen! Na ja, jetzt ist er verspätet und die wertvollen Erbstücke meiner Familie sind bei ihm.\n\nWenn Ihr helfen wollt, könntet Ihr vielleicht hinunter zu den Docks östlich von Orgrimmar gehen, Euch an Bord des Goblinschiffs begeben und nachsehen, was ihn aufhält?", sourceObjective = "Durchsucht die Kabine auf dem Schiff des angeheuerten Kuriers in den Docks östlich von Orgrimmar nach Hinweisen, was den Kurier aufhalten könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[29416] = { id = 29416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hehlerware", description = "Eine schnelle Überprüfung der Kabine ergibt keine Hinweise auf die Identität des Mörders oder seine Motive. Die Kiste, wegen der Ihr gekommen seid, ist verschwunden.\n\nWährend Ihr Euch umdreht, um die Kabine zu verlassen, bemerkt Ihr, dass sich am Boden etwas Kleines bewegt. Eine Gruppe Spinnen kriecht unter dem Bett des erschlagenen Kuriers hervor. Wo könnten sie hinwollen?", sourceObjective = "Folgt den Spinnen zu ihrem Ziel und befragt den Mann, den Ihr dort findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29417] = { id = 29417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg der Huojin", description = "Wir nennen diese teuflischen Affen, die über die Siedlung herfallen, Ho-zen. Normalerweise bleiben sie unter sich, aber sie spüren, dass irgendetwas Schlimmes bevorsteht, und fangen deshalb an, sich Vorräte zusammenzustehlen.\n\nFür ein Problem wie dieses gibt es nur eine Lösung - eine drastische Lösung. Diese Affen werden verschwinden, wenn wir sie dazu zwingen! Unsere Siedlung und damit diejenigen, die wir lieben, nicht zu verteidigen, wäre das wahre Verbrechen. Das ist der Weg der Huojin.", sourceObjective = "Tötet 8 Fe-Feng-Angreifer.", completion = "Ihr habt aber Mumm in den Knochen! Ich glaube, wir werden gut miteinander auskommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29418] = { id = 29418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Feuer entfachen", description = "Nun, da diese Angelegenheit erledigt ist, lasst uns also beginnen!\n\nHuo, der Geist des Feuers, hungert nach trockenen Hartriegelwurzelspänen. Hartriegel wächst im Wald südlich des Dorfes. Es sollte Euch ein Leichtes sein, ein paar Wurzeln zu sammeln.", sourceObjective = "Sammelt 5 trockene Hartriegelwurzeln.", progress = "Ich hoffe, dass Ihr Euch nicht zu fein seid, Euch die Hände schmutzig zu machen.", completion = "{name}! Ihr seid zurück - und wie ich sehe, habt Ihr die Wurzeln mitgebracht. Ihr seid kein Kerl, der lange fackelt, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[29419] = { id = 29419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Fahrer", description = "Mein Fahrer ist den Waldgeistern nachgerannt, kurz nachdem sie uns angegriffen hatten. Ich glaube nicht, dass sie ihm ernsthaft etwas zuleide tun werden, aber ich brauche ihn hier, damit er mir dabei helfen kann, dieses Durcheinander beim Karren in Ordnung zu bringen.\n\nEr hat sie in Richtung der Klippen im Norden gejagt. Wenn Ihr Euch dahin aufmacht, solltet Ihr ihn recht schnell finden können.", sourceObjective = "Rettet den Karrenfahrer.", completion = "Sehr liebenswürdig, {class}. Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[29420] = { id = 29420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wächter des Geistes", description = "Ihr habt Euch soweit gut geschlagen, <mein Schüler/meine Schülerin>. Ihr seid im Besitz der benötigten Materialien, um Huo, den Geist des Feuers, neu zu entfachen.\n\nEr erwartet Euch in der Höhle im Südwesten, aber er wird von Meister Li Fei bewacht, dem Pandarenältesten, dem Ihr in der Höhle der Meditation begegnet seid. Begebt Euch mit den Opfergaben zu ihm. Beweist Euch und findet dann Huo.", sourceObjective = "Sprecht mit Meister Li Fei im Schrein des Inneren Lichts.", completion = "Im Leben geht es nicht darum, sich selbst zu finden. Es geht darum, sich selbst zu formen. Es liegt ein Weg vor Euch, aber Ihr selbst wählt die Prüfungen, denen Ihr gegenübersteht, und die Prüfungen, die Ihr bestehen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29421] = { id = 29421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur die Würdigen dürfen passieren", description = "Es ist an der Zeit, dass Ihr mir gegenübertretet. Nun, da diese drei Feuer Euer wahres Potenzial erhellen, werden wir Gewissheit darüber erhalten, ob Eure entschlossene Seele wirklich würdig genug ist, um passieren zu dürfen.", sourceObjective = "Besiegt Meister Li Fei im Kampf.", completion = "Erinnert Euch stets daran, dass der überlegene Krieger durch seine Taten glänzen, aber seine Worte maßvoll wählen sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[29422] = { id = 29422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Huo, der Geist des Feuers", description = "Ihr habt Euch als würdig erwiesen, {class}.\n\nHuo, der Geist des Feuers, ruht in der Kammer hinter uns. Lasst ihn sich an den Spänen, die Ihr gesammelt habt, nähren und benutzt den Wind, um seine Flammen anzufachen. Indem Ihr dies tut, werdet Ihr ihn Euch geneigt stimmen. Sobald er entfacht - und gewillt - ist, führt ihn zurück zum Tempel der Fünf Sonnenaufgänge, dem hoch aufragenden Gebäude im Zentrum der Insel.", sourceObjective = "Entfacht Huo, den Geist des Feuers, von Neuem.", completion = "<Durch das grelle Licht hindurch sieht es fast so aus, als würde Huo lächeln. Er scheint sich für Euch zu erwärmen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[29423] = { id = 29423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Passion von Shen-zin Su", description = "<Huo springt aufgeregt hin und her. Er ist offensichtlich bereit, Euch zu folgen.>\n\n<Meister Shang Xi hat Euch aufgetragen, Huo zu ihm in den Tempel der Fünf Sonnenaufgänge im Zentrum der Insel zu bringen. Ihr solltet Euch auf den Weg machen.>", sourceObjective = "Bringt den Geist des Feuers in den Tempel der Fünf Sonnenaufgänge.", completion = "{name}, Ihr habt Euch sehr gut geschlagen. Huo, der Geist des Feuers, ist hier. Die Flammen des Tempels sind neu entfacht. Ihr habt Eure letzte Herausforderung bestanden, und ohne große Mühe, wie es scheint.\n\nEs gibt auch einen sehr guten Grund dafür, Huo in den Tempel zu bringen. Es ist an der Zeit, dass ich Euch mehr über die bevorstehenden Ereignisse erzähle.", sourceObjectiveStatus = "unverified-source-field" }
quests[29424] = { id = 29424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegenstände von äußerster Wichtigkeit", description = "Honigblattstrolche haben meinen Karren umzingelt und die meisten der Übungsmaterialien gestohlen, die ich gerade zum Ausbildungsgelände bringen wollte. Sie waren schon immer Unruhestifter, aber sie sind noch nie so aggressiv gewesen. Ich weiß nicht, was mit ihnen passiert ist.\n\nIch bitte Euch, helft mir, die Materialien wiederzubeschaffen!", sourceObjective = "Beschafft 6 Übungsmaterialien von den Honigblattstrolchen wieder.", progress = "Ihr braucht Euch keine Sorgen darüber zu machen, den Waldgeistern etwas zuleide zu tun. Im Endeffekt sind sie einfach nur sehr quirlige Pflanzen - sie werden schon wieder aufsprießen.", completion = "Vielen Dank! Ihr seid ein ehrenhafter {class}. Eure Ausbildung trägt schon jetzt Früchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[29425] = { id = 29425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preise vergleichen", description = "Passt auf, ich habe diesem zwielichtigen Kerl gesagt, dass es da einen Laden in der Gasse gibt, der seinen, ähm, Waren vielleicht offener gegenübersteht. \"Droffers und Sohn Bergungen\" ist der Name des Geschäfts.\n\nHaltet nach Dran Droffers Ausschau. Er überwacht die 'Bergung' von seltenen und wertvollen Gegenständen aus ganz Azeroth.", sourceObjective = "Begebt Euch zum Laden \"Droffers und Sohn Bergungen\" in der Gasse in Orgrimmar und sucht nach Hinweisen auf den Besuch des Kistendiebes.", sourceObjectiveStatus = "unverified-source-field" }
quests[29426] = { id = 29426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorsichtsmaßnahmen", description = "Es hat Euch also jemand anders angeheuert, um diese Kiste zu besorgen? Das hört sich für mich gar nicht gut an.\n\nDer Inhalt dieser Kiste gehört unter die Aufsicht der Archäologischen Akademie. Die in ihr enthaltenen Gegenstände sind sehr mächtig und sehr gefährlich.\n\nWir müssen zu dem Treffen gehen, dass Dran zwischen dem Dieb und dem Sammler vereinbart hat, aber zunächst müssen wir uns vor den Effekten schützen, die der Umgang mit der Kiste mit sich bringt.\n\nKauft etwas seltsamen Staub bei einem Reagenzienhändler, besorgt Euch ein paar Phiolen von einem Alchemisten und sammelt ein paar Blutnesseln im Tal der Weisheit.", sourceObjective = "Besorgt Euch 2 Portionen seltsamen Staub, 5 Kristallphiolen und 5 Blutnesseln.", sourceObjectiveStatus = "unverified-source-field" }
quests[29427] = { id = 29427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Agent des Sammlers", description = "Dran zufolge ist der \"Sammler\", der die Kiste haben will, niemand anders als der wahnsinnige Erzmagier Xylem aus Azshara.\n\nDer treue Diener des Erzmagiers soll sich mit dem Mann, der die Kiste hat, in einer versteckten Ecke im Hof der Ruinen von Lordaeron treffen.\n\nSchnell, nehmt den Zeppelin nach Tirisfal!\n\nIhr müsst Euch rechtzeitig dort einfinden, um den Austausch zu verhindern und die Kiste in Euren Besitz zu bringen, bevor sie für immer an Xylem verloren ist. Trefft mich im \"Wyvernschweif\" im Tal der Ehre, sobald Ihr die Kiste habt.", sourceObjective = "Unterbrecht das Treffen zwischen Sanath Lim-yo und dem Dieb in den Ruinen von Lordaeron.", sourceObjectiveStatus = "unverified-source-field" }
quests[29428] = { id = 29428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was jetzt?", description = "Endlich habt Ihr die Kiste gefunden, die Edgar Euch ausgeschickt hat, zurückzuholen. Es scheint allerdings, dass die Warnungen des Repräsentanten der Archäologischen Akademie korrekt waren.\n\nEs besteht kein Zweifel, dass Euer Auftraggeber Euch bezüglich der Gefahren dieses Auftrags angelogen hat. Wollt Ihr ihm die Kiste wirklich übergeben oder wollt Ihr sie lieber Delian Sonnenschatten geben, der glaubt, dass es besser wäre, den Inhalt der Kiste sicher zu verwahren?", sourceObjective = "Ihr könnt die Kiste entweder Edgar Siegesfroh im \"Gebrochenen Hauer\" in Orgrimmars Tal der Stärke zurückbringen.\n\n-ODER-\n\nIhr könnt die Kiste Delian Sonnenschatten im \"Wyvernschweif\" in Orgrimmars Tal der Ehre übergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[29429] = { id = 29429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die unheimliche Kiste", description = "Nach ihr ist gesucht worden, sie wurde gestohlen und verkauft. Jeder, der versucht hat, die in ihr enthaltene Magie anzuzapfen, musste erleben, dass sich diese Macht gegen ihn wandte.\n\nUnd doch erscheint die Kiste selbst unversehrt zu sein und erfüllt von magischer Energie. Von Zeit zu Zeit zittert und hüpft sie, als ob ihr Inhalt lebendig wäre.\n\nSie scheint an Euch gebunden zu sein und jetzt gehört sie Euch." }
quests[29430] = { id = 29430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Freund in der Not", description = "Wisst Ihr, ich habe Anson noch gar nicht hier draußen gesehen.\n\nIn letzter Zeit verbringt er seine ganze Zeit damit, sich in der \"Güldenen Rose\" volllaufen zu lassen.\n\nEtwas muss ihm wirklich an die Nieren gehen! Würdet Ihr vielleicht mal nach ihm sehen?", sourceObjective = "Besucht Anson Hastings in der \"Güldenen Rose\" in Sturmwinds Handelsdistrikt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29431] = { id = 29431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Freund in der Not", description = "Mit meinem Freund Edgar ist etwas nicht in Ordnung. Normalerweise liebt er die Festivitäten rund um die Schlotternächte.\n\nEr verbringt seine ganze Zeit damit, in der Kneipe \"Zum Gebrochenen Hauer\" in Orgrimmar mit den Orcs zu trinken. Wäret Ihr so gut und würdet mal bei ihm vorbeischauen und nachsehen, ob es irgendwas gibt, womit man ihn aufmuntern könnte?", sourceObjective = "Sprecht mit Edgar Siegesfroh im \"Gebrochenen Hauer\" in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[29433] = { id = 29433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweist Eure Stärke", description = "Einige Leute haben so lange Spaß, bis jemand verletzt wird. Ich nenne solche Leute Schwächlinge.\n\nWahre Stärke beweist nur der, der jemanden oder etwas verletzt. Ihr verletzt Euch selbst, weil Ihr Euren Körper an seine Grenzen führt, und Ihr verletzt die, die anderen schaden wollen.\n\nWenn Ihr der Stärkste sein wollt, müsst Ihr kämpfen. Wie wichtig ist Euch das?\n\nIch will, dass Ihr die niederstreckt, die Euch herausfordern und mir einen Beweis Eures Triumphs bringt.", sourceObjective = "Kerri Hicks möchte, dass Ihr 250 grausige Trophäen erbeutet. Um sie zu bekommen, müsst Ihr Wesen töten, die Euch Erfahrung oder Ehre gewähren und den Abenteuerführer des Dunkelmond-Jahrmarkts bei Euch tragen.", progress = "Ohne Fleiß kein Preis.", completion = "Habt Ihr Euch Herausforderungen gesucht oder einfach nur Eber auf einem Feld abgeschlachtet?\n\nIch bin aus gutem Grund die Stärkste.\n\nVielleicht werde ich Euch eines Tages zeigen, wie stark ich wirklich bin, {class}. Bis dahin müsst Ihr Euch weiter anstrengen, aber vergesst nicht, ab und zu eine Pause zu machen.\n\nSo wie jetzt zum Beispiel. Hier, genießt den Dunkelmond-Jahrmarkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29434] = { id = 29434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Panzergeneral", description = "Willkommen zu unserem bescheidenen kleinen Dampfpanzerkampf-Simulator! Für nur einen Spieljeton könnt Ihr Euer strategisches Können unter Beweis stellen. Fahrt über unseren Parcours und zerstört die Panzerziele.", sourceObjective = "Zerstört mit Eurem Dunkelmond-Panzer 30 Ziele in der veranschlagten Zeit.", progress = "Aufgetankt und einsatzbereit!", completion = "Eine beeindruckende Demonstration!\n\nHier ist Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[29436] = { id = 29436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die menschliche Kanonenkugel", description = "Für nur einen Spieljeton des Dunkelmond-Jahrmarkts könnt Ihr Euch aus der Blastenheimer 5000 Ultrakanone abschießen lassen. Doch damit ist der Spaß noch nicht vorbei! Wir haben ein Ziel im Meer nahe des Piers aufgebaut.\n\nWenn Ihr bei Euren Landungen fünf Punkte erzielt, könnt Ihr Gewinnlose bekommen.\n\nEin Treffer ins Schwarze bringt 5 Punkte, einer ins Ziel 3 Punkte und einer knapp neben dem Ziel 1 Punkt.\n\nViel Glück bei der Landung!", sourceObjective = "Erreicht 5 Kanonenzielpunkte, indem Ihr in der Nähe des Kanonenziels landet.", progress = "Hals und Beinbruch!", completion = "5 Punkte? Gut gemacht! Hier sind Eure Lose.\n\nViel Spaß auf dem Rest des Dunkelmond-Jahrmarkts!", sourceObjectiveStatus = "unverified-source-field" }
quests[29437] = { id = 29437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gefallene Wächter", description = "Fandral Hirschhaupt ist hier auf dem Hyjal gefangen gehalten worden. Es war der grüne Drache Alysra - eine von uns! -, die damit beauftragt war, Fandral zu bewachen.\n\nWir können nur vermuten, dass es dem Schattenhammer gelungen ist, sie zu verderben. Ihr müsst sie stellen, {name}. Vernichtet sie, wenn es sein muss - ich kann es nicht ertragen, dabei zuzusehen.\n\nZuletzt wurde sie bei den Ruinen von Lar'donir gesichtet, westlich des Weltenbaums.", sourceObjective = "Stellt und tötet Alysra bei den Ruinen von Lar'donir.", sourceObjectiveStatus = "unverified-source-field" }
quests[29438] = { id = 29438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er schießt, er trifft!", description = "Glaubt Ihr, dass Ihr gut schießen könnt? Habt Ihr eine ruhige Hand?\n\nWie wäre es dann mit ein paar Schüssen?\n\nEs kostet Euch nur einen Spieljeton, Eure Fähigkeiten unter Beweis zu stellen.\n\nNa, wie gut seid Ihr?", sourceObjective = "Erreicht 25 Punkte in 60 Sekunden.", progress = "Ein stehendes Ziel zu treffen, ist nicht so einfach, wie es aussieht.", completion = "Ich wusste, dass Ihr das schafft, {class}. Hier ist Euer Preis. Genießt den Jahrmarkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29439] = { id = 29439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Weltenschamanen", description = "Der Irdene Ring bittet Euch erneut um Eure Mithilfe, {name}.\n\nAls ein Mitglied der Allianz weiß ich, dass Ihr möglicherweise Bedenken hegt, mit dem, den Ihr Thrall nennt, dem früheren Kriegshäuptling der Horde, zusammenzuarbeiten. Aber er hat explizit darum gebeten, dass es ein Held der Allianz ist, der ihm bei seiner nächsten Unternehmung zur Seite steht, bei einem Heilungsritual, das tiefgreifende Auswirkungen auf unsere Welt haben wird.\n\nLasst Eure Zweifel beiseite, {class}, und antwortet dem Ruf des Weltenschamanen.\n\nIhr werdet ihn unter den Zweigen von Nordrassil auf dem Hyjal finden, auf der südlichen Seite des Baums.", sourceObjective = "Sprecht mit Thrall, direkt südlich des Weltenbaums auf dem Hyjal.", completion = "Es scheint, als wäre meine Nachricht in Sturmwind angekommen.\n\nIch danke Euch, {name}. Dann wollen wir uns mal an die Arbeit machen...", sourceObjectiveStatus = "unverified-source-field" }
quests[29440] = { id = 29440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Weltenschamanen", description = "Der Irdene Ring bittet Euch erneut um Eure Mithilfe, {name}.\n\nThrall hat sein Amt als Kriegshäuptling der Horde niedergelegt, aber für seine neue Aufgabe benötigt er die Unterstützung seines Volkes mehr als je zuvor. Er hat darum gebeten, dass einer der besten Streiter der Horde ihm bei seiner nächsten Unternehmung zur Seite steht, bei einem Heilungsritual, das tiefgreifende Auswirkungen auf unsere Welt haben wird.\n\nIhr werdet ihn unter den Zweigen von Nordrassil auf dem Hyjal finden, auf der südlichen Seite des Baums.", sourceObjective = "Sprecht mit Thrall, direkt südlich des Weltenbaums auf dem Hyjal.", completion = "Es scheint, als wäre meine Nachricht in Orgrimmar angekommen.\n\nIch danke Euch, {name}. Dann wollen wir uns mal an die Arbeit machen...", sourceObjectiveStatus = "unverified-source-field" }
quests[29441] = { id = 29441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus dem Bauch der Bestie" }
quests[29443] = { id = 29443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein merkwürdiger Kristall", description = "Energie wirbelt in dem seltsamen Kristall umher. Vielleicht diente er einst als magischer Brennpunkt, als Energiequelle oder als simpler Glücksbringer. Das lässt sich nicht sicher sagen.\n\nDer Abenteuerführer des Dunkelmond-Jahrmarkts weist Euch darauf hin, dass sich Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt dafür interessieren könnte.", sourceObjective = "Bringt den energiegetränkten Kristall zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", progress = "Was habt Ihr denn da?", completion = "Wo habt Ihr den her?\n\nSolche Kristalle sind sehr selten, viele Sammler suchen danach. Ich würde diesen gern untersuchen und auf dem Jahrmarkt ausstellen. Würdet Ihr ihn gegen eine großzügige Anzahl von Losen des Dunkelmond-Jahrmarkts eintauschen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29444] = { id = 29444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein exotisches Ei", description = "Ihr seid Euch nicht sicher, welches Wesen sich in diesem Ei befindet, aber das Ei stammt sicherlich nicht von einem normalen Tier.\n\nIm Abenteuerführer des Dunkelmond-Jahrmarkts heißt es, ein unerschrockener Abenteurer könne bei seinen Reisen auf eine ganze Reihe seltsamer Eier stoßen. Außerdem weist er darauf hin, dass das Kuriositätenkabinett auf dem Dunkelmond-Jahrmarkt stets am Erwerb solcher Exemplare interessiert ist.\n\nBringt das Ei zu Yebb Nabetand auf dem Dunkelmond-Jahrmarkt.", sourceObjective = "Bringt das monströse Ei zu Yebb Nabetand auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", progress = "Was habt Ihr denn da?", completion = "Wo habt Ihr dieses Ei gefunden? Darin verbirgt sich sicherlich etwas Monströses und Wunderbares. Ein sehr passender Neuzugang für unseren Zoo. Würdet Ihr Euch davon für eine großzügige Anzahl Lose des Dunkelmond-Jahrmarkts trennen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29445] = { id = 29445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein faszinierender Zauberfoliant", description = "Ihr findet keinen Hinweis auf den Ursprung dieses gewaltigen magischen Werkes. Seine Seiten sind voll mit Zaubern und Verzauberungen, von denen Euch nur einige wenige vertraut sind.\n\nIm Abenteuerführer des Dunkelmond-Jahrmarkts steht, der Foliant könnte für Sayge, den berühmten gnollischen Jahrmarktswahrsager auf dem Dunkelmond-Jahrmarkt, von Interesse sein.", sourceObjective = "Bringt den geheimnisvollen Zauberfolianten zu Sayge auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", progress = "Was habt Ihr denn da?", completion = "Ein seltsamer Zauberfoliant, wie interessant! So einen habe ich noch nie gesehen. Ich hätte ihn sehr gern für meine Sammlung. Würdet Ihr ihn gegen Lose des Dunkelmond-Jahrmarkts eintauschen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29446] = { id = 29446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine wundersame Waffe", description = "Ihr untersucht die Waffe und seht, dass sie hervorragend verarbeitet und edel verziert ist. Einige winzige Scharten weisen darauf hin, dass sie auch im Kampf benutzt wurde.\n\nIm Abenteuerführer des Dunkelmond-Jahrmarkts sind verschiedene seltene und wertvolle Waffen aufgeführt, daher würde sich Professor Thaddeus Paleo vom Dunkelmond-Jahrmarkt bestimmt für dieses Stück interessieren.", sourceObjective = "Bringt die verzierte Waffe zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", progress = "Was habt Ihr denn da?", completion = "Wo habt Ihr eine solch wundervolle Klinge gefunden?\n\nWas für eine Verarbeitung! Das ist wahrlich eine Waffe, mit der sich jeder Held schmücken könnte. Ich würde sie sehr gern ausstellen.\n\nWürdet Ihr eine großzügige Anzahl Lose des Dunkelmond-Jahrmarkts dafür annehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29451] = { id = 29451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Meisterstratege", description = "Dieser Foliant über Strategie ist das Meisterwerk des berühmten menschlichen Generals Anduin Lothar. Darin beschreibt der Kommandant in seinen eigenen Worten die korrekte Aufstellung einer Armee und Strategien, mit denen man fast jede Schlacht gewinnen kann.\n\nProfessor Thaddeus Paleo vom Dunkelmond-Jahrmarkt würde sich bestimmt für ein so seltenes Buch interessieren.", sourceObjective = "Bringt die Abhandlung zu strategischem Vorgehen zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", progress = "Das sieht nach einem sehr seltenen Buch aus…", completion = "Ich weiß nicht, wie Ihr daran gekommen seid und ich bin klug genug, nicht zu fragen. Würdet Ihr Euch für Lose des Dunkelmond-Jahrmarkts davon trennen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29452] = { id = 29452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure Zeit ist gekommen", description = "<Ein angenehmes Bild erscheint vor Eurem inneren Auge, als eine ruhige Stimme Euren Körper erfüllt.>\n\n<Junger/Junge:c> {class}, seid ganz ruhig und hört meine Worte.\n\nIch wurde gerufen, um Euch abzuholen und abzuliefern, bei jemandem, dessen Blick niemand entkommt.\n\nFindet mich in Orgrimmar, sterbliches Wesen, denn Eure Zeit ist gekommen.", sourceObjective = "Sprecht mit Ziradormi in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[29453] = { id = 29453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure Zeit ist gekommen", description = "<Ein angenehmes Bild erscheint vor Eurem inneren Auge, als eine ruhige Stimme Euren Körper erfüllt.>\n\n<Junger/Junge:c> {class}, seid ganz ruhig und hört meine Worte.\n\nIch wurde gerufen, um Euch abzuholen und abzuliefern, bei jemandem, dessen Blick niemand entkommt.\n\nFindet mich in Sturmwind, sterbliches Wesen, denn Eure Zeit ist gekommen.", sourceObjective = "Sprecht mit Coridormi in Sturmwind.", completion = "Lasst uns beginnen, sterbliches Wesen.\n\nWir haben keine Zeit zu verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29455] = { id = 29455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werft den Ring", description = "Hey Ihr! Haltet ein!\n\nWollt Ihr allen beweisen, wie talentiert Ihr seid? Sorgt dafür, dass drei Ringe auf der Dunkelmond-Schildkröte landen, dann bekommt Ihr eine Belohnung.\n\nFür einen Spieljeton könnt Ihr einen Stapel Ringe kaufen, um der Welt zu zeigen, warum wir Euch auf dem Jahrmarkt {name}, \"<den Adleräugigen/die Adleräugige>\" nennen.", sourceObjective = "Werft 3 Ringe auf die Dunkelmond-Schildkröte.", progress = "Geht's dem Wurfarm gut?", completion = "Ich wusste, dass Ihr das könnt, {class}. Gebt uns die restlichen Ringe, falls welche übrig sind, dann bekommt Ihr Euer Gewinnlos.", sourceObjectiveStatus = "unverified-source-field" }
quests[29456] = { id = 29456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein erbeutetes Banner", description = "Auf dem zerschlissenen Banner ist ein verblasstes Gildenwappen zu sehen. Das alte Banner muss viele Schlachten mitgemacht haben.\n\nProfessor Thaddeus Paleo vom Dunkelmond-Jahrmarkt sammelt Banner und andere Kriegsrelikte. Vielleicht wäre er auch an diesem interessiert. Zeigt ihm das Banner, wenn Ihr den Dunkelmond-Jahrmarkt das nächste Mal besucht.", sourceObjective = "Bringt das Banner der Gefallenen zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", progress = "Was habt Ihr denn da?", completion = "Was für ein wundervolles Banner! Das hätte ich gerne in meiner Sammlung.\n\nWürdet Ihr es mir für einige Lose des Dunkelmond-Jahrmarkts überlassen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29457] = { id = 29457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Insigne des Feindes", description = "Das Insigne eines gegnerischen Offiziers ist auf dem zerbeulten Abzeichen zu sehen. Für Euch ist es kaum mehr wert als das Metall, aus dem es besteht, aber für einen Sammler von Kriegsandenken wäre es von großem Interesse.\n\nDie Sammlung von Kriegsartefakten, die Professor Thaddeus Paleo vom Dunkelmond-Jahrmarkt zusammengetragen hat, ist in ganz Azeroth bekannt. Zeigt ihm das Abzeichen, wenn Ihr den Dunkelmond-Jahrmarkt das nächste Mal aufsucht.", sourceObjective = "Bringt das eroberte Insigne zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", progress = "Was habt Ihr denn da?", completion = "Das ist ein bemerkenswert gut erhaltenes Offiziersinsigne der Allianz. Viele Offiziere besuchen zwar den Jahrmarkt, aber keiner von ihnen will sich von seinen Abzeichen trennen. Würdet Ihr einige Lose des Dunkelmond-Jahrmarkts dafür annehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29458] = { id = 29458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das erbeutete Tagebuch", description = "Der Umschlag des Buches besteht aus abgewetztem, mit Blut und Schlamm besudeltem Leder. Ihr blättert die Seiten durch und erkennt, dass es sich um das Tagebuch eines Abenteurers handelt, der sehr von sich und seinen Abenteuern eingenommen ist.\n\nProfessor Thaddeus Paleo vom Dunkelmond-Jahrmarkt könnte sich dafür interessieren.", sourceObjective = "Bringt das Tagebuch eines Abenteurers zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", progress = "Was habt Ihr denn da?", completion = "Ein bemerkenswerter Fund!\n\n<Der Professor blättert in dem Buch.>\n\nEinige Seiten sind kaum noch lesbar, aber wenn auch nur ein Drittel des Inhalts der Wahrheit entspricht, handelt es sich um einen wahren Schatz. Würdet Ihr es gegen eine großzügige Anzahl Lose des Dunkelmond-Jahrmarkts eintauschen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29463] = { id = 29463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hau-den-Gnoll", description = "Wollt Ihr ein paar Gnolle hauen? Dann seid Ihr am richtigen Ort.\n\nEure Aufgabe ist einfach: Erreicht 30 Punkte in einer Minute.\n\nBenutzt den Holzhammer, den ich Euch geben werde und legt los. Sprecht mich an, wenn Ihr bereit seid.", sourceObjective = "Erreicht 30 Punkte beim Gnollhauen.", progress = "Wie habt Ihr Euch geschlagen?", completion = "Ihr habt die Gnolle also besiegt. Fühlte sich gut an, oder?\n\nHier ist Euer Preis. Genießt den Rest des Dunkelmond-Jahrmarkts!", sourceObjectiveStatus = "unverified-source-field" }
quests[29464] = { id = 29464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werkzeuge der Weissagung", description = "Diese Sammlung abgenutzter Runensteine wurde offensichtlich häufig benutzt. Die Steine wirken alt. Ihr könnt die Einkerbungen auf ihnen nicht zuordnen.\n\nEin Gelehrter oder Sammler könnte mehr darüber wissen. Bringt sie zu Professor Thaddeus Paleo, wenn Ihr den Dunkelmond-Jahrmarkt das nächste Mal besucht.", sourceObjective = "Bringt die Wahrsagerrunen zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", progress = "Was habt Ihr denn da?", completion = "Wo habt Ihr diese Runensammlung her? So eine habe ich seit Jahren nicht mehr gesehen. Es wird mir eine Freude sein, ihr Rätsel zu entschlüsseln!\n\nWürdet Ihr einige Lose des Dunkelmond-Jahrmarkts dafür annehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29469] = { id = 29469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederbewaffnung, Wiederverwendung, Wiederverwertung", description = "Die Jahrmarktsbesucher lieben unsere Dampfpanzer! Wenn der Dunkelmond-Jahrmarkt schließt, liegt all der Panzerschrott auf dem Platz herum.\n\nWäre doch schade, wenn das gute Metall einfach im Dreck verrotten würde.\n\nWäret Ihr so nett, mir einige der größeren Stücke zu bringen, damit ich die kaputten Panzerteile damit reparieren kann? Das ist weitaus billiger als jedes Mal neues Metall zu kaufen. Was meint Ihr?", sourceObjective = "Beschafft 6 Stücke Panzerschrott vom Lagerplatz des Dunkelmond-Jahrmarkts.", sourceObjectiveStatus = "unverified-source-field" }
quests[29475] = { id = 29475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gobliningenieurskunst", description = "Ein geübter Ingenieur kann sich für EINE Spezialisierung entscheiden. Ich kenne die Geheimnisse der Gobliningenieurskunst.\n\nIhr seht aus, als würdet Ihr gern Dinge in die Luft jagen, aber ich benötige Proben Eurer Arbeit. Bringt mir zwanzig große Eisenbomben, zwanzig Stangen robustes Dynamit und fünf explodierende Schafe.\n\nWenn Ihr diese Gegenstände zu einem Ingenieurskunstlehrer in einer beliebigen Hauptstadt bringt, wird er Euch offiziell zum Gobliningenieur mit Zugang zu allen Bauplänen ernennen!", sourceObjective = "Bringt 20 große Eisenbomben, 20 Stangen robustes Dynamit und 5 explodierende Schafe zu einem Ingenieurskunstlehrer in einer beliebigen Hauptstadt.", progress = "Überlasst mir Eure gefertigten Ingenieurskunstgegenstände zur Bewertung, dann werde ich Euch das Wissen vermitteln, das Ihr benötigt, um Mitglied im exklusiven Club der Gobliningenieure zu werden.", completion = "Anscheinend seid Ihr tatsächlich bereit für eine richtige Ausbildung. Hiermit ernenne ich Euch zum Gobliningenieur, {name}!\n\nIhr könnt Euch die teuflischen Erfindungen aller Gobliningenieure ansehen. Genießt es und versucht, Euch nicht in die Luft zu sprengen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29477] = { id = 29477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomeningenieurskunst", description = "Ein geübter Ingenieur kann sich für EINE Spezialisierung entscheiden. Ich kann Euch die Gnomeningenieurskunst beibringen.\n\nIhr scheint zwar zu wissen, was Ihr tut, aber ich benötige einige Proben Eurer Arbeit. Bringt mir sechs Mithrilrohre, ein genaues Zielfernrohr und zwei hochentwickelte Zielattrappen.\n\nSobald Ihr diese Gegenstände bei einem Ingenieurskunstlehrer in einer beliebigen Hauptstadt abgebt, seid Ihr offiziell ein Gnomeningenieur und erhaltet Zugriff auf alle Baupläne!", sourceObjective = "Bringt 6 Mithrilrohre, ein genaues Zielfernrohr und zwei hochentwickelte Zielattrappen zu einem Ingenieurskunstlehrer in einer beliebigen Hauptstadt.", progress = "Sobald Ihr mir Eure gefertigten Ingenieurskunstgegenstände zur Bewertung unterbreitet habt, könnt Ihr ein zertifizierter Gnomeningenieur werden. Dann erhaltet Ihr uneingeschränkten Zugriff auf alle Baupläne der Gnomeningenieure.", completion = "Am heutigen Tag wird aus Euch ein echter Ingenieur, {name}. Macht Euch keine Gedanken mehr über diese schmutzigen Bomben und Sprengstoffe, denn Ihr werdet bald über Euch selbst hinauswachsen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29481] = { id = 29481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Elixiere", description = "Bei Elixieren geht es nur um Stärke! Ich kann Euch zum Meister der Elixiere ausbilden, wenn Ihr das wünscht.\n\nDas ist nichts für jeden und ich verlange einen Beweis für Eure Ernsthaftigkeit, bevor wir fortfahren können. Mit einigen Fläschchen könnt Ihr mir Eure Entschlossenheit zeigen.\n\nVergesst nicht, {name}, dass Ihr nur EINE Spezialisierung erlernen könnt. Wenn Ihr die Elixierbeherrschung abgeschlossen habt, werden Euch Tränke und Transmutation nicht mehr angeboten.", sourceObjective = "Bringt eine Reihe verschiedener Fläschchen zu einem Alchemielehrer.", progress = "Habt Ihr die Fläschchen?", completion = "Sehr gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[29482] = { id = 29482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Transmutation", description = "Eisen zu Gold, Wasser zu Feuer... ich kann Euch helfen, wenn Ihr ein Meister der Transmutation werden wollt.\n\nDie Ausbildung ist sehr teuer, also müsst Ihr mir einige der besten transmutierten Materialien der Welt bringen.\n\nVergesst nicht, {name}, dass Ihr nur EINE Spezialisierung erlernen könnt. Wenn Ihr die Transmutationsbeherrschung abgeschlossen habt, werden Euch Tränke und Elixiere nicht länger angeboten.", sourceObjective = "Bringt die verlangten Materialien zu einem Alchemielehrer in einer beliebigen Hauptstadt.", progress = "Habt Ihr die Materialien?", completion = "Sehr gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[29506] = { id = 29506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine prickelnde Mischung", description = "Als <Alchemist/Alchemistin> habt Ihr sicherlich schon zahlreiche Tränke gebraut. Würdet Ihr mir vielleicht bei etwas weniger Gehaltvollem helfen?\n\nIch wollte immer schon eine fruchtige Variante unserer beliebten Prickelgetränke kreieren. Wenn Ihr Euch daran versuchen wollt, würde ich Euch das Basisgetränk verkaufen. Anschließend mischt Ihr es mit etwas Mondbeerensaft.\n\nEin Gastwirt im Wald von Elwynn oder in Mulgore wird Euch genügend Saft für Eure Kreation verkaufen können.", sourceObjective = "Mischt mit Hilfe des Cocktail-Shakers aus Mondbeerensaft und prickelndem Marktgetränk 5 Krüge Mondbeerenfizz.", progress = "Was macht der Mondbeerenfizz?", completion = "Eure Kreation sieht vielversprechend aus. Mit ein wenig Glück werden wir bald ein neues Lieblingsgetränk haben!\n\nIch danke Euch für Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[29507] = { id = 29507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spaß für die Kleinen", description = "Kinder fragen so oft, was ein Archäologe tut und wie Archäologie funktioniert, dass ich eine kleine Demonstration für sie vorbereitet habe.\n\nIch vergrabe Artefakte und Fossilien im Sandkasten hinter dem Zelt. Die Kinder können sie ausgraben und so ihre eigenen Entdeckungen machen, lernen, wie man Knochen zusammensetzt und herausfinden, was ihnen die Archäologie über Geschichte beibringen kann.\n\nWürdet Ihr mir einige Fossilien für mein Projekt spenden, solltet Ihr welche übrig haben?", sourceObjective = "Bringt 15 mit Archäologie aufgespürte Fossilienfragmente zu Professor Thaddeus Paleo beim Dunkelmond-Jahrmarkt.", progress = "Wie sieht es aus? Wollt Ihr ein paar Fossilienfragmente spenden?", completion = "Großartig! Die Kinder werden sich sehr freuen, wenn sie diese Teile \"entdecken\".", sourceObjectiveStatus = "unverified-source-field" }
quests[29508] = { id = 29508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baby braucht zwei Paar Schuhe", description = "Habt Ihr meine Stute Baby da hinten neben den Wagen gesehen? Sie zieht den Karren mit allen Tieren unseres Kuriositätenkabinetts.\n\nSie arbeitet hart und braucht mehr Hufeisen, als Ihr Euch vorstellen könnt. Es ist wieder einmal Zeit für neue. Die Rohmaterialien habe ich bereits gekauft.\n\nIhr müsst sie nur auf einem Amboss bearbeiten und Baby anlegen. Geht schnell und ist mir ein paar Lose wert, also was meint Ihr?", sourceObjective = "Stellt aus den Eisenbeständen 4 Hufeisen her und legt sie Baby auf dem Dunkelmond-Jahrmarkt an.", progress = "Wie geht's dem alten Mädchen?", completion = "Danke für Eure Hilfe, {name}! Hier ist die versprochene Bezahlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[29509] = { id = 29509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie der Frosch knusprig wird", description = "Die Knusperfrösche des Dunkelmond-Jahrmarkts sind in ganz Azeroth berühmt!\n\nWir haben gerade frische Frösche bekommen. Warum helft Ihr uns nicht bei der Zubereitung und tut gleichzeitig etwas für Eure Kochkunst?\n\nDas Mehl, in dem Ihr die Frösche wälzen müsst, bekommt Ihr bei jedem Handwerkswarenhändler im Wald von Elwynn oder in Mulgore.", sourceObjective = "Bereitet 5 Knusperfrösche zu, indem Ihr Eure fetten Frösche in herkömmlichem Mehl wälzt und in dem Kessel hinter Stampf Donnerhorn bratet.", progress = "Rieche ich etwa frische Knusperfrösche?", completion = "Die sind auf den Punkt gebraten, {name}. Sehr gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[29510] = { id = 29510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auch Abfall kann nützlich sein", description = "Die Leute kommen nicht nur zum Spaß auf den Jahrmarkt, {name}. Die meisten wollen auch etwas mit nach Hause nehmen, deshalb helfe ich bei der Herstellung der magischen Schmuckstücke, die Besucher mit ihren Gewinnlosen kaufen können.\n\nDafür benötige ich ständig Wahrsagerstaub. Seht Euch auf dem Platz um, da gibt es jede Menge abgelegter Waffen. Diese Gegenstände kann jemand wie Ihr, der die Kunst des Verzauberns beherrscht, in Staub verwandeln. Würdet Ihr mir helfen?", sourceObjective = "Sammelt 6 Wahrsagerstaub, indem Ihr die abgelegten Waffen, die auf dem Platz des Dunkelmond-Jahrmarkts liegen, entzaubert.", progress = "Habt Ihr etwas Wahrsagerstaub bekommen?", completion = "Das hilft mir schon mal weiter. Wenn Ihr noch einmal helfen wollt, besucht einfach den alten Sayge, wenn der Dunkelmond-Jahrmarkt in der Stadt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[29511] = { id = 29511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Panzerreparatur", description = "Die Dunkelmonddampfpanzer gehören zu unseren beliebtesten Attraktionen. Unsere Besucher testen ihr Können stundenlang, aber bei all dem Spaß werden die Panzer stark beansprucht.\n\nIhr scheint zu wissen, wie man mit einem Schraubenschlüssel umgeht. Würdet Ihr mir bei der Reparatur der beschädigten Panzer helfen? Ich würde Euch für Euren Zeitaufwand entschädigen.", sourceObjective = "Repariert 5 beschädigte Dampfpanzer auf dem Gelände des Dunkelmond-Jahrmarkts.", completion = "Sehr gute Arbeit. Die Panzer laufen wieder. Hier sind die versprochenen Lose.", sourceObjectiveStatus = "unverified-source-field" }
quests[29512] = { id = 29512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kratzer, Beulen, blaue Flecke", description = "Die Arbeit auf dem Dunkelmond-Jahrmarkt ist gefährlich, {name}. Unsere Arbeiter verletzen sich oft beim Aufbau, Abbau und Transport der Attraktionen.\n\nEinige der verletzten Arbeiter findet Ihr in der Nähe der Wagen. Andere wollen sich im Heilzelt behandeln lassen. Warum nehmt Ihr nicht diese Bandagen und seht, ob Ihr den verletzten Arbeitern helfen könnt?", sourceObjective = "Nehmt die Bandagen des Dunkelmond-Jahrmarkts und heilt damit 4 verletzte Schausteller.", progress = "Habt Ihr Euch um die verletzten Arbeiter gekümmert?", completion = "Ich danke Euch für Eure Hilfe, {name}. Der Jahrmarkt kann nur weiterbestehen, wenn wir alle zusammenhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29513] = { id = 29513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leckerer Fisch im Schlafrock", description = "Wir haben gerade ein neues Gericht in unsere Speisekarte aufgenommen, den Fisch im Schlafrock. Es ist so beliebt, dass wir die Nachfrage kaum erfüllen können!\n\nIhr seht aus, als wüsstet Ihr, wie man mit einer Angel umgeht, {race}. Würdet Ihr mir bei der Aufstockung meiner Vorräte helfen?\n\nWir wollen doch all die Jahrmarktsbesucher, die etwas Neues ausprobieren wollen, nicht enttäuschen, oder?", sourceObjective = "Fangt 5 große Meeresheringe im Ozean rund um die Dunkelmond-Insel.", progress = "Habt Ihr die Fische?", completion = "Genau die richtigen! Hier sind wie versprochen Eure Lose.", sourceObjectiveStatus = "unverified-source-field" }
quests[29514] = { id = 29514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilkräuter", description = "Die kleinen purpurnen Blumen, die überall auf dem Platz wild wachsen, sind mehr als nur hübsch.\n\nMit ihnen kann man Wunden behandeln und Essen würzen.\n\nIhr scheint ein Talent zum Kräutersammeln zu besitzen. Würdet Ihr mir dabei helfen, meinen Vorrat an Dunkelblüten aufzustocken?", sourceObjective = "Sammelt 6 Dunkelblüten auf dem Lagerplatz des Dunkelmond-Jahrmarkts.", progress = "Wie geht das Kräutersammeln voran?", completion = "Danke, {name}. Sobald der Dunkelmond-Jahrmarkt wieder in der Stadt ist, würde ich gern noch einmal auf Eure Hilfe zurückgreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29515] = { id = 29515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Blick in die Zukunft", description = "Die Beliebtheit des Dunkelmond-Jahrmarkts nimmt zu. Immer mehr Leute suchen mich auf, um einen Blick in ihre Zukunft zu werfen.\n\nHäufig bitten sie um Wissen, das besser im Nebel der Zeit verborgen bleiben sollte, aber solche Ratschläge stehen mir nicht zu.\n\nMein Vorrat an geschriebenen Horoskopen neigt sich dem Ende zu und Ihr scheint eine sichere Hand zu haben. Stellt Tinte aus diesen Kräutern her und schreibt einige Horoskope für mich. Das Pergament, das Ihr dafür braucht, könnt Ihr bei jedem Handwerkswarenhändler im Wald von Elwynn oder in Mulgore erwerben.", sourceObjective = "Stellt aus dem Bund exotischer Kräuterprophetische Tinte her. Verbindet die Tinte mit leichtem Pergament, um Sayges Horoskope zu schreiben.", progress = "Habt Ihr die Horoskope geschrieben?", completion = "Die sehen genau wie meine aus. Ihr habt ein gutes Gespür für Details. Ich danke Euch für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29516] = { id = 29516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jahrmarkt der Eitelkeiten", description = "Die Künstler und Tiere des Dunkelmond-Jahrmarkts benötigen mehr Schmuck, als ich mir je hätte erträumen lassen. Zum Glück bestehen die Edelsteine nur aus geschliffenem Glas. Aber auch die muss jemand herstellen.\n\nSeid Ihr geübt in Juwelierskunst und würdet uns helfen, einige glitzernde Glasedelsteine für unsere Künstler herzustellen?\n\nManchmal kann man die erstaunlichsten Scherben auf dem Platz finden. Wenn die von jemandem mit einem Händchen für Juwelierskunst bearbeitet werden, entstehen daraus wunderschöne Edelsteine.", sourceObjective = "Sucht nach Glasscherben auf dem Platz des Dunkelmond-Jahrmarkts und schleift daraus 5 funkelnde \"Edelsteine\".", progress = "Ist es Euch gelungen, Ersatzedelsteine für den Schmuck unserer Künstler zu schleifen?", completion = "Sehr gute Arbeit, {name}. Ihr seid wirklich talentiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[29517] = { id = 29517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begehrte Preise", description = "Die Spiele werden immer beliebter, was bedeutet, dass wir mehr Preise ausgeben als je zuvor.\n\nWir brauchen dringend neue Preise. Wenn Ihr geübt in der Lederverarbeitung seid, würde ich Euch gern ein Set geben. Ihr werdet einige Teile bei einem Handwerkswarenhändler im Wald von Elwynn oder in Mulgore erwerben müssen, aber sie sind nicht teuer.\n\nWollt Ihr mir helfen?", sourceObjective = "Stellt mit Hilfe des Handwerkersets des Dunkelmond-Jahrmarkts 5 Gewinne des Dunkelmond-Jahrmarkts her. Dazu benötigt Ihr groben Faden, glänzende Schmuckstücke und blauen Farbstoff.", progress = "Habt Ihr die Preise hergestellt?", completion = "Sehr gute Arbeit! Die Preise sehen genauso aus wie die anderen. Ich danke Euch für Eure Hilfe.\n\nWenn Ihr noch einmal helfen wollt, dann sucht mich auf, wenn der Dunkelmond-Jahrmarkt das nächste Mal in der Stadt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[29518] = { id = 29518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederbewaffnung, Wiederverwendung, Wiederverwertung", description = "Die Jahrmarktsbesucher lieben unsere Dampfpanzer! Wenn der Dunkelmond-Jahrmarkt schließt, liegt all der Panzerschrott auf dem Platz herum.\n\nWäre doch schade, wenn das gute Metall einfach im Dreck verrotten würde.\n\nWäret Ihr so nett, mir einige der größeren Stücke zu bringen, damit ich die kaputten Panzerteile damit reparieren kann? Das ist weitaus billiger als jedes Mal neues Metall zu kaufen. Was meint Ihr?", sourceObjective = "Beschafft 6 Stücke Panzerschrott vom Lagerplatz des Dunkelmond-Jahrmarkts.", progress = "Habt Ihr Schrott gefunden? Der Platz ist voll davon.", completion = "Das ist eine Menge Schrott. Ich danke Euch für Eure Hilfe. Damit werde ich viele Panzer reparieren können.\n\nHier, nehmt dies als kleine Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[29519] = { id = 29519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerbt meine Häute", description = "Auf dem Dunkelmond-Jahrmarkt wird ständig Leder für Zelte, Stiefel und alles, was Ihr Euch vorstellen könnt, benötigt. Ich habe einige Kreaturen gefangen und ihre Häute aufgespannt.\n\nIhr scheint Euch mit Häuten auszukennen. Ich würde Euch belohnen, wenn Ihr mir beim Abschaben der neuen Häute helfen könntet.", sourceObjective = "Schabt 4 aufgespannte Häute auf dem Lagerplatz des Dunkelmond-Jahrmarkts ab.", progress = "Die Arbeit auf dem Dunkelmond-Jahrmarkt hört nie auf.", completion = "Ich danke Euch für Eure Hilfe, {name}. Ich werde Euch in guter Erinnerung behalten.\n\nUnd wenn Ihr möchtet, könnt Ihr mir gern wieder helfen, wenn der Dunkelmond-Jahrmarkt das nächste Mal in der Stadt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[29520] = { id = 29520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Banner, überall Banner!", description = "Ist es nicht wundervoll, dass überall Banner des Dunkelmond-Jahrmarkts wehen? Das genieße ich am meisten beim Aufbau, aber viele sind mittlerweile alt und zerschlissen und müssten ersetzt werden.\n\nNehmt Nadel und Faden, wenn Ihr damit umgehen könnt, und stellt ein Banner aus diesem Set her. Steckt es dann in einige lose Steine auf dem Lagerplatz des Jahrmarkts.\n\nEs fehlen noch einige Teile, doch die solltet Ihr bei jedem Handwerkswarenhändler im Wald von Elwynn oder in Mulgore erwerben können.", sourceObjective = "Stellt mit einem groben Faden sowie rotem und blauem Farbstoff zusammen mit dem Bannersets des Dunkelmond-Jahrmarkts ein Banner des Dunkelmond-Jahrmarkts her. Steckt es in einen Haufen loser Steine auf dem Lagerplatz des Jahrmarkts.", completion = "Danke für Eure Hilfe. Ihr seid recht begabt mit Nadel und Faden. Wenn der Dunkelmond-Jahrmarkt das nächste Mal in der Stadt ist, könnt Ihr uns gern wieder helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29521] = { id = 29521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Singenden Teiche", description = "Es ist von höchster Wichtigkeit, dass wir die drei verbleibenden Geister ebenfalls unversehrt zurückbringen. Ich bin zu alt, um dies selbst zu bewerkstelligen, und Aysa und Ji sind trotz ihrer Stärken zu engstirnig, was ihre Ideale betrifft.\n\nIhr besitzt alle Qualitäten <eines Helden/einer Heldin> und zusätzlich eine Ausgewogenheit, über die sie nicht verfügen. Ihr seid <derjenige, der/diejenige> die; diese Aufgabe erfüllen muss.\n\nShu, der Geist des Wassers, befindet sich irgendwo in den Singenden Teichen östlich von hier. Sucht dort Aysa auf und arbeitet mit ihr zusammen, um ihn zu finden. Wir alle verlassen uns auf Euch.", sourceObjective = "Sprecht mit Aysa Wolkensänger bei den Singenden Teichen.", completion = "Es ist schön, Euch wiederzusehen, {name}.\n\nDas hier ist der Teich des Stinktiers, wie Ihr sicherlich bemerkt habt.\n\nSeit der Entstehung von Shen-zin Su sind über die Jahre hinweg Tiere in einigen dieser magischen Teiche verendet. Durch ihren Tod wurden die Gewässer von ihrem Geist durchdrungen und jeder, der das Wasser berührt, wird ihre Gestalt annehmen.\n\nEs gibt einige verfluchte Teiche hier, von denen manche gefährlicher sind als andere.", sourceObjectiveStatus = "unverified-source-field" }
quests[29522] = { id = 29522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ji, Anhänger der Huojin", description = "Ein weiterer meiner talentiertesten Schüler wartet in Wu-Song im Nordwesten auf Euch. Ihr werdet feststellen, dass er in vielerlei Hinsicht anders denkt und handelt als Aysa, aber durch ihre Unterschiede bringen sie sich gegenseitig ins Gleichgewicht.\n\nJi Feuerpfote wird Euch beim Sammeln der Opfergaben für den Geist des Feuers anleiten. Vertraut auf seine Weisheit.", sourceObjective = "Sprecht mit Ji Feuerpfote in Wu-Song.", completion = "Seid gegrüßt! Ihr seht selbstsicher und zuversichtlich aus… Das gefällt mir!\n\nIch habe einige recht beeindruckende Gerüchte über Euch gehört. Wenn Ihr nur halb so fähig seid, wie man sagt… Ich habe das Gefühl, dass wir gute Freunde sein werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[29523] = { id = 29523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flammen schüren", description = "Das Eigenartige am Wind ist, dass es durchaus schwer sein kann, ihn in die Finger zu bekommen.\n\nMeiner Meinung nach ist die beste Methode, eine Art lebendigen Wind zu finden. Wenn er mir eine verpassen kann, dann kann ich auch ihm eine verpassen und er wird mir nicht einfach davonwehen.\n\nMacht Euch auf den Weg zum Schrein der Sommerbrise und beschwört mit diesem Windstein einen solchen lebendigen Wind. Bezwingt ihn, entnehmt ihm eine flatternde Brise und kehrt zu mir zurück, damit wir entscheiden können, wie der nächste Schritt aussehen wird.", sourceObjective = "Beschafft eine flatternde Brise.", progress = "Wenn sich eine Gelegenheit ergibt, ist es unsere Pflicht, sie zu ergreifen. Eine Entscheidung im Nachhinein zu bezweifeln ist genauso viel wert, wie gleich aufzugeben.", completion = "Ihr wisst, was es heißt, eine Gelegenheit beim Schopfe zu packen. Ich denke, dass wir beide aus demselben Holz geschnitzt sind, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29524] = { id = 29524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lektion des unterdrückten Stolzes", description = "Es ist etwas ganz anderes, einem lebenden Gegner anstatt dieser Übungsziele im Hof gegenüberzustehen. Lebende Gegner schlagen zurück. Eine sehr reelle Angst vor dem Versagen, und manchmal sogar dem Tod, kann Euch überkommen.\n\nIhr müsst den Mut aufbringen, diese Ängste zu überwinden.\n\nFordert die anderen Schüler innerhalb des Tempels oder auf den Stufen davor heraus und bezwingt sie.", sourceObjective = "Bezwingt 6 Huojin- oder Tushui-Schüler.", completion = "Faszinierend, mein junger Schüler.\n\nDie meisten der anderen Schüler haben schon einige Zeit hier verbracht, aber Ihr seid schon jetzt in der Lage, Euch mit ihnen zu messen.\n\nDas spricht für Euch, aber es gibt noch weitere Lektionen, die ich Euch gerne lernen sehen würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[29527] = { id = 29527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg im Bollwerk", description = "Wachhabender Gargolmar und Vazruden der Herold haben das Kommando über die Verteidigung des Bollwerks.\n\nWenn Ihr sie ausschaltet, werden die Soldaten in Panik geraten.\n\nTötet sie und bringt mir einen Beweis für Eure Tat, damit die Invasion beginnen kann!", sourceObjective = "Tötet Wachhabenden Gargolmar, Vazruden den Herold und Vazrudens Drachen Nazan. Bringt Gargolmars Hand und Nazans Kopf zu Steingardist Stok'ton.", progress = "Diese Mission hängt von Eurem Erfolg ab, {name}.", completion = "Ohne ihre Anführer sollten die Truppen in Panik geraten.\n\nAber es geht hier um mehr als die Beseitigung einiger Wachen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29528] = { id = 29528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg im Bollwerk", description = "Die Verteidigung der Höllenfeuerzitadelle hängt in erster Linie vom Bollwerk ab, das als eine Art Frühwarnsystem dient.\n\nBeseitigt Wachhabenden Gargolmar und Vazruden den Herold. Ohne sie wird die Eroberung des Bollwerks ein Kinderspiel sein.", sourceObjective = "Tötet Wachhabenden Gargolmar, Vazruden den Herold und Vazrudens Drachen Nazan. Bringt Gargolmars Hand und Nazans Kopf zu Vorhutsspäher Chadwick.", progress = "Wart Ihr erfolgreich? Von dieser Mission hängt sehr viel ab, {name}.", completion = "Ich wusste, dass ich auf Euch zählen kann!\n\nIhre Streitkräfte sind nun führerlos. Die Invasion kann beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29529] = { id = 29529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonen in der Zitadelle", description = "Einer unserer Späher berichtet, er habe irgendwo im Bollwerk einen Agenten der Brennenden Legion gesehen. Wenn das stimmt, laufen wir Gefahr, dass die Ehrenfeste von zwei Seiten angegriffen wird!\n\nWenn Ihr diesen Teufel findet, dann bringt ihn um.", sourceObjective = "Tötet Omor den Narbenlosen und bringt seinen Huf zu Vorhutsspäher Chadwick.", progress = "Habt Ihr dort drinnen Dämonen entdeckt?", completion = "Dann ist es also wahr. Die Höllenorcs und die Brennende Legion arbeiten auf irgendeine Weise zusammen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29530] = { id = 29530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonen in der Zitadelle", description = "Einer unserer Späher hat unangenehme Neuigkeiten überbracht. Wir haben einen mächtigen Agenten der Brennenden Legion im Bollwerk entdeckt!\n\nBringt diesen Dämon um, bevor er seinen Vorgesetzten von unseren Plänen berichten kann.", sourceObjective = "Tötet Omor den Narbenlosen und bringt seinen Huf zu Steingardist Stok'ton.", progress = "Konntet Ihr die üble Kreatur beseitigen?", completion = "Gut gemacht. Wir brauchen die Zeit, die Ihr uns erkauft habt, um der Verbindung zwischen Höllenorcs und brennender Legion nachzugehen. Eure Taten haben vielleicht Hunderten das Leben gerettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29531] = { id = 29531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Stuff" }
quests[29535] = { id = 29535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst sie bluten!", description = "Der Schöpfer erzeugt neue Höllenorcs, indem er ihnen Dämonenblut injiziert.\n\nMeine Vorgesetzten glauben, dass sich der Prozess rückgängig machen lässt, aber um das auszuprobieren, benötigen wir Proben ihres Blutes und die Injektionsspritze des Schöpfers.", sourceObjective = "Beschafft 10 Phiolen mit Höllenorcblut und eine Teufelsinjektionsspritze für Caza'rez.", progress = "Ihr seid zurück und sogar lebendig! Gut gemacht. Besser als alle anderen bis jetzt.", completion = "Diese Phiolen könnten das Ende der Höllenorcs einläuten. Ich hoffe, dass Ihr versteht, wie wichtig das für unseren Feldzug wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[29536] = { id = 29536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz des Zorns", description = "Wir wissen, dass die Höllenorcs ihren Fokus erhöhen, indem sie Orcs Dämonenblut injizieren.\n\nBegebt Euch tief in diese unheiligen Hallen und findet heraus, was dort geschieht. Wir können es erst riskieren, eine Armee hineinzuschicken, wenn wir genau wissen, was uns erwartet.", sourceObjective = "Untersucht den Blutkessel vollständig und meldet Euch wieder bei Caza'rez.", completion = "<Ihr erzählt Caza'rez alles, was Ihr im Blutkessel gesehen habt.>\n\nWenn sie das den braunen Orcs der Mag'har antun können, dann sind auch wir in Gefahr! Wir müssen vorsichtig sein, sonst werden alle in Thrallmar zu hirnlosen Bestien.", sourceObjectiveStatus = "unverified-source-field" }
quests[29537] = { id = 29537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorsicht, Lücke!", description = "Im ganzen Blutkessel gibt es nur ein Gebiet, das unsere Seher trotz aller Mühen nicht erreichen können.\n\nDiese \"Lücke\", wie sie es nennen, ist recht groß. Dort wird bestimmt Magtheridon gefangen gehalten.\n\nIhr müsst die Ursache dieser Störungen finden und vernichten.", sourceObjective = "Tötet Keli'dan den Zerstörer und kehrt zu Caza'rez zurück.", completion = "Die Störungen haben nachgelassen, aber wir können das Gebiet immer noch nicht sehen. Wir werden der Sache weiter nachgehen. Ich danke Euch für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[29538] = { id = 29538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst sie bluten!", description = "Mit Dämonenblut und einer speziellen Spritze verwandelt der Schöpfer braune und grüne Orcs in rote. Wir würden uns das Blut gern ansehen und damit herumspielen, bis es Orcs aller Farben in harmlose, friedliche Ochsen verwandelt.\n\nBringt mir einige Proben ihres Blutes, damit wir anfangen können. Und vergesst die Spritze nicht!", sourceObjective = "Beschafft 10 Phiolen mit Höllenorcblut und eine Teufelsinjektionsspritze für Gunny.", progress = "Habt Ihr das Blut, Prinzessin? Wir haben Euch bestimmt nicht darum gebeten, weil es unwichtig ist.", completion = "Verdammt beeindruckend! Damit steigt Ihr auf Platz acht meiner Lieblingspersonen in den qualmenden Ruinen dieses bemitleidenswerten Planeten auf!", sourceObjectiveStatus = "unverified-source-field" }
quests[29539] = { id = 29539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz des Zorns", description = "Hat sich gezeigt, dass die Eierköpfe in der Ehrenfeste nicht viel von diesem Ort hier sehen können. Lügende, faule Magier sind das, nichts weiter.\n\nWie dem auch sei, wir wissen nicht genau, was hier vorgeht. Also werdet Ihr das herausfinden!", sourceObjective = "Untersucht den Blutkessel vollständig und meldet Euch wieder bei Gunny.", completion = "<Ihr erzählt Gunny alles, was Ihr im Blutkessel gesehen habt.>\n\nIhr habt doch auch Beute für den alten Gunny, oder?\n\nNein, Ihr habt natürlich recht. Ich schulde Euch eine Belohnung für Eure harte Arbeit, auch wenn Ihr ohne mich überhaupt nicht hineingegangen wäret.", sourceObjectiveStatus = "unverified-source-field" }
quests[29540] = { id = 29540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zerstörer", description = "Die verstecken hier irgendwo so einen großen, alten Dämon, hab ich gehört. Und da gibt's auch einen Orc, der darauf achten soll, dass er bleibt, wo er hingehört.\n\nEin Orc ist ein Orc, und Orcs werden umgebracht, richtig? Ist egal, was er tut oder getan hat, einer weniger schadet nie.", sourceObjective = "Tötet Keli'dan den Zerstörer und kehrt zu Gunny zurück.", completion = "Wirklich? Ihr wollt eine Belohnung, weil Ihr einen Orc umgebracht habt? So wie in Ruhm und Reichtum und edle Reittiere?\n\nZu meiner Zeit war es Belohnung genug, einen Orc töten zu DÜRFEN!", sourceObjectiveStatus = "unverified-source-field" }
quests[29541] = { id = 29541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take Care of It" }
quests[29542] = { id = 29542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eroberung der Zitadelle", description = "Die Legion steht auf der einen, die Höllenorcs auf der anderen Seite. Sie werden Thrallmar überrennen, wenn wir nichts unternehmen.\n\nMacht Euch auf den Weg nach Westen zum Höllenfeuerbollwerk und sprecht mit Steingardist Stok'ton. Die Geheimmission, die er leitet, wird der Horde den Weg in die Zitadelle ebnen.", sourceObjective = "Sprecht mit Steingardist Stok'ton im Höllenfeuerbollwerk.", completion = "Schädelbrecher ist nicht gerade freundlich, aber er weiß, was er tut. Und für Euch gibt es auch genug Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[29543] = { id = 29543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eroberung der Zitadelle", description = "Die Legion steht auf der einen, die Höllenorcs auf der anderen Seite. Sie werden die Ehrenfeste in Kürze überrennen, wenn wir nichts unternehmen.\n\nMacht Euch auf nach Westen zum Höllenfeuerbollwerk und sprecht dort mit Vorhutsspäher Chadwick. Die Mission, die er leitet, wird der Allianz den Weg in die Zitadelle ebnen.", sourceObjective = "Sprecht mit Vorhutsspäher Chadwick im Höllenfeuerbollwerk.", completion = "Altumus ist wirklich ein Juwel. Aber wir werden hier nur lebend herauskommen, wenn wir im Bollwerk siegreich sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[29547] = { id = 29547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Befehl des Königs", description = "Seid gegrüßt, {class}.\n\nIch wurde beauftragt, eine Gruppe für eine Mission von höchster Wichtigkeit zusammenzustellen.\n\nBitte eilt sofort in die Burg Sturmwind für eine Besprechung mit König Varian Wrynn. Ich werde im Kriegsraum des Königs auf Euch warten.", sourceObjective = "Sucht Großadmiralin Jes-Tereth im Kriegsraum von Burg Sturmwind in Sturmwind auf.", completion = "Unsere Rolle ist äußerst wichtig. Admiral Taylor und sein Flaggschiff sind verschwunden. Was noch wichtiger ist: Der junge Prinz war bei ihm und unser primäres Ziel besteht darin, ihn sicher zurück nach Hause zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29548] = { id = 29548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mission", description = "Nun denn, Ihr habt den König gehört. Admiral Taylors letzte Übertragung kam von irgendwo im südlichen Meer.\n\nWir werden umgehend mit der Luftaufklärung beginnen. Der Prinz - der Weiße Bauer - ist dabei die oberste Priorität.\n\nDie Himmelsfeuer ist vollgetankt, beladen und zum Aufbruch bereit. Sie wartet mit ihrer Mannschaft am Himmel nördlich des Hafens.\n\nTrefft Eure letzten Vorbereitungen und meldet Euch dann bei Himmelsadmiralin Rogers auf dem Deck. Wir werden ohne weitere Verzögerungen aufbrechen.", sourceObjective = "Meldet Euch bei Admiralin Rogers auf der Himmelsfeuer.", progress = "Ah, ein Veteran aus den Kataklysmusfeldzügen! Sehr gut - ich kann fähige Hände hier wirklich gut gebrauchen.", completion = "Das da unten ist eine komplette Basis der Horde! Wo waren unsere Aufklärer!?\n\nNun denn, {class}, es wird Zeit herauszufinden, wozu dieses aufgerüstete Luftschiff in der Lage ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[29552] = { id = 29552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In kritischem Zustand", description = "Die erste Schlacht haben wir zwar gewonnen, es gibt aber noch eine äußerst wichtige Aufgabe.\n\nIn der ersten Luftschlacht wurden Dutzende Himmelsfeuerpiloten abgeschossen.\n\nOhne medizinische Hilfe wird sich ihr Zustand im Lauf der Zeit verschlechtern, bis sie schließlich sterben. Wir sind ihre einzige Überlebenshoffnung.\n\nBegebt Euch in den Obstgarten und belebt alle Piloten wieder, die Ihr findet.\n\nWir werden niemanden zurücklassen.", sourceObjective = "Belebt 6 verwundete Piloten im Hain von Pel'zin wieder. Ihr könnt auch Heilzauber oder Bandagen verwenden, um sie wiederzubeleben.", completion = "Gut gemacht, {name}. Dank Eurer Anstrengungen werden diese Soldaten einen Tag länger leben und kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29553] = { id = 29553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Admiral", description = "Also gut. Die Hinweise, die Ihr gefunden habt, deuten darauf hin, dass es Anduins Schiff mit Admiral Taylor als Kapitän war. \n\nUnd laut Admiral Taylors letztem Eintrag wollte er die Ho-zen abwehren und das Schiff nach dem Schiffbruch schützen.\n\nDie Einheimischen behaupten, die Ho-zen würden manchmal Gefangene nehmen, und ich habe Taylors Leichnam zwischen den Wrackteilen nicht gefunden. Taylor ist also wahrscheinlich im Lager der Ho-zen im Nordosten.\n\nBrecht auf, wir haben keine Zeit zu verlieren!", sourceObjective = "Findet Admiral Taylor.", completion = "<Ihr habt ihn gefunden, aber der Admiral ist bewusstlos. Er scheint dem Tode näher als dem Leben.>", sourceObjectiveStatus = "unverified-source-field" }
quests[29555] = { id = 29555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weiße Bauer", description = "Also, Soldat. Ich habe eine entscheidende Mission für Euch.\n\nBegebt Euch zur Küste südlich von hier - in der Bucht dort werdet Ihr das Wrack eines Schiffs der Allianz finden. Ich möchte, dass Ihr es durchsucht und herausfindet, ob Anduin Passagier darauf war.\n\nBergt dann das Logbuch des Kapitäns und sucht darin nach Hinweisen darauf, wo wir ihn finden können.\n\nDa es sich um das Logbuch eines Militärschiffes handelt, wird es in Code verfasst sein. Bringt es anschließend zu Nick Codeknack. Er bewacht das Wrack am anderen Ende der Bucht.", sourceObjective = "Durchsucht das Wrack der Herold im Jadewald nach Hinweisen auf seine Ladung und bergt das verschlüsselte Logbuch des Kapitäns.", progress = "Nun?", completion = "Schön... zeigt her... der Code vom Zeitpunkt des Verschwindens des Schiffs...\n\n<Nick rechnet offenbar in seinem Kopf.>\n\nAha!", sourceObjectiveStatus = "unverified-source-field" }
quests[29556] = { id = 29556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ho-zen sind nicht Freund, sondern Feind", description = "Wir haben ein Wrack der Allianz im Süden geortet. Den Einheimischen dort zufolge wird es jedoch derzeit von einer Gruppe dieser \"Ho-zen\" genannten Geschöpfe geplündert.\n\nDass sie unsere Schiffswracks ausnehmen, beweist bereits, dass sie uns nicht freundlich gesinnt sind. Wir können nicht zulassen, dass sie in unseren Schiffen auf Beutezug gehen, unseren Nachschub stehlen und - schlimmer noch - womöglich Überlebende gefangen nehmen oder gar töten.\n\nAuf mit Euch, erledigt sie! Wenn Ihr damit fertig seid, meldet Euch bei Nick Codeknack, unserem SI:7-Agent in der Gegend.", sourceObjective = "Tötet 14 Ho-zen am Wrack der Herold.", completion = "Gute Arbeit. Solche Dreckskerle - uns zu treten, wenn wir am Boden liegen...\n\nDas wird sie lehren, nicht noch einmal ein Schiff der Allianz zu plündern!", sourceObjectiveStatus = "unverified-source-field" }
quests[29558] = { id = 29558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegspfad", description = "Ich merke, dass Ihr Euren Freund retten wollt. Ich kann Euch helfen, wenn Ihr mir ebenfalls helft.\n\nZunächst einmal ist es wohl offensichtlich, dass eine Flucht viel leichter zu bewerkstelligen sein wird, wenn hier weniger Schlingschwänze umherstreifen.\n\nTötet die Wachen der Ho-zen um uns herum und wir sind der Freiheit schon einen Schritt näher.", sourceObjective = "Tötet 12 Kronenhüpfer oder Schlammseher der Schlingschwänze.", progress = "Ihr kämpft gut, Fremder.", completion = "Ahahaha! Ihr seid tapfer.\n\nEine bewundernswerte Eigenschaft.", sourceObjectiveStatus = "unverified-source-field" }
quests[29559] = { id = 29559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere Brüder befreien", description = "Ihr mögt ein Außenstehender sein, doch wir haben in den Ho-zen einen gemeinsamen Feind.\n\nViele Mitglieder meines Stammes sind in Käfigen in der Nähe eingesperrt. Ich habe außerdem Eure... Allianzsoldaten gesehen.\n\nIch kann nicht fortgehen, ohne meine Brüder befreit zu haben - so, wie Ihr Eure Kameraden nicht zurücklassen könnt.\n\nDie Schlingschwänze sind im Besitz der Schlüssel zu diesen Käfigen. Findet die Schlüssel und befreit unsere Freunde.", sourceObjective = "Befreit 6 Jinyu- oder Allianzgefangene.", completion = "Ihr habt meine Brüder befreit? Gut.\n\nWir stehen in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[29560] = { id = 29560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Macht", description = "Die Schädel der Ho-zen sind begehrte Objekte in meinem Dorf.\n\nWir verwenden sie, um Riten zu zelebrieren. Je älter der Schädel, desto mächtiger ist seine Magie.\n\nZu unserem Glück sind die Ho-zen nachlässig, die schmutzigen Biester. Sie lassen die Schädel ihrer Verstorbenen überall zwischen ihren Hütten und Lagerfeuern herumliegen.\n\nSammelt diese Schädel für mich und ich werde Euch fürstlich belohnen.", sourceObjective = "Sammelt 8 uralte Ho-zen-Schädel.", progress = "Diese Schädel sind für meinen Stamm sehr wertvoll. Wie viele habt Ihr eingesammelt?", completion = "Es ist gut zu sehen, dass Ihr so einfallsreich seid, {name}. Diese Eigenschaft wird von meinem Volk bewundert.\n\nDiese wunderbaren Exemplare, die Ihr mir gebracht habt, werden mächtige Magie hervorbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29562] = { id = 29562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbruch aus dem Gefängnis", description = "Ohne Heilung wird Euer Freund Taylor sterben. Mein Dorf befindet sich im Osten von hier, mitten in dem großen See.\n\nIch werde Taylor selbst dorthin tragen, doch die Kämpfe in dieser Richtung sind höchst gefährlich.\n\nIch brauche Eure Hilfe, um mir einen Weg durch die Ho-zen zu bahnen, damit ich sicher zu meinem Dorf laufen kann.\n\nSchafft Ihr das?", sourceObjective = "Tötet 10 Entbeiner der Schlingschwänze.", completion = "Danke, {name}. Dank Euch haben wir es sicher hierher geschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[29563] = { id = 29563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschollen im Kampf", description = "Ihr müsst mir helfen! Wir wurden ausgesandt, um die verschiedenen Bereiche des Kessels zu erkunden, aber das war vor einiger Zeit und meine Freunde sind noch nicht zurückgekehrt.\n\nBitte findet heraus, ob ihnen etwas zugestoßen ist. Naturalist Biss und Jäter Gründaum sind in diese Richtung gegangen.", sourceObjective = "Findet heraus, was Naturalist Biss und Jäter Gründaum zugestoßen ist. Kehrt dann zu Behüterin Jhang zurück.", completion = "Der Verlust des Lebens... so schmerzhaft.\n\n<Behüterin Jhang seufzt.>\n\nDanke, {name}. Wenn wir alle wieder vereint sind, werden uns die Naga nichts anhaben können.", sourceObjectiveStatus = "unverified-source-field" }
quests[29564] = { id = 29564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der betrogene Bruder", description = "Anfangs gelang es meinem Dorf, den Angriffen der Naga auszuweichen. Wir hätten es bis nach Nagrand geschafft, wenn mein Bruder nicht gewesen wäre. Mit unseren Seelen erkaufte er sich seine Freiheit.\n\nNun arbeitet er hier als Sklavenaufseher und peitscht seine eigenen Brüder aus, bis ihre Rücken bluten. Dafür muss Mennu bezahlen, {race}.", sourceObjective = "Tötet Mennu den Verräter und kehrt zu Nahuud zurück.", completion = "Mennus Tod kann die Wunden meiner Familie und Freunde nicht heilen, aber wenigstens können sie den Rest ihres Lebens in Freiheit verbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29565] = { id = 29565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Pudels Kern", description = "Nahuud hat mir erklärt, zwei mächtige Wesen, Rokmar der Zerquetscher und Quagmirran, seien als erste von den Naga nach deren Ankunft versklavt worden. Sie haben bei der Unterwerfung vieler Völker in den Zangarmarschen geholfen.\n\nIch tue das sehr ungern, aber ich muss Euch bitten, sie zu töten.", sourceObjective = "Bringt die Klaue des Eindringlings und das Auge des Sklaventreibers zu Behüterin Jhang.", progress = "Habt Ihr sie getötet?", completion = "Ich bin froh, dass ihr Geist nun frei ist. Ich wünschte, das gleiche könnte man von den anderen ihrer Art sagen.\n\nEs gibt noch viel zu tun, vor allem in den anderen Teilen des Echsenkessels.", sourceObjectiveStatus = "unverified-source-field" }
quests[29566] = { id = 29566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorene Expedition", description = "Die Sümpfe sind wunderschön, findet Ihr nicht? Abgesehen natürlich von den Naga, die das Wasser abpumpen.\n\nIch habe eine kleine Expedition zum Echsenkessel geschickt. Sie sollte die Naga beobachten, aber bis jetzt ist niemand zurückgekehrt. Ich mache mir Sorgen um sie.\n\nWürdet Ihr Euch zu den Sklavenunterkünften unterhalb des Schlangensees begeben und nach Behüterin Jhang suchen?", sourceObjective = "Sprecht mit Behüterin Jhang in den Sklavenunterkünften.", completion = "Was macht Ihr denn hier unten? Ihr könnt doch sehen, dass es hier nicht gerade sicher ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[29567] = { id = 29567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet die Mutter", description = "Die Fungusgiganten greifen zwar heutzutage mein Volk an, aber die Marschenläufer haben bereits mehr Unschuldige auf dem Gewissen als alle anderen Kreaturen, die ich kenne. Sie sind seit Urzeiten unser Feind.\n\nIhre Brutmutter, die man auch Schattenmutter nennt, lebt in den Tiefen dieses Sumpfes. Wenn es Euch gelingen sollte, sie zu vernichten und mir ihr Gehirn als Beweis zu bringen, würde ich noch meinen Enkeln von Eurer ruhmreichen Tat erzählen.", sourceObjective = "Bringt das Gehirn der Schattenmutter zu T'shu.", progress = "Ihr seid zurück. Heißt das die Schattenmutter ist nicht mehr?", completion = "Die Schattenmutter ist tot! Normalerweise schwelge ich ja nicht in solchen Gemetzeln, aber der Schmerz, den die große Mutter und ihre Brut über Jahrhunderte meinem Volk zugefügt haben, ist unaussprechlich.\n\nIch bin Euch auf ewig dankbar, mutiger {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29568] = { id = 29568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein notwendiges Übel", description = "Hungarfenn und Quagmirran herrschten einst gemeinsam über die Fungusgiganten. Seit Quagmirrans Tod lastet diese Verantwortung allein auf Hungarfenns Ranken.\n\nWir müssen den Riesen töten, bevor er versklavt und als Waffe gegen uns eingesetzt werden kann.", sourceObjective = "Tötet Hungarfenn und kehrt zu Naturalist Biss zurück.", completion = "Ihr habt den Zangarmarschen an diesem Tag einen großen Gefallen erwiesen, {name}. Die Fungusgiganten sind zwar von Natur aus angriffslustig, aber sie sind ein wichtiger Teil des Ökosystems.", sourceObjectiveStatus = "unverified-source-field" }
quests[29570] = { id = 29570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rettung der Expedition", description = "Die restlichen Mitglieder meiner Expedition sind irgendwo hier drinnen. Wir brauchen das Wissen, das sie erlangt haben, und die Fähigkeiten, die sie besitzen, sonst werden wir die Naga niemals schlagen.\n\nSucht nach Erdbinder Rayge und Windrufer Klaue und stellt sicher, dass es ihnen gut geht.", sourceObjective = "Findet heraus, was mit Erdbinder Rayge und Windrufer Klaue geschehen ist. Kehrt dann zu Behüterin Jhang zurück.", progress = "Konntet Ihr die beiden finden? Geht es ihnen gut?", completion = "Bald werden wir wieder vereint sein, und das habe ich Euch zu verdanken!\n\nWir werden die Naga schneller besiegen, als Ihr denkt. Sie haben keine Chance!", sourceObjectiveStatus = "unverified-source-field" }
quests[29571] = { id = 29571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung der Wildnis", description = "Der Irdene Ring arbeitet oft eng mit dem Zirkel des Cenarius zusammen. So ist es auch dieses Mal.\n\nReist nach Norden zum Tiefensumpf und sprecht mit Behüterin Jhang. Sie leitet eine Expedition in den Echsenkessel, um die Naga aufzuhalten und die Zangarmarschen zu retten.", sourceObjective = "Sprecht mit Behüterin Jhang im Tiefensumpf.", completion = "Der Tiefensumpf steht kurz davor, zu einem Teil des Systems zu werden, das die Naga im Echsenkessel etabliert haben. Ihr müsst uns helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29573] = { id = 29573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherheit geht vor", description = "Es ist hier jetzt fast so sicher, dass meine Leute kommen und sich holen können, was rechtmäßig ihnen gehört. Die einzig große, noch verbleibende Gefahr stellt Shaffars Leibgarde dar. Von der wimmelt es hier.\n\nKümmert Euch um diese Streitkräfte, während ich wieder zu Kräften komme.", sourceObjective = "Tötet 10 astrale Grufträuber, 5 astrale Zauberer, 5 Nexuswandler und 5 astrale Zauberbinder. Kehrt danach zu Konstrukteur Morphalius zurück.", completion = "Wunderbar! Haramad wird sich über die guten Neuigkeiten freuen! Dieser Ort wird ihm wie ein reifer Apfel in die Hand fallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29574] = { id = 29574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rätselhafte Wesen", description = "Nahe des Eingangs dieser Hallen gibt es eine Kreatur, die Pandemonius genannt wird. Sie ist in der Lage, die Energien der Leere so zu verändern, dass sie sich daraus versorgen und stärken kann.\n\nWeiter hinten liegt Tavarok, ein Wesen, das die gleiche Energie in eine kristalline Struktur umwandelt, die stärker ist als alles, was ich je gesehen habe!\n\nIch brauche dringend Proben für weitere Untersuchungen.", sourceObjective = "Bringt Pandemonius' Essenz und Tavaroks Herz zu Mamdy dem Ologen.", progress = "Wenn Ihr nicht habt, wonach ich suche, verschwendet Ihr nur meine Zeit.", completion = "Diese Proben sind äußerst interessant. Sie werden mir sehr helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29575] = { id = 29575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Konkurrenz untergraben", description = "Dank der Barriere, die Nexusprinz Shaffar errichtet und der Truppen, die er aufgestellt hat, kann er diese Gruft in aller Seelenruhe ausplündern.\n\nNexusprinz Haramad ist darüber nicht gerade begeistert. Deshalb hat er einen sehr ansehnlichen Preis auf Shaffars Kopf ausgesetzt.", sourceObjective = "Bringt Shaffars Bandagen zu Konstrukteur Morphalius.", progress = "Hattet Ihr Euch für den Preis auf Shaffars Kopf interessiert?", completion = "Ich hätte nicht gedacht, dass ein {race} einen Nexusprinzen besiegen kann. Ihr habt mich überrascht und Euch diese schöne Belohnung mehr als verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[29576] = { id = 29576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hauch von Sorge", description = "Mein Augenlicht ist schon lange verblasst, doch wenn der Wind richtig steht, kann ich immer noch die Blüten des Obstgartens Nektarhauch riechen, als ob ich sie in meinen Händen halte.\n\nHeute ist ihr Duft allerdings mit Rauch vermengt. Wenn Ihr Euch dazu in der Lage seht, schaut doch bitte im Obstgarten nach dem Rechten. Vielleicht spielt mir meine alte Nase einfach einen Streich.\n\nIhr findet den Obstgarten im Südwesten, jenseits der Statue der Jadeschlange.", sourceObjective = "Sprecht mit Shao dem Widerspenstigen im Obstgarten Nektarhauch.", completion = "Wenn Ihr hergekommen seid, um Euch mit meinen Fäusten zu unterhalten, stellt Euch hinten an. Ansonsten könnte ich Eure Hilfe gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29577] = { id = 29577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashyos Vision", description = "Seht Euch das mal an!\n\n<Ashyo zeigt zum mächtigen Wasserfall im Norden.>\n\nDas muss wohl die Wasserzufuhr für das gesamte Tal sein!\n\nDenkt mal darüber nach, {name}: Die Pandaren pflanzen mit diesem Wasser Gemüse an, das so groß ist wie ein Haus. Wie ist das möglich? Was ist das Geheimnis?\n\nDie Alten meines Volkes kennen eine Methode, um mit dem Wasser zu sprechen und die Zukunft vorherzusagen. Vielleicht gewährt die gleiche Technik auch Einblicke in den Ursprung dieses Gewässers...\n\nEs wäre zumindest einen Versuch wert!", sourceObjective = "Sprecht mit Ashyo bei den Teichen der Reinheit und beobachtet sein Ritual.", completion = "Ich kann kaum glauben, dass er das mit einem Stock sehen konnte... Vielleicht steckt doch mehr hinter den \"verrückten Jinyuritualen\" als wir dachten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29578] = { id = 29578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widerstand", description = "Die verfluchten Mogu sind wie aus dem Nichts über uns hergefallen! Wen sie nicht sofort töten, den zerren sie fort in die Wälder.\n\nDas hier ist der einzige sichere Unterschlupf, und ich kann nichts anderes tun, als die Tür zuzuhalten.\n\nWas sagt Ihr? Seid Ihr willens, für die Schwachen einzustehen und für sie zu kämpfen?", sourceObjective = "Tötet 8 Gormaliplünderer und 8 Gormaliverbrenner im Obstgarten Nektarhauch.", completion = "Gute Arbeit. Doch es gibt noch mehr zu tun, wenn wir dieses Dorf retten wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29579] = { id = 29579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versammelt die Überlebenden", description = "Die Einwohner dieses Dorfes sind einfache Bauern - keine Kämpfer wie Ihr und ich. Dennoch verteidigen sie hartnäckig ihr Zuhause so gut sie eben können.\n\nDurchsucht das Dorf nach allen, die noch aufrecht stehen können und sagt ihnen, sie sollen sich hier bei Hanae versammeln.", sourceObjective = "Sprecht mit 5 Bauern von Nektarhauch in der Umgebung vom Obstgarten Nektarhauch und schickt sie zum sicheren Unterschlupf.", completion = "Sie sind drinnen. Aufgewühlt, aber dank Euch lebendig.", sourceObjectiveStatus = "unverified-source-field" }
quests[29580] = { id = 29580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geräte aus dem Obstgarten", description = "Sie mögen keine Waffenmeister sein, doch viele dieser Bauern können eine einfache Hacke oder einen Rechen schwingen, um ihrem Willen Ausdruck zu verleihen.\n\nDiese Meisterschaft in Verbindung mit der richtigen Motivation kann eine Armee auf die Beine stellen, die in der Lage ist, den Mogu die Stirn zu bieten.\n\nWenn Ihr einige Werkzeuge aus dem Obstgarten herholt, werde ich sie an die Kampfwilligen verteilen.", sourceObjective = "Bergt 6 Obstgartenwerkzeuge aus dem Obstgarten Nektarhauch.", progress = "Waren noch Werkzeuge da?", completion = "Unter uns gibt es niemanden wie Euch, {class}, doch wir werden kämpfen und die, die wir lieben, beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29581] = { id = 29581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der goldene Traum", description = "Ashyo muss das erlebt haben, was wir den goldenen Traum nennen.\n\nViele von uns, die hier arbeiten, haben ihn auch gesehen - häufig nach einem langen Arbeitstag in den Teichen. Man sagt, diese Vision - und das Hochgefühl, das sie bringt - sei eine Belohnung des Geistes für die Nutzung des Körpers.\n\nEs gibt jedoch auch eine einfachere Methode, die wir allerdings kaum noch nutzen: Man kann einen Tee aus Lotuswurzeln und Traumlaub, das in der Nähe des Schreins im oberen Bereich zu finden ist, herstellen.\n\nBringt das Traumlaub in das Dorf zu Yan - er wird Euch den Tee zubereiten.", sourceObjective = "Bringt einen Traumlaubzweig zu Yan in Neu-Cifera.", progress = "Ja, braucht Ihr etwas?", completion = "Ah... Traumlaub! Ihr wollt also den goldenen Traum sehen, nicht wahr?\n\nWenn ich jetzt so darüber nachdenke, fällt mir auf, dass ich den Traum seit Jahren nicht mehr geträumt habe - zuletzt in meinen jungen Jahren beim stundenlangen Spielen in den Teichen. Lange bevor ich mich den kulinarischen Künsten widmete.\n\nWie es aussieht, habt Ihr genügend Traumlaub für zwei Tassen Tee mitgebracht... Hmm, warum nicht?\n\nAuf bessere Zeiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[29582] = { id = 29582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greks verrückte Nacht", description = "Grek hatte gestern ziemlich üble Nacht.\n\nGlänzender Mumienmann kam in Greks Haus und sagte, Grek solle zu Managruft in Auchindoun gehen. Aber Grek versuchte noch Steckbrief zu lesen!\n\n<Greks Augen beginnen zu leuchten.>\n\nGrek weiß! Ihr gehen zu glänzendem Mumienmann und sagt ihm, Grek schickt Euch. Perfekter Plan!", sourceObjective = "Sprecht mit Konstrukteur Morphalius in der Managruft in Auchindoun.", completion = "Der Hohlschädel hat stattdessen Euch geschickt?\n\n<Konstrukteur Morphalius mustert Euch.>\n\nDann werdet Ihr wohl genügen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29583] = { id = 29583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eckert der Verrückte", description = "Ich bin ein erfahrener Ingenieur, ein brillanter Erfinder, der Mittelpunkt jeder Party und der beste Tänzer, den es jemals in Azeroth gegeben hat.\n\nAber nennt mich jemand so? Nein.\n\nDa hat man nur eine Begegnung mit einem Astralen und auf einmal nennt einen die ganze Welt \"den Verrückten\".\n\nGenau hier habe ich gestern einen gesehen, das schwöre ich! Er sagte, ich müsste ihm nur zur Managruft in Auchindoun folgen, dann würde ich einen gewaltigen Schatz bekommen und uraltes Wissen erlangen!", sourceObjective = "Sprecht mit Konstrukteur Morphalius in der Managruft in Auchindoun.", completion = "Ich hatte wirklich gehofft, dass der Gnom, den ich aufgesucht habe, meinem Ruf folgen würde.\n\n<Konstrukteur Morphalius mustert Euch.>\n\nNa ja, Ihr müsst mir genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29585] = { id = 29585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerspeier", description = "Wir kümmern uns seit Generationen um diese Obstgärten und stellen aus dem Nektar Most her. In all der Zeit haben wir gelernt, wie wir ein Feuer im Handumdrehen löschen können.\n\n<Hanae drückt Euch einen Krug Apfelmost in die Hand.>\n\nDer Apfelmost wird klebrig und dickflüssig, wenn man ihn mit zerstoßenem Ingwerblatt und Spucke vermischt. Damit lassen sich Feuer gut löschen.\n\nBitte, könnt Ihr versuchen, die Flammen unter Kontrolle zu bringen, wenn Ihr da draußen seid? Ich habe schon Ingwerblatt daruntergemischt, Ihr müsst nur noch hineinspucken.", sourceObjective = "Nutzt den Nektarhauchmost, um 12 Feuer im Obstgarten Nektarhauch zu löschen.", completion = "Eben war jemand hier und sagte, dass die Flammen langsam erlöschen.\n\nWir sind Euch zu großem Dank verpflichtet. Ich kann Euch unmöglich angemessen belohnen, aber nehmt das doch bitte.", sourceObjectiveStatus = "unverified-source-field" }
quests[29586] = { id = 29586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gesplitterte Pfad", description = "Zuerst... vor den Kriegsschreien... hörten wir die Bäume.\n\nSie stöhnten, knarrten und stürzten schließlich zu Boden, als die Mogu sich den Weg durch den Wald bahnten. Sie machten sich den Rückweg leichter...\n\nSie zerren unsere Freunde auf diesem Weg zurück zu den Ruinen westlich des Dorfes! Diese Ruinen waren seit Jahren verlassen – unsere Kinder spielen dort.\n\nWarum sollten die Mogu jetzt dorthin zurückkehren?", sourceObjective = "Folgt dem Weg der gefallenen Bäume von der Nordwestecke des Obstgartens Nektarhauch aus und findet das Lager der Moguräuber.", completion = "Das sieht nicht nach einer schnellen Entführung aus. Die haben etwas Größeres im Sinn.", sourceObjectiveStatus = "unverified-source-field" }
quests[29587] = { id = 29587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungebunden", sourceObjective = "Befreit 10 gefesselte Bauern von Nektarhauch im Lager Gormal.", completion = "Die Pandaren waren in alten Zeiten der Moguregentschaft unterworfen - das werden wir nie wieder zulassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29590] = { id = 29590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Totenwächter", description = "Ein schreckliches, überirdisches Wesen sucht die Welt der Geister und die der Lebenden heim. Wir nennen es Shirrak.\n\nEs kann nur in Eurem Reich verletzt werden. Bitte helft uns, diesen Alptraum zu beenden.", sourceObjective = "Tötet Shirrak den Totenwächter und kehrt zu dem Draeneigeist zurück.", completion = "Vielleicht werden wir jetzt endlich Frieden finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29591] = { id = 29591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wütende Geister", description = "Die Auchenai haben all unseren Werten den Rücken gekehrt. Sie erwecken die Toten und halten sie als ihre unheiligen Diener!\n\nDas muss ein Ende haben. Bringt diesen Geistern den Frieden und tötet alle, die sie zu Untoten gemacht haben.", sourceObjective = "Tötet 5 erboste Skelette, 5 tobende Skelette und 3 Totenbeschwörer der Auchenai. Kehrt dann zur gequälten Seelenpriesterin in der Auchenaikrypta zurück.", completion = "Die Toten gehören ins Reich der Geister, so wie Ihr in dieses Reich gehört.", sourceObjectiveStatus = "unverified-source-field" }
quests[29593] = { id = 29593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft sie, wo es schmerzt", description = "Die Höllenorcs lagern eine Menge Vorräte hier.\n\nEs würde ihren Feldzug empfindlich treffen und unserem deutlich helfen, wenn sie gestohlen würden. Traut Ihr Euch das zu, {class}?", sourceObjective = "Stehlt 3 Stapel Vorräte der Höllenfeuerhalbinsel und kehrt zu Steingardist Stok'ton im Höllenfeuerbollwerk zurück.", progress = "Wie viele Vorräte konntet Ihr mitnehmen?", completion = "Sehr gut! Langfristig wird dieser Angriff weit schwerwiegendere Konsequenzen haben als der Tod von ein paar Orcs.", sourceObjectiveStatus = "unverified-source-field" }
quests[29594] = { id = 29594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft sie, wo es schmerzt", description = "Die Höllenorcs lagern eine Menge Vorräte hier.\n\nEs würde ihren Feldzug empfindlich treffen und unserem deutlich helfen, wenn sie gestohlen würden. Traut Ihr Euch das zu, {class}?", sourceObjective = "Stehlt 3 Stapel Vorräte der Höllenfeuerhalbinsel und kehrt zu Vorhutsspäher Chadwick im Höllenfeuerbollwerk zurück.", progress = "Wie viele Vorräte konntet Ihr mitnehmen?", completion = "Sehr gut! Langfristig wird dieser Angriff weit schwerwiegendere Konsequenzen haben als der Tod von ein paar Orcs.", sourceObjectiveStatus = "unverified-source-field" }
quests[29595] = { id = 29595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles wird gut", description = "Da habt Ihr ja ein ziemliches Abenteuer hinter Euch, {name}. Dabei habt Ihr die Auchenaikrypta noch nicht einmal betreten.\n\nIch bin einer der glücklichen Geister. Ich war nie an Levixus gebunden, noch war ich Teil von Exarch Maladaars verwerflichen Experimenten in der Nekromantie. Levixus habt Ihr bereits vernichtet, aber Maladaar quält weiter die Geister in der Krypta.\n\nIch habe eine simple Bitte an Euch. Betretet die Auchenaikrypta und sprecht mit dem Draeneigeist dort. Ihr müsst Exarch Maladaar vernichten.", sourceObjective = "Großvater Aldrimus außerhalb der Auchenaikrypta von Auchindoun möchte, dass Ihr in die Auchenaikrypta geht und Exarch Maladaar vernichtet.", completion = "Willkommen in der Auchenaikrypta, {name}. Unsere beiden Welten treffen sich hier.", sourceObjectiveStatus = "unverified-source-field" }
